window._relGerarCentral = function(centralName, tipo) {
  const niveis = _relNiveisSelecionados('an-rel-central-niv');
  if (!niveis) { alert('Selecione ao menos um nível de criticidade.'); return; }
  document.getElementById('an-rel-central-modal').classList.remove('open');
  if (tipo === 'acoes') gerarRelatorioComAcoes(centralName, niveis);
  else                  gerarRelatorioCentral(centralName, niveis);
};

// ═══════════════════════════════════════════════════════════════════
// HELPER — resolve ações para um material/variação
// Retorna a string de ações da regra mais próxima do valor, ou null
// ═══════════════════════════════════════════════════════════════════

function _resolverAcoesParaMaterial(materialNome, variacao, categoriaItem, nivelItem, catKeyItem, catSubKeyItem) {
  const regras = (state.acoesRelatorio || []);
  if (!regras.length) return null;

  // Helper: normaliza string para comparação
  const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();

  // Mapeamento: valor do checkbox → catKey(s) ou catSubKey(s) usados pelo sistema
  // Prioridade: catSubKey (distingue miúdo/graúdo) > catKey (agregado genérico)
  const CHECKBOX_TO_KEYS = {
    'agregados miudos':   { subKeys: ['agregado_miudo'],  fallbackKey: null },
    'agregados graudos':  { subKeys: ['agregado_graudo'], fallbackKey: null },
    'aglomerantes':       { subKeys: [],                  fallbackKey: 'aglomerante' },
    'aditivos e adicoes': { subKeys: [],                  fallbackKey: ['aditivo', 'adicao'] },
  };

  // Tenta match por categoria + nível (novo formato)
  const nivelNorm  = norm(nivelItem || '');
  const catKeyNorm    = norm(catKeyItem || '');
  const catSubKeyNorm = norm(catSubKeyItem || '');

  const porCategoriaNivel = regras.filter(r => {
    if (!Array.isArray(r.categorias) || !r.nivel) return false;
    const matchNivel = norm(r.nivel) === nivelNorm;
    if (!matchNivel) return false;

    const matchCat = r.categorias.some(c => {
      const map = CHECKBOX_TO_KEYS[norm(c)];
      if (!map) return false;
      // Match por subKey (miúdo/graúdo) se disponível
      if (map.subKeys.length && catSubKeyNorm) {
        return map.subKeys.includes(catSubKeyNorm);
      }
      // Match por catKey genérico (aglomerante, aditivo, adicao)
      const fk = map.fallbackKey;
      if (!fk) return false;
      if (Array.isArray(fk)) return fk.includes(catKeyNorm);
      return fk === catKeyNorm;
    });
    return matchCat;
  });

  if (porCategoriaNivel.length) {
    return porCategoriaNivel[0].acoes;
  }

  // Compatibilidade retroativa: tenta match pelo nome do material + operador/valor (formato antigo)
  const legado = regras.filter(r => {
    if (!r.material || !r.operador) return false;
    const normA = norm(r.material);
    const normM = norm(materialNome);
    return normA === normM;
  });

  if (!legado.length) return null;

  const avaliarRegra = (r) => {
    const v = Number(r.valor);
    switch (r.operador) {
      case 'lt':  return variacao <  v;
      case 'lte': return variacao <= v;
      case 'eq':  return Math.abs(variacao - v) < 0.001;
      case 'gte': return variacao >= v;
      case 'gt':  return variacao >  v;
      default:    return false;
    }
  };

  const candidatas = legado.filter(avaliarRegra);
  if (!candidatas.length) return null;

  candidatas.sort((a, b) => Math.abs(Number(a.valor) - variacao) - Math.abs(Number(b.valor) - variacao));
  return candidatas[0].acoes;
}

// ═══════════════════════════════════════════════════════════════════
// RELATÓRIO POR CENTRAL (níveis selecionados no modal) — Relatório Padrão
// (mesmo shell escuro dos relatórios de Ranking/Ausência: _buildRankingShellHTML)
// ═══════════════════════════════════════════════════════════════════

window.gerarRelatorioCentral = function(centralName, niveis) {
  const byLevel = window._rankByLevel;
  if (!byLevel) { alert('Nenhum dado de criticidade disponível. Execute a análise primeiro.'); return; }

  const sel = _relNiveisNorm(niveis, ['critico','urgente','atencao']);
  const filter = item => item.central === centralName;
  const itensPorNivel = {};
  sel.forEach(k => { itensPorNivel[k] = (byLevel[k] || []).filter(filter); });
  const todosItens = sel.flatMap(k => itensPorNivel[k]);

  if (!todosItens.length) {
    alert('Nenhum material nos níveis selecionados para esta central.');
    return;
  }

  const periodo = _getAnPeriodo();
  const now = new Date().toLocaleString('pt-BR');

  function fmtKgC(v) { const n=Math.abs(Number(v)||0); return n.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})+' kg'; }
  function varDir(v) { return v<-0.001?'Desfalque':v>0.001?'Sobra':'Equil.'; }
  function varDirColor(v) { return v<-0.001?'#f87171':v>0.001?'#4ade80':'#94a3b8'; }
  function trendLabel(t) { return t==='worsening'?'▲ Piorando':t==='improving'?'▼ Melhorando':'→ Estável'; }
  function trendColor(t) { return t==='worsening'?'#f87171':t==='improving'?'#4ade80':'#94a3b8'; }
  function escC(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

  function buildRows(items) {
    return items.map((item,idx) => {
      const dc=varDirColor(item.diff); const tc=trendColor(item.trend);
      return `<tr class="data-row">
        <td class="rank-cell">${idx+1}</td>
        <td class="mat-cell"><span class="mat-name">${escC(item.mat)}</span></td>
        <td class="var-cell" style="color:${dc}"><strong>${varDir(item.diff)}</strong><br><span style="font-size:11px">${fmtKgC(item.diff)}</span></td>
        <td class="trend-cell" style="color:${tc}">${trendLabel(item.trend)}</td>
      </tr>`;
    }).join('');
  }

  const _lvlGrad = {
    '#ef4444': 'linear-gradient(135deg,#7f1d1d 0%,#991b1b 60%,#b91c1c 100%)',
    '#f97316': 'linear-gradient(135deg,#7c2d12 0%,#9a3412 60%,#c2410c 100%)',
    '#f59e0b': 'linear-gradient(135deg,#78350f 0%,#92400e 60%,#b45309 100%)',
    '#10b981': 'linear-gradient(135deg,#064e3b 0%,#065f46 60%,#047857 100%)',
  };
  const _lvlGlow = {
    '#ef4444': 'rgba(239,68,68,0.35)',
    '#f97316': 'rgba(249,115,22,0.35)',
    '#f59e0b': 'rgba(245,158,11,0.30)',
    '#10b981': 'rgba(16,185,129,0.28)',
  };

  function buildLevelSection(items, color, icon, label, sublabel) {
    const grad = _lvlGrad[color] || ('linear-gradient(135deg,' + color + ' 0%,' + color + 'cc 100%)');
    const glow = _lvlGlow[color] || (color + '55');
    return (
      '<div style="margin-bottom:28px;border-radius:12px;overflow:hidden;box-shadow:0 4px 20px ' + glow + ';page-break-inside:avoid">' +
        '<div style="background:' + grad + ';padding:20px 26px;display:flex;align-items:center;justify-content:space-between;position:relative;overflow:hidden">' +
          '<div style="position:absolute;right:-20px;top:-20px;width:100px;height:100px;border-radius:50%;background:rgba(255,255,255,0.06);pointer-events:none"></div>' +
          '<div style="position:absolute;right:50px;bottom:-32px;width:64px;height:64px;border-radius:50%;background:rgba(255,255,255,0.04);pointer-events:none"></div>' +
          '<div style="display:flex;align-items:center;gap:16px;position:relative">' +
            '<div style="width:52px;height:52px;border-radius:13px;background:rgba(255,255,255,0.13);border:1.5px solid rgba(255,255,255,0.22);display:flex;align-items:center;justify-content:center;font-size:24px;flex-shrink:0">' + icon + '</div>' +
            '<div>' +
              '<div style="font-size:20px;font-weight:900;color:#fff;letter-spacing:.07em;line-height:1;text-transform:uppercase">' + label + '</div>' +
              '<div style="font-size:12px;color:rgba(255,255,255,0.62);margin-top:5px;font-weight:500">' + sublabel + '</div>' +
            '</div>' +
          '</div>' +
          '<span style="background:rgba(255,255,255,0.15);border:1.5px solid rgba(255,255,255,0.25);color:#fff;padding:6px 16px;border-radius:24px;font-size:13px;font-weight:800;letter-spacing:.03em;position:relative">' + items.length + ' ' + (items.length>1?'materiais':'material') + '</span>' +
        '</div>' +
        '<div style="background:rgba(255,255,255,.02);border:1px solid rgba(255,255,255,.09);border-top:none">' +
          '<table class="data-table"><thead><tr><th style="width:36px">#</th><th>Material</th><th>Variação</th><th>Tendência</th></tr></thead><tbody>' + buildRows(items) + '</tbody></table>' +
        '</div>' +
      '</div>'
    );
  }

  const secCfg = {
    critico: { color:'#ef4444', icon:'🔴', label:'CRÍTICO', sub:'Ação imediata — escalar à gerência' },
    urgente: { color:'#f97316', icon:'🟠', label:'URGENTE', sub:'Atenção redobrada — repassar aos regionais' },
    atencao: { color:'#f59e0b', icon:'⚠️', label:'ATENÇÃO', sub:'Monitorar — contatar operador' },
    bom:     { color:'#10b981', icon:'🟢', label:'BOM',     sub:'Dentro do esperado — sem ação necessária' },
  };

  const sectionsHtml = sel.map(k => {
    const items = itensPorNivel[k];
    if (!items.length) return '';
    const c = secCfg[k];
    return buildLevelSection(items, c.color, c.icon, c.label, c.sub);
  }).join('');

  const totalGeral = todosItens.length;
  const regional = todosItens[0]?.regional || '—';
  const niveisLabel = sel.map(k => secCfg[k].label).join(' · ');

  const infoBar = `
    <div class="crit-info-bar">
      <div class="crit-info-item"><span class="crit-info-label">Central</span><span class="crit-info-value">${escC(centralName)}</span></div>
      <div style="width:1px;height:28px;background:rgba(255,255,255,.1)"></div>
      <div class="crit-info-item"><span class="crit-info-label">Regional</span><span class="crit-info-value">${escC(regional)}</span></div>
      <div style="width:1px;height:28px;background:rgba(255,255,255,.1)"></div>
      <div class="crit-info-item"><span class="crit-info-label">Níveis exibidos</span><span class="crit-info-value">${niveisLabel}</span></div>
      <div style="width:1px;height:28px;background:rgba(255,255,255,.1)"></div>
      <div class="crit-info-item"><span class="crit-info-label">Total de materiais</span><span class="crit-info-value">${totalGeral} ${totalGeral!==1?'materiais':'material'}</span></div>
    </div>`;

  const bodyHtml = `
    <style>
      ${_criticidadeMatTableStyles()}
      .crit-info-bar { display:flex; align-items:center; gap:16px; background:rgba(255,255,255,.04); border:1px solid rgba(255,255,255,.09); border-radius:10px; padding:12px 16px; margin-bottom:22px; flex-wrap:wrap; }
      .crit-info-item { display:flex; flex-direction:column; gap:2px; }
      .crit-info-label { font-size:9.5px; color:#64748b; text-transform:uppercase; letter-spacing:.06em; }
      .crit-info-value { font-size:12.5px; color:#e2e8f0; font-weight:600; }
    </style>
    ${infoBar}
    ${sectionsHtml}`;

  const html = _buildRankingShellHTML({
    periodoBadge: periodo,
    periodo, now,
    kpis: [
      ...sel.map(k => {
        const n = _REL_NIVEIS.find(x => x.key === k);
        return { value: itensPorNivel[k].length, label: n.plural, color: n.kpiColor };
      }),
      { value: totalGeral, label: 'total', color: '#94a3b8' }
    ]
  }, {
    pageTitle:  `Relatório Central — ${centralName}`,
    badge:      'Alerta de Criticidade',
    title:      `Relatório de Central — ${centralName}`,
    subtitle:   `${escC(regional)} · materiais ${_relNiveisTexto(sel)}, por nível de prioridade.`,
    bodyHtml,
    notaRodape: 'Níveis calculados a partir do desequilíbrio (desfalque/sobra) entre estoque físico e lançamentos no período selecionado.'
  });

  _openRelWindow(html);
};

// ═══════════════════════════════════════════════════════════════════
// RELATÓRIO COM AÇÕES — igual ao Padrão + coluna de ações por material
// (mesmo shell escuro dos relatórios de Ranking/Ausência: _buildRankingShellHTML)
// ═══════════════════════════════════════════════════════════════════

window.gerarRelatorioComAcoes = function(centralName, niveis) {
  const byLevel = window._rankByLevel;
  if (!byLevel) { alert('Nenhum dado de criticidade disponível. Execute a análise primeiro.'); return; }

  const sel = _relNiveisNorm(niveis, ['critico','urgente','atencao']);
  const filter = item => item.central === centralName;
  const itensPorNivel = {};
  sel.forEach(k => { itensPorNivel[k] = (byLevel[k] || []).filter(filter); });

  if (!sel.some(k => itensPorNivel[k].length)) {
    alert('Nenhum material nos níveis selecionados para esta central.');
    return;
  }

  const totalRegras = (state.acoesRelatorio || []).length;
  if (!totalRegras) {
    if (!confirm('Nenhuma regra cadastrada em Configurações → Ações de Relatório.\nO relatório será gerado sem ações associadas. Continuar?')) return;
  }

  const periodo = _getAnPeriodo();
  const now = new Date().toLocaleString('pt-BR');

  function fmtKgC(v) { const n=Math.abs(Number(v)||0); return n.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})+' kg'; }
  function varDir(v)  { return v < -0.001 ? 'Desfalque' : v > 0.001 ? 'Sobra' : 'Equilibrado'; }
  function varColor(v){ return v < -0.001 ? '#f87171'   : v > 0.001 ? '#fbbf24' : '#94a3b8'; }
  function trendLabel(t){ return t==='worsening' ? '▲ Piorando' : t==='improving' ? '▼ Melhorando' : '→ Estável'; }
  function trendColor(t){ return t==='worsening' ? '#f87171' : t==='improving' ? '#4ade80' : '#94a3b8'; }
  function escC(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

  // Monta cards de material — layout vertical, sem tabela
  function buildCards(items, levelColor, levelBg, levelKey) {
    return items.map((item, idx) => {
      const acoes  = _resolverAcoesParaMaterial(item.mat, item.diff, item.categoria, levelKey || item.level, item.catKey, item.catSubKey);
      const vc     = varColor(item.diff);
      const tc     = trendColor(item.trend);
      const hasAcao = acoes !== null;

      const acoesItems = hasAcao
        ? acoes.split(/[;|\n]/).map(a => a.trim()).filter(Boolean)
        : [];

      const acoesBullets = acoesItems.map(a =>
        '<li style="margin-bottom:5px;padding-left:4px;word-break:break-word;overflow-wrap:break-word">' + escC(a) + '</li>'
      ).join('');

      const acoesBlock = hasAcao
        ? '<div style="margin-top:14px;padding-top:14px;border-top:1px solid rgba(255,255,255,.08)">' +
            '<div style="display:flex;align-items:center;gap:7px;margin-bottom:10px">' +
              '<span style="width:20px;height:20px;border-radius:50%;background:rgba(34,197,94,.15);border:1.5px solid rgba(34,197,94,.4);display:flex;align-items:center;justify-content:center;flex-shrink:0;font-size:11px;color:#4ade80">✓</span>' +
              '<span style="font-size:11px;font-weight:700;color:#4ade80;text-transform:uppercase;letter-spacing:.06em">Ações propostas</span>' +
            '</div>' +
            '<ul style="margin:0;padding-left:18px;font-size:13px;color:#e2e8f0;line-height:1.7;word-break:break-word;overflow-wrap:break-word">' + acoesBullets + '</ul>' +
          '</div>'
        : '<div style="margin-top:14px;padding-top:14px;border-top:1px solid rgba(255,255,255,.06);display:flex;align-items:center;gap:7px">' +
            '<span style="width:20px;height:20px;border-radius:50%;background:rgba(255,255,255,.04);border:1.5px solid rgba(255,255,255,.12);display:flex;align-items:center;justify-content:center;flex-shrink:0;font-size:11px;color:#64748b">—</span>' +
            '<span style="font-size:12px;color:#64748b;font-style:italic">Sem regra cadastrada para esta variação</span>' +
          '</div>';

      return '<div style="background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.09);border-left:4px solid ' + levelColor + ';border-radius:10px;padding:18px 20px;margin-bottom:12px;page-break-inside:avoid;overflow:hidden;word-break:break-word">' +

        '<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:12px">' +
          '<div style="display:flex;align-items:center;gap:10px">' +
            '<span style="width:26px;height:26px;border-radius:7px;background:' + levelBg + ';color:' + levelColor + ';font-size:11px;font-weight:800;font-family:\'JetBrains Mono\',monospace;display:flex;align-items:center;justify-content:center;flex-shrink:0">' + (idx+1) + '</span>' +
            '<span style="font-size:15px;font-weight:700;color:#fff">' + escC(item.mat) + '</span>' +
          '</div>' +
          (hasAcao
            ? '<span style="padding:3px 10px;border-radius:20px;font-size:10px;font-weight:700;background:rgba(34,197,94,.15);color:#4ade80;border:1px solid rgba(34,197,94,.4);white-space:nowrap;flex-shrink:0">✓ Com ação</span>'
            : '<span style="padding:3px 10px;border-radius:20px;font-size:10px;font-weight:600;background:rgba(255,255,255,.04);color:#64748b;border:1px solid rgba(255,255,255,.12);white-space:nowrap;flex-shrink:0">Sem ação</span>'
          ) +
        '</div>' +

        '<div style="display:flex;gap:10px;flex-wrap:wrap">' +
          '<div style="display:flex;align-items:center;gap:7px;padding:7px 12px;border-radius:8px;background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.08);min-width:160px">' +
            '<div>' +
              '<div style="font-size:10px;color:#64748b;font-weight:600;text-transform:uppercase;letter-spacing:.05em;margin-bottom:2px">Variação</div>' +
              '<div style="font-size:14px;font-weight:800;color:' + vc + ';font-family:\'JetBrains Mono\',monospace">' + varDir(item.diff) + '</div>' +
              '<div style="font-size:12px;font-weight:500;color:' + vc + ';font-family:\'JetBrains Mono\',monospace">' + fmtKgC(item.diff) + '</div>' +
            '</div>' +
          '</div>' +
          '<div style="display:flex;align-items:center;gap:7px;padding:7px 12px;border-radius:8px;background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.08);min-width:140px">' +
            '<div>' +
              '<div style="font-size:10px;color:#64748b;font-weight:600;text-transform:uppercase;letter-spacing:.05em;margin-bottom:2px">Tendência</div>' +
              '<div style="font-size:13px;font-weight:700;color:' + tc + '">' + trendLabel(item.trend) + '</div>' +
            '</div>' +
          '</div>' +
        '</div>' +

        acoesBlock +
      '</div>';
    }).join('');
  }

  const lvlCfg = {
    critico: { color:'#f87171', bg:'rgba(239,68,68,.16)', grad:'linear-gradient(135deg,#7f1d1d 0%,#991b1b 60%,#b91c1c 100%)', glow:'rgba(239,68,68,0.30)', icon:'🔴', label:'CRÍTICO', sub:'Ação imediata — escalar à gerência' },
    urgente: { color:'#fb923c', bg:'rgba(249,115,22,.16)', grad:'linear-gradient(135deg,#7c2d12 0%,#9a3412 60%,#c2410c 100%)', glow:'rgba(249,115,22,0.28)', icon:'🟠', label:'URGENTE', sub:'Atenção redobrada — repassar aos regionais' },
    atencao: { color:'#fbbf24', bg:'rgba(245,158,11,.16)', grad:'linear-gradient(135deg,#78350f 0%,#92400e 60%,#b45309 100%)', glow:'rgba(245,158,11,0.25)', icon:'⚠️', label:'ATENÇÃO', sub:'Monitorar — contatar operador' },
    bom:     { color:'#34d399', bg:'rgba(16,185,129,.16)', grad:'linear-gradient(135deg,#064e3b 0%,#065f46 60%,#047857 100%)', glow:'rgba(16,185,129,0.24)', icon:'🟢', label:'BOM',     sub:'Dentro do esperado — sem ação necessária' },
  };

  function buildLevelSection(items, cfg, levelKey) {
    if (!items.length) return '';
    const cards = buildCards(items, cfg.color, cfg.bg, levelKey);
    return '<div style="margin-bottom:32px;border-radius:14px;overflow:hidden;box-shadow:0 4px 24px ' + cfg.glow + ';page-break-inside:avoid">' +
      '<div style="background:' + cfg.grad + ';padding:20px 28px;display:flex;align-items:center;justify-content:space-between;position:relative;overflow:hidden">' +
        '<div style="position:absolute;right:-20px;top:-20px;width:110px;height:110px;border-radius:50%;background:rgba(255,255,255,0.06);pointer-events:none"></div>' +
        '<div style="display:flex;align-items:center;gap:16px;position:relative">' +
          '<div style="width:52px;height:52px;border-radius:13px;background:rgba(255,255,255,0.13);border:1.5px solid rgba(255,255,255,0.22);display:flex;align-items:center;justify-content:center;font-size:24px;flex-shrink:0">' + cfg.icon + '</div>' +
          '<div>' +
            '<div style="font-size:20px;font-weight:900;color:#fff;letter-spacing:.06em;line-height:1;text-transform:uppercase">' + cfg.label + '</div>' +
            '<div style="font-size:12px;color:rgba(255,255,255,0.65);margin-top:5px;font-weight:500">' + cfg.sub + '</div>' +
          '</div>' +
        '</div>' +
        '<span style="background:rgba(255,255,255,0.15);border:1.5px solid rgba(255,255,255,0.25);color:#fff;padding:7px 18px;border-radius:24px;font-size:13px;font-weight:800;position:relative">' + items.length + ' ' + (items.length > 1 ? 'materiais' : 'material') + '</span>' +
      '</div>' +
      '<div style="background:rgba(255,255,255,.015);padding:16px 20px;border:1px solid rgba(255,255,255,.09);border-top:none">' +
        cards +
      '</div>' +
    '</div>';
  }

  const allItems = sel.flatMap(k => itensPorNivel[k]);
  const totalGeral = allItems.length;
  const regional   = allItems[0]?.regional || '—';
  const comAcoes   = allItems.filter(i => _resolverAcoesParaMaterial(i.mat, i.diff, i.categoria, i.level, i.catKey, i.catSubKey) !== null).length;
  const semAcoes   = totalGeral - comAcoes;

  const sectionsHtml = sel.map(k => buildLevelSection(itensPorNivel[k], lvlCfg[k], k)).join('');
  const niveisLabel  = sel.map(k => lvlCfg[k].label).join(' · ');

  const infoBar = `
    <div class="crit-info-bar">
      <div class="crit-info-item"><span class="crit-info-label">Central</span><span class="crit-info-value">${escC(centralName)}</span></div>
      <div style="width:1px;height:28px;background:rgba(255,255,255,.1)"></div>
      <div class="crit-info-item"><span class="crit-info-label">Regional</span><span class="crit-info-value">${escC(regional)}</span></div>
      <div style="width:1px;height:28px;background:rgba(255,255,255,.1)"></div>
      <div class="crit-info-item"><span class="crit-info-label">Níveis exibidos</span><span class="crit-info-value">${niveisLabel}</span></div>
      <div style="width:1px;height:28px;background:rgba(255,255,255,.1)"></div>
      <div class="crit-info-item"><span class="crit-info-label">Total de materiais</span><span class="crit-info-value">${totalGeral}</span></div>
      <div style="width:1px;height:28px;background:rgba(255,255,255,.1)"></div>
      <div class="crit-info-item"><span class="crit-info-label">Regras cadastradas</span><span class="crit-info-value">${totalRegras}</span></div>
    </div>`;

  const bodyHtml = `
    <style>
      .crit-info-bar { display:flex; align-items:center; gap:16px; background:rgba(255,255,255,.04); border:1px solid rgba(255,255,255,.09); border-radius:10px; padding:12px 16px; margin-bottom:22px; flex-wrap:wrap; }
      .crit-info-item { display:flex; flex-direction:column; gap:2px; }
      .crit-info-label { font-size:9.5px; color:#64748b; text-transform:uppercase; letter-spacing:.06em; }
      .crit-info-value { font-size:12.5px; color:#e2e8f0; font-weight:600; }
    </style>
    ${infoBar}
    ${sectionsHtml}`;

  const html = _buildRankingShellHTML({
    periodoBadge: periodo,
    periodo, now,
    kpis: [
      ...sel.map(k => {
        const n = _REL_NIVEIS.find(x => x.key === k);
        return { value: itensPorNivel[k].length, label: n.plural, color: n.kpiColor };
      }),
      { value: comAcoes,        label: 'com ação',  color: '#22c55e' },
      { value: semAcoes,        label: 'sem ação',  color: '#64748b' }
    ]
  }, {
    pageTitle:  `Relatório com Ações — ${centralName}`,
    badge:      'Cobrança de Pendências',
    title:      `Relatório com Ações — ${centralName}`,
    subtitle:   `${escC(regional)} · materiais ${_relNiveisTexto(sel)}, com ações corretivas propostas por regra cadastrada.`,
    bodyHtml,
    notaRodape: 'Ações resolvidas a partir das regras cadastradas em Configurações → Ações de Relatório, pela combinação de material, categoria, nível e faixa de variação mais próxima.'
  });

  _openRelWindow(html);
};

// ═══════════════════════════════════════════════════════════════════════════════
// RELATÓRIO GERENCIAL DE OCORRÊNCIAS — visão executiva para diretoria
// ═══════════════════════════════════════════════════════════════════════════════
// RELATÓRIO GERENCIAL DE OCORRÊNCIAS — visão executiva (mesmo shell escuro dos
// relatórios de Ranking/Ausência: _buildRankingShellHTML)
// ═══════════════════════════════════════════════════════════════════════════════
window.gerarRelatorioGeralOcorrencias = function() {
  const lista = (state.ocorrencias || []);
  if (!lista.length) {
    alert('Nenhuma ocorrência cadastrada para gerar o relatório.');
    return;
  }

  const now    = new Date().toLocaleString('pt-BR');
  const nowISO = new Date().toISOString().split('T')[0]; // YYYY-MM-DD de hoje

  // ── helpers ─────────────────────────────────────────────────────────────────
  function escR(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

  // Dias entre duas datas ISO (b - a), inteiro
  function diffDays(aISO, bISO) {
    if (!aISO || !bISO) return null;
    const a = new Date(aISO + 'T00:00:00'), b = new Date(bISO + 'T00:00:00');
    if (isNaN(a) || isNaN(b)) return null;
    return Math.round((b - a) / 86400000);
  }

  function ocStatus(o) {
    if (o.concluida) return 'concluida';
    if (!o.dataLimite) return 'normal';
    const d = diffDays(nowISO, o.dataLimite);
    if (d < 0)  return 'vencida';
    if (d <= 2) return 'urgente';
    return 'normal';
  }

  // ── mapeamento central → regional via state.filiais ──────────────────────────
  const centralParaRegional = {};
  (state.filiais || []).forEach(f => {
    const key = (f.origem || f.alias || '').trim().toLowerCase();
    if (key) centralParaRegional[key] = (f.regional || '').trim() || 'Sem Regional';
  });
  function getRegional(central) {
    return centralParaRegional[(central||'').trim().toLowerCase()] || 'Sem Regional';
  }

  // ── KPIs globais ──────────────────────────────────────────────────────────────
  const total      = lista.length;
  const concluidas = lista.filter(o => o.concluida).length;
  const abertas    = total - concluidas;
  const vencidas   = lista.filter(o => ocStatus(o) === 'vencida').length;
  const urgentes   = lista.filter(o => ocStatus(o) === 'urgente').length;
  const normais    = abertas - vencidas - urgentes;
  const pctConc    = total > 0 ? Math.round(concluidas / total * 100) : 0;
  const pctVenc    = abertas > 0 ? Math.round(vencidas / abertas * 100) : 0;

  // Semáforo: vermelho se >30% vencidas dentre abertas, amarelo se >10%, verde se ok
  const semaforoColor = pctVenc > 30 ? '#ef4444' : pctVenc > 10 ? '#f59e0b' : '#22c55e';
  const semaforoLabel = pctVenc > 30 ? 'CRÍTICO' : pctVenc > 10 ? 'ATENÇÃO' : 'NORMAL';
  const semaforoDesc  = pctVenc > 30
    ? `${pctVenc}% das ocorrências abertas estão com prazo vencido — ação imediata necessária.`
    : pctVenc > 10
    ? `${pctVenc}% das ocorrências abertas estão vencidas — acompanhamento necessário.`
    : `Situação sob controle. ${pctVenc}% de vencimento entre as abertas.`;

  // Tempo médio de conclusão (abertura→conclusão, em dias)
  let tempoTotal = 0, tempoCount = 0;
  lista.forEach(o => {
    if (!o.concluida || !o.dataAbertura || !o.dataConclusao) return;
    const d = diffDays(o.dataAbertura, o.dataConclusao);
    if (d === null || d < 0) return;
    tempoTotal += d; tempoCount++;
  });
  const tempoMedio = tempoCount > 0 ? (tempoTotal / tempoCount).toFixed(1) : null;

  // ── KPIs por regional ─────────────────────────────────────────────────────────
  const porRegional = {};
  lista.forEach(o => {
    const reg = getRegional(o.central);
    if (!porRegional[reg]) porRegional[reg] = { total:0, abertas:0, vencidas:0, urgentes:0, concluidas:0, tempoTotal:0, tempoCount:0 };
    const r = porRegional[reg];
    r.total++;
    const st = ocStatus(o);
    if (o.concluida) { r.concluidas++; }
    else             { r.abertas++;    }
    if (st === 'vencida') r.vencidas++;
    if (st === 'urgente') r.urgentes++;
    if (o.concluida && o.dataAbertura && o.dataConclusao) {
      const d = diffDays(o.dataAbertura, o.dataConclusao);
      if (d !== null && d >= 0) { r.tempoTotal += d; r.tempoCount++; }
    }
  });

  // Ordena: mais vencidas primeiro, depois mais urgentes
  const regionaisOrdenados = Object.entries(porRegional).sort((a, b) => {
    const scoreA = a[1].vencidas * 1000 + a[1].urgentes * 100 + a[1].abertas;
    const scoreB = b[1].vencidas * 1000 + b[1].urgentes * 100 + b[1].abertas;
    return scoreB - scoreA;
  });

  // ── KPIs por motivo ───────────────────────────────────────────────────────────
  const porMotivo = {};
  lista.forEach(o => {
    const m = (o.motivo || '').trim() || 'Sem motivo';
    if (!porMotivo[m]) porMotivo[m] = { total:0, abertas:0, vencidas:0 };
    porMotivo[m].total++;
    if (!o.concluida) porMotivo[m].abertas++;
    if (ocStatus(o) === 'vencida') porMotivo[m].vencidas++;
  });
  const motivosOrdenados = Object.entries(porMotivo).sort((a, b) => b[1].total - a[1].total);
  const maxMotivo = motivosOrdenados[0]?.[1]?.total || 1;

  // ── Top centrais com mais abertas ─────────────────────────────────────────────
  const porCentral = {};
  lista.forEach(o => {
    const c = o.central || '—';
    if (!porCentral[c]) porCentral[c] = { total:0, abertas:0, vencidas:0, urgentes:0 };
    porCentral[c].total++;
    if (!o.concluida) porCentral[c].abertas++;
    if (ocStatus(o) === 'vencida') porCentral[c].vencidas++;
    if (ocStatus(o) === 'urgente') porCentral[c].urgentes++;
  });
  const topCentrals = Object.entries(porCentral)
    .sort((a, b) => (b[1].vencidas * 100 + b[1].urgentes * 10 + b[1].abertas) - (a[1].vencidas * 100 + a[1].urgentes * 10 + a[1].abertas))
    .slice(0, 12);
  const maxCentral = topCentrals[0]?.[1]?.total || 1;

  // ── Pior regional (para meta no header) ──────────────────────────────────────
  const piorRegional = regionaisOrdenados[0];

  // ── Builders de seção (tema escuro) ──────────────────────────────────────────
  function buildRegionalRow([reg, r]) {
    const tm = r.tempoCount > 0 ? (r.tempoTotal / r.tempoCount).toFixed(1) : '—';
    const pctR = r.total > 0 ? Math.round(r.concluidas / r.total * 100) : 0;
    const barW = r.total > 0 ? Math.round(r.concluidas / r.total * 100) : 0;
    const rowBg = r.vencidas > 0 ? 'rgba(239,68,68,.06)' : r.urgentes > 0 ? 'rgba(245,158,11,.06)' : 'transparent';
    const vencColor = r.vencidas > 0 ? '#f87171' : '#64748b';
    const urgColor  = r.urgentes > 0 ? '#fbbf24' : '#64748b';
    return `
    <tr style="background:${rowBg}">
      <td class="rk-name" style="font-size:12px">${escR(reg)}</td>
      <td class="rk-num">${r.total}</td>
      <td class="rk-num" style="color:#93c5fd">${r.abertas}</td>
      <td class="rk-num" style="color:${vencColor}">${r.vencidas}</td>
      <td class="rk-num" style="color:${urgColor}">${r.urgentes}</td>
      <td class="rk-num" style="font-size:11px;color:#cbd5e1">${tm === '—' ? '—' : tm + 'd'}</td>
      <td style="min-width:130px">
        <div style="display:flex;align-items:center;gap:8px">
          <div class="oc-bar-track"><div class="oc-bar-fill" style="width:${barW}%;background:#22c55e"></div></div>
          <span style="font-size:10.5px;font-family:'JetBrains Mono',monospace;color:#94a3b8;min-width:30px;text-align:right">${pctR}%</span>
        </div>
      </td>
    </tr>`;
  }

  function buildMotivoRow([motivo, m], idx) {
    const barW = Math.round(m.total / maxMotivo * 100);
    const vColor = m.vencidas > 0 ? '#f87171' : '#64748b';
    return `
    <tr>
      <td class="rk-num" style="color:#64748b;font-size:10px">${idx+1}</td>
      <td class="rk-name" style="font-size:11.5px">${escR(motivo)}</td>
      <td style="min-width:150px">
        <div style="display:flex;align-items:center;gap:8px">
          <div class="oc-bar-track"><div class="oc-bar-fill" style="width:${barW}%;background:#3b82f6"></div></div>
          <span style="font-size:10.5px;font-family:'JetBrains Mono',monospace;color:#94a3b8;min-width:22px;text-align:right">${m.total}</span>
        </div>
      </td>
      <td class="rk-num" style="color:#93c5fd">${m.abertas}</td>
      <td class="rk-num" style="color:${vColor}">${m.vencidas}</td>
    </tr>`;
  }

  function buildCentralRow([central, c], idx) {
    const barW = Math.round(c.total / maxCentral * 100);
    const reg = getRegional(central);
    const vColor = c.vencidas > 0 ? '#f87171' : '#64748b';
    const uColor = c.urgentes > 0 ? '#fbbf24' : '#64748b';
    const rowBg = c.vencidas > 0 ? 'rgba(239,68,68,.06)' : c.urgentes > 0 ? 'rgba(245,158,11,.06)' : 'transparent';
    return `
    <tr style="background:${rowBg}">
      <td class="rk-num" style="color:#64748b;font-size:10px">${idx+1}</td>
      <td class="rk-name" style="font-size:12px">${escR(central)}</td>
      <td class="rk-sub" style="margin-top:0">${escR(reg)}</td>
      <td style="min-width:120px">
        <div style="display:flex;align-items:center;gap:8px">
          <div class="oc-bar-track"><div class="oc-bar-fill" style="width:${barW}%;background:#818cf8"></div></div>
          <span style="font-size:10.5px;font-family:'JetBrains Mono',monospace;color:#94a3b8;min-width:18px;text-align:right">${c.total}</span>
        </div>
      </td>
      <td class="rk-num" style="color:#93c5fd">${c.abertas}</td>
      <td class="rk-num" style="color:${vColor}">${c.vencidas}</td>
      <td class="rk-num" style="color:${uColor}">${c.urgentes}</td>
    </tr>`;
  }

  // ── bodyHtml ──────────────────────────────────────────────────────────────────
  const bodyHtml = `
    <style>
      .oc-semaforo { border-radius:10px; padding:16px 22px; display:flex; align-items:center; gap:16px; margin-bottom:22px; }
      .oc-semaforo-dot { width:16px; height:16px; border-radius:50%; flex-shrink:0; }
      .oc-semaforo-label { font-size:14px; font-weight:800; letter-spacing:.04em; }
      .oc-semaforo-desc { font-size:11.5px; color:#94a3b8; margin-top:3px; }

      .oc-highlight { background:rgba(255,255,255,.045); border:1px solid rgba(255,255,255,.09); border-radius:12px; padding:20px 24px; margin-bottom:24px; display:flex; align-items:center; gap:32px; flex-wrap:wrap; }
      .oc-highlight-label { font-size:10.5px; color:#94a3b8; text-transform:uppercase; letter-spacing:.06em; }
      .oc-highlight-value { font-family:'JetBrains Mono',monospace; font-weight:800; font-size:38px; color:#4ade80; line-height:1; margin-top:4px; }
      .oc-highlight-value small { font-size:16px; font-weight:400; color:#94a3b8; margin-left:4px; }
      .oc-highlight-sub { font-size:10.5px; color:#64748b; margin-top:4px; }
      .oc-highlight-divider { width:1px; height:56px; background:rgba(255,255,255,.1); flex-shrink:0; }
      .oc-highlight-stats { display:flex; flex-direction:column; gap:8px; flex:1; min-width:220px; }
      .oc-highlight-row { display:flex; justify-content:space-between; font-size:11.5px; }
      .oc-highlight-row span:first-child { color:#94a3b8; }
      .oc-highlight-row strong { font-family:'JetBrains Mono',monospace; }

      .oc-bar-track { flex:1; height:5px; background:rgba(255,255,255,.09); border-radius:3px; overflow:hidden; }
      .oc-bar-fill { height:100%; border-radius:3px; }
    </style>

    <div class="oc-semaforo" style="background:${semaforoColor}18;border:1px solid ${semaforoColor}40">
      <div class="oc-semaforo-dot" style="background:${semaforoColor};box-shadow:0 0 10px ${semaforoColor}80"></div>
      <div>
        <div class="oc-semaforo-label" style="color:${semaforoColor}">${semaforoLabel}</div>
        <div class="oc-semaforo-desc">${escR(semaforoDesc)}${piorRegional ? ` · Regional com mais atenção: <strong style="color:#e2e8f0">${escR(piorRegional[0])}</strong>` : ''}</div>
      </div>
    </div>

    ${tempoMedio !== null ? `
    <div class="oc-highlight">
      <div>
        <div class="oc-highlight-label">Tempo médio de conclusão</div>
        <div class="oc-highlight-value">${tempoMedio}<small>dias</small></div>
        <div class="oc-highlight-sub">média entre as ${tempoCount} ocorrência${tempoCount!==1?'s':''} concluídas com datas</div>
      </div>
      <div class="oc-highlight-divider"></div>
      <div class="oc-highlight-stats">
        <div class="oc-highlight-row"><span>Ocorrências abertas</span><strong style="color:#93c5fd">${abertas}</strong></div>
        <div class="oc-highlight-row"><span>Vencidas (prazo expirado)</span><strong style="color:#f87171">${vencidas}</strong></div>
        <div class="oc-highlight-row"><span>Urgentes (vencem em até 2 dias)</span><strong style="color:#fbbf24">${urgentes}</strong></div>
        <div class="oc-highlight-row"><span>Em prazo normal</span><strong style="color:#a5b4fc">${normais}</strong></div>
      </div>
    </div>` : ''}

    <div class="rk-table-wrap">
      <div class="rk-table-head">
        <div class="rk-table-head-title">Situação por Regional</div>
        <div class="rk-table-head-cap">${regionaisOrdenados.length} ${regionaisOrdenados.length!==1?'regionais':'regional'} · ordenado por criticidade</div>
      </div>
      <table class="rk-table">
        <thead>
          <tr>
            <th>Regional</th><th style="text-align:center">Total</th><th style="text-align:center">Em Aberto</th>
            <th style="text-align:center">Vencidas</th><th style="text-align:center">Urgentes</th>
            <th style="text-align:center">Tempo Médio</th><th>% Concluídas</th>
          </tr>
        </thead>
        <tbody>${regionaisOrdenados.map(buildRegionalRow).join('')}</tbody>
      </table>
    </div>

    <div class="rk-table-wrap">
      <div class="rk-table-head">
        <div class="rk-table-head-title">Ranking de Centrais</div>
        <div class="rk-table-head-cap">top ${topCentrals.length} por volume e criticidade</div>
      </div>
      <table class="rk-table">
        <thead>
          <tr>
            <th style="width:28px">#</th><th>Central</th><th>Regional</th><th>Volume</th>
            <th style="text-align:center">Em Aberto</th><th style="text-align:center">Vencidas</th><th style="text-align:center">Urgentes</th>
          </tr>
        </thead>
        <tbody>${topCentrals.map(buildCentralRow).join('')}</tbody>
      </table>
    </div>

    <div class="rk-table-wrap">
      <div class="rk-table-head">
        <div class="rk-table-head-title">Distribuição por Motivo</div>
        <div class="rk-table-head-cap">${motivosOrdenados.length} motivo${motivosOrdenados.length!==1?'s':''}</div>
      </div>
      <table class="rk-table">
        <thead>
          <tr><th style="width:28px">#</th><th>Motivo</th><th>Volume</th><th style="text-align:center">Em Aberto</th><th style="text-align:center">Vencidas</th></tr>
        </thead>
        <tbody>${motivosOrdenados.map(buildMotivoRow).join('')}</tbody>
      </table>
    </div>`;

  const d = {
    periodoBadge: now.split(' ')[0],
    periodo: 'Base completa de ocorrências',
    now,
    kpis: [
      { value: total,           label: 'total de ocorrências', color: '#94a3b8' },
      { value: abertas,         label: 'em aberto',            color: '#3b82f6' },
      { value: vencidas,        label: 'vencidas',              color: '#ef4444' },
      { value: urgentes,        label: 'urgentes',              color: '#f59e0b' },
      { value: pctConc + '%',   label: 'concluídas',            color: '#22c55e' }
    ]
  };

  const html = _buildRankingShellHTML(d, {
    pageTitle:  'Relatório Gerencial de Ocorrências',
    badge:      'Relatório Gerencial',
    title:      'Painel de Ocorrências — Situação Geral',
    subtitle:   'Visão executiva de abertura, prazos e conclusão de todas as ocorrências registradas.',
    bodyHtml,
    notaRodape: 'Vencida: prazo expirado. Urgente: vence em até 2 dias. Tempo médio calculado apenas entre ocorrências concluídas com data de abertura e conclusão registradas.'
  });

  _openRelWindow(html);
};

// ═══════════════════════════════════════════════════════════════════════════════
// RELATÓRIO DE DAIs (31/07) — todas as Documento de Ajuste de Inventário já
// geradas + dashboard gerencial com KPIs SMART (Específicos/Mensuráveis/
// Atingíveis/Relevantes/Temporais — todos calculados sobre dados que já
// existem em state.ajustesSistemicos/state.ocorrencias, sem inventar campo
// novo). Mesmo shell dos demais relatórios gerenciais (_buildRankingShellHTML)
// e mesma estrutura de gerarRelatorioGeralOcorrencias logo acima — só troca
// a fonte de dados de ocorrências pra DAIs.
// ═══════════════════════════════════════════════════════════════════════════════
window.gerarRelatorioDAIs = function() {
  const lista = (state.ajustesSistemicos || []);
  if (!lista.length) {
    alert('Nenhuma DAI cadastrada para gerar o relatório.');
    return;
  }

  const now = new Date().toLocaleString('pt-BR');
  function escR(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
  function diffDays(aISO, bISO) {
    if (!aISO || !bISO) return null;
    const a = new Date(aISO + 'T00:00:00'), b = new Date(bISO + 'T00:00:00');
    if (isNaN(a) || isNaN(b)) return null;
    return Math.round((b - a) / 86400000);
  }

  const centralParaRegional = {};
  (state.filiais || []).forEach(f => {
    const key = (f.origem || f.alias || '').trim().toLowerCase();
    if (key) centralParaRegional[key] = (f.regional || '').trim() || 'Sem Regional';
  });
  function getRegional(central) {
    return centralParaRegional[(central||'').trim().toLowerCase()] || 'Sem Regional';
  }

  // Pendente = algum item ainda sem Nº do documento SAP (mesmo critério já
  // usado no modal de detalhe — ver openOcDetailModal em ocorrencias.js).
  function daiItens(dai) { return (typeof _daiGetItens === 'function') ? _daiGetItens(dai) : (dai.itens || []); }
  function daiPendente(dai) { return daiItens(dai).some(it => !it.sapDocumento || it.sapDocumento === 'PENDENTE'); }
  function daiDataGeracaoISO(dai) { return dai.dataGeracao ? new Date(dai.dataGeracao).toISOString().split('T')[0] : null; }
  // Conclusão de uma DAI = maior dataConclusao entre as ocorrências vinculadas
  // (uma por item, quando "ocorrência por item" foi usada na geração).
  function daiDataConclusaoISO(dai) {
    const ocs = (state.ocorrencias || []).filter(o => o.daiId === dai.id && o.concluida && o.dataConclusao);
    if (!ocs.length) return null;
    return ocs.map(o => o.dataConclusao).sort().pop();
  }

  // ── KPIs globais (SMART) ────────────────────────────────────────────────
  const total       = lista.length;
  const pendentes    = lista.filter(daiPendente).length;
  const concluidas   = total - pendentes;
  const pctConc      = total > 0 ? Math.round(concluidas / total * 100) : 0;
  const pctPend      = total > 0 ? Math.round(pendentes / total * 100) : 0;

  let tempoTotal = 0, tempoCount = 0;
  lista.forEach(dai => {
    if (daiPendente(dai)) return;
    const d = diffDays(daiDataGeracaoISO(dai), daiDataConclusaoISO(dai));
    if (d === null || d < 0) return;
    tempoTotal += d; tempoCount++;
  });
  const tempoMedio = tempoCount > 0 ? (tempoTotal / tempoCount).toFixed(1) : null;

  const semaforoColor = pctPend > 30 ? '#ef4444' : pctPend > 10 ? '#f59e0b' : '#22c55e';
  const semaforoLabel = pctPend > 30 ? 'CRÍTICO' : pctPend > 10 ? 'ATENÇÃO' : 'NORMAL';
  const semaforoDesc  = pctPend > 30
    ? `${pctPend}% das DAIs ainda aguardam o Nº do documento SAP — ação imediata necessária.`
    : pctPend > 10
    ? `${pctPend}% das DAIs aguardam o Nº do documento SAP — acompanhamento necessário.`
    : `Situação sob controle. ${pctPend}% de pendência entre as DAIs geradas.`;

  // ── por Regional ─────────────────────────────────────────────────────────
  const porRegional = {};
  lista.forEach(dai => {
    const reg = (dai.regionalCentral || '').trim() || getRegional(dai.central);
    if (!porRegional[reg]) porRegional[reg] = { total:0, pendentes:0, concluidas:0 };
    const r = porRegional[reg];
    r.total++;
    if (daiPendente(dai)) r.pendentes++; else r.concluidas++;
  });
  const regionaisOrdenados = Object.entries(porRegional).sort((a, b) =>
    (b[1].pendentes * 100 + b[1].total) - (a[1].pendentes * 100 + a[1].total)
  );

  // ── Ranking de centrais ──────────────────────────────────────────────────
  const porCentral = {};
  lista.forEach(dai => {
    const c = dai.central || '—';
    if (!porCentral[c]) porCentral[c] = { total:0, pendentes:0 };
    porCentral[c].total++;
    if (daiPendente(dai)) porCentral[c].pendentes++;
  });
  const topCentrals = Object.entries(porCentral).sort((a, b) => b[1].total - a[1].total).slice(0, 12);
  const maxCentral = topCentrals[0]?.[1]?.total || 1;

  // ── linhas de tabela ──────────────────────────────────────────────────────
  function buildRegionalRow([reg, r]) {
    const pctR = r.total > 0 ? Math.round(r.concluidas / r.total * 100) : 0;
    const rowBg = r.pendentes > 0 ? 'rgba(245,158,11,.06)' : 'transparent';
    return `
    <tr style="background:${rowBg}">
      <td class="rk-name" style="font-size:12px">${escR(reg)}</td>
      <td class="rk-num">${r.total}</td>
      <td class="rk-num" style="color:${r.pendentes>0?'#fbbf24':'#64748b'}">${r.pendentes}</td>
      <td class="rk-num" style="color:#4ade80">${r.concluidas}</td>
      <td style="min-width:130px">
        <div style="display:flex;align-items:center;gap:8px">
          <div class="oc-bar-track"><div class="oc-bar-fill" style="width:${pctR}%;background:#22c55e"></div></div>
          <span style="font-size:10.5px;font-family:'JetBrains Mono',monospace;color:#94a3b8;min-width:30px;text-align:right">${pctR}%</span>
        </div>
      </td>
    </tr>`;
  }

  function buildCentralRow([central, c], idx) {
    const barW = Math.round(c.total / maxCentral * 100);
    const reg = getRegional(central);
    return `
    <tr style="background:${c.pendentes>0?'rgba(245,158,11,.06)':'transparent'}">
      <td class="rk-num" style="color:#64748b;font-size:10px">${idx+1}</td>
      <td class="rk-name" style="font-size:12px">${escR(central)}</td>
      <td class="rk-sub" style="margin-top:0">${escR(reg)}</td>
      <td style="min-width:120px">
        <div style="display:flex;align-items:center;gap:8px">
          <div class="oc-bar-track"><div class="oc-bar-fill" style="width:${barW}%;background:#818cf8"></div></div>
          <span style="font-size:10.5px;font-family:'JetBrains Mono',monospace;color:#94a3b8;min-width:18px;text-align:right">${c.total}</span>
        </div>
      </td>
      <td class="rk-num" style="color:${c.pendentes>0?'#fbbf24':'#64748b'}">${c.pendentes}</td>
    </tr>`;
  }

  const daisOrdenadas = lista.slice().sort((a, b) => (b.dataGeracao||0) - (a.dataGeracao||0));
  function buildDaiRow(dai) {
    const pendente = daiPendente(dai);
    const reg = (dai.regionalCentral || '').trim() || getRegional(dai.central);
    return `
    <tr style="background:${pendente?'rgba(245,158,11,.06)':'transparent'}">
      <td class="rk-name" style="font-size:11.5px">${escR(dai.tag || dai.numero || '—')}</td>
      <td class="rk-sub" style="margin-top:0;font-family:'JetBrains Mono',monospace">${escR(dai.numero || '—')}</td>
      <td class="rk-name" style="font-size:11.5px;font-weight:600">${escR(dai.central || '—')}</td>
      <td class="rk-sub" style="margin-top:0">${escR(reg)}</td>
      <td style="font-size:11px;color:#cbd5e1">${dai.dataGeracao ? new Date(dai.dataGeracao).toLocaleDateString('pt-BR') : '—'}</td>
      <td style="font-size:11px;color:#cbd5e1">${escR(dai.analista || '—')}</td>
      <td style="font-size:11px;color:#94a3b8">${escR(dai.material || '—')}</td>
      <td style="text-align:center">
        <span style="display:inline-block;padding:2px 9px;border-radius:5px;font-size:9.5px;font-weight:800;letter-spacing:.04em;text-transform:uppercase;${pendente ? 'background:rgba(245,158,11,.16);color:#fbbf24' : 'background:rgba(34,197,94,.16);color:#4ade80'}">${pendente ? 'Pendente' : 'Concluída'}</span>
      </td>
    </tr>`;
  }

  // ── bodyHtml ──────────────────────────────────────────────────────────────
  const bodyHtml = `
    <style>
      .oc-semaforo { border-radius:10px; padding:16px 22px; display:flex; align-items:center; gap:16px; margin-bottom:22px; }
      .oc-semaforo-dot { width:16px; height:16px; border-radius:50%; flex-shrink:0; }
      .oc-semaforo-label { font-size:14px; font-weight:800; letter-spacing:.04em; }
      .oc-semaforo-desc { font-size:11.5px; color:#94a3b8; margin-top:3px; }

      .oc-highlight { background:rgba(255,255,255,.045); border:1px solid rgba(255,255,255,.09); border-radius:12px; padding:20px 24px; margin-bottom:24px; display:flex; align-items:center; gap:32px; flex-wrap:wrap; }
      .oc-highlight-label { font-size:10.5px; color:#94a3b8; text-transform:uppercase; letter-spacing:.06em; }
      .oc-highlight-value { font-family:'JetBrains Mono',monospace; font-weight:800; font-size:38px; color:#4ade80; line-height:1; margin-top:4px; }
      .oc-highlight-value small { font-size:16px; font-weight:400; color:#94a3b8; margin-left:4px; }
      .oc-highlight-sub { font-size:10.5px; color:#64748b; margin-top:4px; }
      .oc-highlight-divider { width:1px; height:56px; background:rgba(255,255,255,.1); flex-shrink:0; }
      .oc-highlight-stats { display:flex; flex-direction:column; gap:8px; flex:1; min-width:220px; }
      .oc-highlight-row { display:flex; justify-content:space-between; font-size:11.5px; }
      .oc-highlight-row span:first-child { color:#94a3b8; }
      .oc-highlight-row strong { font-family:'JetBrains Mono',monospace; }

      .oc-bar-track { flex:1; height:5px; background:rgba(255,255,255,.09); border-radius:3px; overflow:hidden; }
      .oc-bar-fill { height:100%; border-radius:3px; }
    </style>

    <div class="oc-semaforo" style="background:${semaforoColor}18;border:1px solid ${semaforoColor}40">
      <div class="oc-semaforo-dot" style="background:${semaforoColor};box-shadow:0 0 10px ${semaforoColor}80"></div>
      <div>
        <div class="oc-semaforo-label" style="color:${semaforoColor}">${semaforoLabel}</div>
        <div class="oc-semaforo-desc">${escR(semaforoDesc)}</div>
      </div>
    </div>

    ${tempoMedio !== null ? `
    <div class="oc-highlight">
      <div>
        <div class="oc-highlight-label">Tempo médio de conclusão</div>
        <div class="oc-highlight-value">${tempoMedio}<small>dias</small></div>
        <div class="oc-highlight-sub">média entre geração e conclusão, ${tempoCount} DAI${tempoCount!==1?'s':''} com datas completas</div>
      </div>
      <div class="oc-highlight-divider"></div>
      <div class="oc-highlight-stats">
        <div class="oc-highlight-row"><span>DAIs criadas</span><strong style="color:#fff">${total}</strong></div>
        <div class="oc-highlight-row"><span>Concluídas (Nº SAP preenchido)</span><strong style="color:#4ade80">${concluidas}</strong></div>
        <div class="oc-highlight-row"><span>Pendentes (aguardando Nº SAP)</span><strong style="color:#fbbf24">${pendentes}</strong></div>
        <div class="oc-highlight-row"><span>% concluídas</span><strong style="color:#93c5fd">${pctConc}%</strong></div>
      </div>
    </div>` : ''}

    <div class="rk-table-wrap">
      <div class="rk-table-head">
        <div class="rk-table-head-title">Situação por Regional</div>
        <div class="rk-table-head-cap">${regionaisOrdenados.length} ${regionaisOrdenados.length!==1?'regionais':'regional'}</div>
      </div>
      <table class="rk-table">
        <thead>
          <tr><th>Regional</th><th style="text-align:center">Total</th><th style="text-align:center">Pendentes</th><th style="text-align:center">Concluídas</th><th>% Concluídas</th></tr>
        </thead>
        <tbody>${regionaisOrdenados.map(buildRegionalRow).join('')}</tbody>
      </table>
    </div>

    <div class="rk-table-wrap">
      <div class="rk-table-head">
        <div class="rk-table-head-title">Ranking de Centrais</div>
        <div class="rk-table-head-cap">top ${topCentrals.length} por volume de DAIs</div>
      </div>
      <table class="rk-table">
        <thead>
          <tr><th style="width:28px">#</th><th>Central</th><th>Regional</th><th>Volume</th><th style="text-align:center">Pendentes</th></tr>
        </thead>
        <tbody>${topCentrals.map(buildCentralRow).join('')}</tbody>
      </table>
    </div>

    <div class="rk-table-wrap">
      <div class="rk-table-head">
        <div class="rk-table-head-title">Todas as DAIs Criadas</div>
        <div class="rk-table-head-cap">${total} documento${total!==1?'s':''} · mais recente primeiro</div>
      </div>
      <table class="rk-table">
        <thead>
          <tr><th>Tag</th><th>Nº Documento</th><th>Central</th><th>Regional</th><th>Geração</th><th>Analista</th><th>Material(is)</th><th style="text-align:center">Status</th></tr>
        </thead>
        <tbody>${daisOrdenadas.map(buildDaiRow).join('')}</tbody>
      </table>
    </div>`;

  const d = {
    periodoBadge: now.split(' ')[0],
    periodo: 'Base completa de DAIs',
    now,
    kpis: [
      { value: total,          label: 'DAIs criadas',    color: '#94a3b8' },
      { value: concluidas,     label: 'concluídas',      color: '#22c55e' },
      { value: pendentes,      label: 'pendentes (SAP)', color: '#f59e0b' },
      { value: pctConc + '%',  label: '% concluídas',    color: '#3b82f6' },
      { value: tempoMedio !== null ? tempoMedio + 'd' : '—', label: 'tempo médio conclusão', color: '#8b5cf6' }
    ]
  };

  const html = _buildRankingShellHTML(d, {
    pageTitle:  'Relatório de DAIs',
    badge:      'Relatório Gerencial',
    title:      'Painel de DAIs — Documentos de Ajuste de Inventário',
    subtitle:   'Visão executiva de todas as DAIs geradas: pendências de Nº SAP, tempo de conclusão e distribuição por regional/central.',
    bodyHtml,
    notaRodape: 'Pendente: DAI com ao menos um item aguardando o Nº do documento SAP. Tempo médio calculado apenas entre DAIs concluídas com data de geração e conclusão registradas.'
  });

  _openRelWindow(html);
};

// ═══════════════════════════════════════════════════════════════════════════════
// RELATÓRIO GERENCIAL DO DASHBOARD GERENCIAL — Visão Geral, para diretoria/
// presidência (mesmo shell escuro dos demais Relatórios Gerenciais:
// _buildRankingShellHTML). Lê window._dgVgLastData (cache populado no fim de
// renderDgVisaoGeralPdf, em dashboard.js) — nunca recalcula nada, garantindo
// que os números do PDF batem exatamente com o que está na tela.
//
// FASE 1: Resumo do Período (KPIs) + Saúde Geral (gauges capturados como
// imagem). FASE 2: Categoria + Custo por Regional/Central (extremos + 2
// gráficos de barra). FASE 3: Custo Absoluto (donut de Grupo + 4 donuts de
// categoria). FASE 4 (final): Giro & Cobertura (Top 5) + Detalhado
// Analítico (tabela de material + 4 rankings, lista completa). Relatório
// completo — todas as 10 seções da Visão Geral.
// ═══════════════════════════════════════════════════════════════════════════════

// ── Rasteriza um <svg> vivo da tela em PNG (data URL), resolvendo as
//    variáveis CSS (var(--text)/var(--text3)/var(--mono)) usadas nesses
//    SVGs para valores literais do tema escuro — o relatório abre numa
//    janela/documento própria, sem acesso às custom properties do app.
//    scale:2 pra ficar nítido tanto na tela quanto impresso. ──────────────
function _dgrSvgParaPngDataUrl(svgEl, scale = 2) {
  return new Promise((resolve) => {
    if (!svgEl) { resolve(null); return; }
    try {
      // Lê o valor JÁ COMPUTADO de --text/--text3 no body ATUAL — antes
      // isso era hardcoded pros hex do tema escuro (sempre), o que fazia
      // os gauges saírem sempre escuros no PDF mesmo com o Dashboard em
      // tema claro. Lendo ao vivo, respeita seja o tema real da tela, seja
      // o tema temporariamente forçado pra captura (ver _dgrCapturarComTema).
      const cs = getComputedStyle(document.body);
      const corText  = (cs.getPropertyValue('--text')  || '').trim()  || '#dde3f0';
      const corText3 = (cs.getPropertyValue('--text3') || '').trim()  || '#404a60';
      let svgStr = new XMLSerializer().serializeToString(svgEl);
      svgStr = svgStr
        .replace(/var\(--text3\)/g, corText3)
        .replace(/var\(--text\)/g, corText)
        .replace(/var\(--mono\)/g, "'JetBrains Mono',monospace");
      if (!svgStr.includes('xmlns=')) {
        svgStr = svgStr.replace('<svg', '<svg xmlns="http://www.w3.org/2000/svg"');
      }
      const vb = svgEl.viewBox && svgEl.viewBox.baseVal;
      const rect = svgEl.getBoundingClientRect();
      const w = (vb && vb.width)  || rect.width  || 300;
      const h = (vb && vb.height) || rect.height || 220;
      const blob = new Blob([svgStr], { type: 'image/svg+xml;charset=utf-8' });
      const url = URL.createObjectURL(blob);
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        canvas.width = w * scale;
        canvas.height = h * scale;
        const ctx = canvas.getContext('2d');
        ctx.scale(scale, scale);
        ctx.drawImage(img, 0, 0, w, h);
        URL.revokeObjectURL(url);
        resolve(canvas.toDataURL('image/png'));
      };
      img.onerror = () => { URL.revokeObjectURL(url); resolve(null); };
      img.src = url;
    } catch (err) {
      console.error('[Relatório Gerencial - Dashboard] Falha ao capturar SVG:', err);
      resolve(null);
    }
  });
}

// ── Captura um <canvas> (Chart.js) já desenhado na tela em PNG — cores
//    já vêm "assadas" nos pixels do canvas, sem depender de CSS var. ─────
function _dgrCanvasParaPngDataUrl(canvasId) {
  const c = document.getElementById(canvasId);
  if (!c) return null;
  try { return c.toDataURL('image/png'); }
  catch (err) { console.error('[Relatório Gerencial - Dashboard] Falha ao capturar canvas', canvasId, err); return null; }
}

// ── Seção 1: Resumo do Período (réplica dos cards de KPI da tela, com
//    cores literais do tema escuro em vez de var(--x) — ver nota acima). ──
function _dgrBuildResumoPeriodoHtml(d) {
  const colorFor = v => v < -0.0001 ? '#f43f5e' : v > 0.0001 ? '#f59e0b' : '#06b6d4';
  const varCol = colorFor(d.varTotalFisica);
  const cstCol = colorFor(d.custoTotal);

  const totalEstTeorico = d.estTotais.totalIni + d.movTotais.totalEnt - d.movTotais.totalSai;
  const pctVariacao = Math.abs(totalEstTeorico) > 0.0001 ? (d.varTotalFisica / totalEstTeorico) * 100 : null;
  const custoEstTeorico = (d.estTotais.custoIni || 0) + (d.custoMovTotais.custoEnt || 0) - (d.custoMovTotais.custoSai || 0);
  const pctCusto = Math.abs(custoEstTeorico) > 0.0001 ? (d.custoTotal / custoEstTeorico) * 100 : null;

  // Evolução = Est. Final Total (SAP) em relação ao Est. Inicial Total
  // (SAP) — usa o teórico (totalEstTeorico/custoEstTeorico, calculado
  // acima), não o medido (estTotais.totalFim/custoFim).
  const kgEvolucao    = totalEstTeorico - d.estTotais.totalIni;
  const custoEvolucao = custoEstTeorico - (d.estTotais.custoIni || 0);
  const pctEvolucao   = Math.abs(d.estTotais.totalIni) > 0.0001 ? (kgEvolucao / d.estTotais.totalIni) * 100 : null;
  const evoCol = colorFor(kgEvolucao);

  const pctStr = p => p === null ? '—' : Math.abs(p).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + '%';

  // Saldo físico do card hero em toneladas (kg ÷ 1.000) — só essa linha,
  // a pedido do Hugo; o resto do relatório (cards secundários, tabela de
  // Detalhamento) continua em kg, que é o grão certo pra aquele nível de
  // detalhe.
  const fmtTon = kg => (kg / 1000).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' ton';

  // Caminhões/Carretas/IBCs (equivalente em veículos da variação física —
  // mesma metodologia da tela, ver veiculosRowHtml em _dgVgRenderKpisHero,
  // dashboard.js) — versão discreta, sem ícone/selo, pra ficar ao lado do
  // saldo em vez de ocupar uma grade grande embaixo (ficava desbalanceado).
  const v = d.veiculosTotalKpi || {};
  const veiculoStat = (label, valor) => `
    <div class="dgr-kpi-veiculo-simples">
      <div class="dgr-kpi-veiculo-simples-valor" style="color:${_dgrValCor(valor)}">${_daFmtCountSigned(valor)}</div>
      <div class="dgr-kpi-veiculo-simples-label">${label}</div>
    </div>`;
  const veiculosHtml = (v.caminhoes || v.carretas || v.ibcs) ? `
    <div class="dgr-kpi-veiculos-simples">
      ${veiculoStat('Caminhões', v.caminhoes)}
      ${veiculoStat('Carretas', v.carretas)}
      ${veiculoStat('IBCs', v.ibcs)}
    </div>` : '';

  // Card secundário padrão (rótulo + selo de ícone colorido no topo, valor
  // grande, subvalor menor).
  const card2 = (label, iconCls, iconCol, valor, sub) => `
    <div class="dgr-kpi-card">
      <div class="dgr-kpi-card-head">
        <div class="dgr-kpi-label">${label}</div>
        <div class="dgr-kpi-icon" style="background:${iconCol}1f;color:${iconCol}"><i class="ti ${iconCls}"></i></div>
      </div>
      <div class="dgr-kpi-value">${valor}</div>
      <div class="dgr-kpi-unit" style="margin-top:8px;padding-top:8px;border-top:1px solid var(--dgr-divider, rgba(255,255,255,.08))">${sub}</div>
    </div>`;

  // Card "Variação Ajustada" — as % de Variação e de Custo Var. separadas
  // do card hero, cada uma com seu mini-rótulo, uma acima da outra.
  const cardVariacaoAjustada = `
    <div class="dgr-kpi-card">
      <div class="dgr-kpi-card-head">
        <div class="dgr-kpi-label">Variação Ajustada</div>
        <div class="dgr-kpi-icon" style="background:${varCol}1f;color:${varCol}"><i class="ti ti-adjustments"></i></div>
      </div>
      ${pctVariacao === null ? '<div class="dgr-kpi-unit">—</div>' : `
      <div class="dgr-kpi-pct" style="color:${varCol}">${varSymbol(d.varTotalFisica)} ${pctStr(pctVariacao)}</div>
      <div class="dgr-kpi-unit">Variação · Est. Final Total (Medição) - Est. Final Total (SAP)</div>`}
      ${pctCusto === null ? '' : `
      <div class="dgr-kpi-divider-row">
        <div class="dgr-kpi-pct-sub" style="color:${cstCol}">${varSymbol(d.custoTotal)} ${pctStr(pctCusto)}</div>
        <div class="dgr-kpi-pct-label">Custo Var. · do Custo Teórico</div>
      </div>`}
    </div>`;

  // Parêntese com o mesmo saldo em toneladas, ao lado do valor em kg —
  // mesma divisão por 1.000 do card hero (fmtTon), só que discreto (menor,
  // cor dim) por ficar colado no valor grande em vez de ser ele.
  const tonAoLado = kg => ` <span style="font-weight:400;font-size:.65em;color:var(--dgr-text-dim2, #64748b)">(${fmtTon(kg)})</span>`;

  // Card "Est. Final Total - Medição" — Saldo Teórico SAP (Est. Inicial +
  // Entradas - Saídas, já calculado acima em totalEstTeorico) em evidência,
  // Saldo Real (o estoqueFim importado, ver _dgVgEstoqueTotais em
  // dashboard.js) abaixo — os dois podem divergir quando há ajuste manual
  // não refletido no SAP.
  const cardEstFinal = `
    <div class="dgr-kpi-card">
      <div class="dgr-kpi-card-head">
        <div class="dgr-kpi-label">Est. Final Total - SAP</div>
        <div class="dgr-kpi-icon" style="background:#3b82f61f;color:#3b82f6"><i class="ti ti-circle-check"></i></div>
      </div>
      <div class="dgr-kpi-value">${fmtKg(totalEstTeorico)}${tonAoLado(totalEstTeorico)}</div>
      <div class="dgr-kpi-unit">${money(custoEstTeorico)}</div>
      <div class="dgr-kpi-divider-row" style="flex-direction:column;align-items:flex-start;gap:2px">
        <div class="dgr-kpi-pct-label">Est. Final Total (Medição)</div>
        <div class="dgr-kpi-pct-sub">${fmtKg(d.estTotais.totalFim)}${tonAoLado(d.estTotais.totalFim)}</div>
      </div>
    </div>`;

  return `
    <div class="dgr-kpi-secondary">
      ${card2('Est. Inicial Total - SAP', 'ti-database', '#94a3b8', fmtKg(d.estTotais.totalIni) + tonAoLado(d.estTotais.totalIni), money(d.estTotais.custoIni || 0))}
      ${card2('Entradas - SAP', 'ti-activity', '#10b981', fmtKg(d.movTotais.totalEnt) + tonAoLado(d.movTotais.totalEnt), money(d.custoMovTotais.custoEnt || 0))}
      ${card2('Saídas - SAP', 'ti-activity', '#f43f5e', fmtKg(d.movTotais.totalSai) + tonAoLado(d.movTotais.totalSai), money(d.custoMovTotais.custoSai || 0))}
      ${cardEstFinal}
      ${card2('Evolução Estoque', 'ti-chart-line', '#8b5cf6', `<span style="color:${evoCol}">${pctEvolucao === null ? '—' : varSymbol(kgEvolucao) + ' ' + pctStr(pctEvolucao)}</span><div class="dgr-kpi-unit" style="margin-top:4px">Evolução · Est. Final Total (SAP) - Est. Inicial Total (SAP)</div>`, `${varSymbol(kgEvolucao)} ${fmtKg(Math.abs(kgEvolucao))}<br>${varSymbol(kgEvolucao)} ${money(Math.abs(custoEvolucao))}`)}
      ${cardVariacaoAjustada}
    </div>
    <div class="dgr-kpi-hero" style="border-top-color:${cstCol}">
      <div class="dgr-kpi-card-head">
        <div class="dgr-kpi-label">Variação Estoque</div>
        <div class="dgr-kpi-icon" style="background:${cstCol}1f;color:${cstCol}"><i class="ti ti-currency-dollar"></i></div>
      </div>
      <div class="dgr-kpi-unit">Est. Final Total (Medição) - Est. Final Total (SAP)</div>
      <div class="dgr-kpi-hero-saldo" style="color:${varCol}">${varSymbol(d.varTotalFisica)} ${fmtKg(Math.abs(d.varTotalFisica))}${tonAoLado(Math.abs(d.varTotalFisica))}</div>
      <div class="dgr-kpi-hero-custo-row">
        <div>
          <div class="dgr-kpi-hero-custo" style="color:${cstCol}">${varSymbol(d.custoTotal)} ${money(Math.abs(d.custoTotal))}</div>
          <div class="dgr-kpi-unit">R$ bruto</div>
        </div>
        ${veiculosHtml}
      </div>
    </div>`;
}

// ── Seção 2: Saúde Geral — Centrais e Materiais (gauges capturados como
//    imagem + badges de contagem por nível, reaproveitados direto do DOM
//    já renderizado — já usam cores literais, só o font-family precisa de
//    resolução). ────────────────────────────────────────────────────────
function _dgrBuildSaudeGeralHtml(imgCentral, imgMateriais) {
  const resolveMono = html => (html || '').replace(/var\(--mono\)/g, "'JetBrains Mono',monospace");
  const summaryCentral   = resolveMono(document.getElementById('dg-vg-health-central-summary')?.innerHTML);
  const summaryMateriais = resolveMono(document.getElementById('dg-vg-health-materiais-summary')?.innerHTML);
  const subCentral    = document.getElementById('dg-vg-health-central-subtitle')?.textContent || '';
  const subMateriais  = document.getElementById('dg-vg-health-materiais-subtitle')?.textContent || '';

  const card = (titulo, iconCls, sub, img, summary) => `
    <div class="dgr-health-card">
      <div class="dgr-health-title"><i class="ti ${iconCls}"></i><span>${_rankEsc(titulo)}</span><span style="margin-left:auto;font-weight:400;color:#64748b;font-size:10px">${_rankEsc(sub)}</span></div>
      ${img ? `<img src="${img}" alt="${_rankEsc(titulo)}">` : '<div style="padding:40px 0;color:#64748b;font-size:11px;text-align:center">Gráfico indisponível</div>'}
      <div class="dgr-health-summary">${summary}</div>
    </div>`;

  return `
    <div class="dgr-health-grid">
      ${card('Saúde Geral — Centrais', 'ti-building-factory-2', subCentral, imgCentral, summaryCentral)}
      ${card('Saúde Geral — Materiais', 'ti-heartbeat', subMateriais, imgMateriais, summaryMateriais)}
    </div>`;
}

// ── Captura do gráfico "Desfalque e Sobra por Categoria" ampliado só pra
//    o relatório: na tela (Visão Geral) esse canvas vive num container de
//    180px de altura, adequado ao card compacto do dashboard, mas que
//    fica espremido quando reaproveitado 1:1 no PDF (poucas linhas de
//    respiro entre as 4 categorias + legenda + eixo). Em vez de mudar a
//    altura fixa da tela (afetaria o dashboard ao vivo), redimensiona o
//    <canvas> e reforça as fontes dos dois plugins/eixos SÓ durante a
//    captura, e devolve tudo ao estado original logo depois — a tela
//    nunca fica visivelmente diferente pro usuário (a troca acontece com
//    o overlay "Gerando relatório..." por cima). chart.update('none') é
//    usado pra pular a animação e desenhar de forma síncrona antes do
//    toDataURL(). ─────────────────────────────────────────────────────
// ── Captura TODOS os gráficos/gauges do Relatório Gerencial já na cor do
//    parâmetro `tema` recebido (fixo, sem modal de escolha — ver
//    abrirModalSelecaoRelatorioGerencial). Duas famílias de gráfico, dois
//    mecanismos diferentes:
//    - Chart.js (categoria/regional/usina): a cor é "assada" em pixel no
//      canvas no momento do render — só trocar o atributo data-theme NÃO
//      redesenha um canvas já pintado. Preciso re-chamar as funções de
//      render (com os dados já cacheados em window._dgVgLastData, sem
//      recalcular nada) DEPOIS de trocar o tema, pra elas lerem a cor
//      nova via _dgVgTheme().
//    - Gauges SVG (Saúde Geral): usam fill="var(--text)" AO VIVO no
//      próprio elemento — o navegador já repinta sozinho assim que
//      data-theme muda, sem precisar re-render explícito. Só a CAPTURA
//      (_dgrSvgParaPngDataUrl) precisa ler o valor computado atual, o que
//      já foi corrigido lá.
//    Tudo isso acontece com o overlay "Gerando relatório..." (z-index
//    9100, cobre a tela inteira incl. sidebar) por cima, então a troca
//    de tema "piscando" pra capturar nunca fica visível pro usuário — a
//    tela volta exatamente como estava antes de o overlay fechar. ───────
async function _dgrCapturarComTema(tema, d) {
  const temaOriginal = document.body.dataset.theme; // undefined = escuro (padrão)

  // Desliga a animação de entrada do Chart.js (globalmente, só durante
  // essa captura) — redesenharGraficos() DESTRÓI e RECRIA os 3 gráficos
  // do zero (_dgVgDestroyChart + new Chart), e por padrão o Chart.js anima
  // as barras crescendo de 0 até o valor final em ~1000ms. Como a captura
  // do canvas (toDataURL) acontece na MESMA sincronia, sem isso ela pega
  // um frame no meio dessa animação — barras minúsculas/cortadas, coladas
  // no zero, exatamente o bug relatado. Restaurado no finally, então o uso
  // normal do Dashboard (botão "Atualizar") continua animando como sempre.
  const animOriginal = (typeof Chart !== 'undefined') ? Chart.defaults.animation : undefined;
  if (typeof Chart !== 'undefined') Chart.defaults.animation = false;

  const redesenharGraficos = () => {
    _dgVgRenderChartCategoriaFisica(d.catFisicaPct);
    _dgVgRenderChartVariacaoPorChave('dg-vg-chart-regional', d.entriesRegional, 'chartRegional');
    _dgVgRenderChartVariacaoPorChave('dg-vg-chart-usina', d.entriesCentral, 'chartUsina');
  };

  try {
    if (tema === 'light') document.body.setAttribute('data-theme', 'light');
    else document.body.removeAttribute('data-theme'); // 'dark' = tema raiz do tokens.css
    redesenharGraficos();

    const [imgGaugeCentral, imgGaugeMateriais] = await Promise.all([
      _dgrSvgParaPngDataUrl(document.getElementById('dg-vg-gauge-central-svg')),
      _dgrSvgParaPngDataUrl(document.getElementById('dg-vg-gauge-chart-svg'))
    ]);
    const imgCategoria = _dgrCapturarCategoriaAmpliada();
    const imgRegional  = _dgrCanvasParaPngDataUrl('dg-vg-chart-regional');
    const imgUsina     = _dgrCanvasParaPngDataUrl('dg-vg-chart-usina');

    return { imgGaugeCentral, imgGaugeMateriais, imgCategoria, imgRegional, imgUsina };
  } finally {
    // Restaura o tema original da TELA (não do relatório) e redesenha os
    // 3 gráficos de novo com a cor de volta — sem isso, o Dashboard ao
    // vivo ficaria preso no tema usado só pra captura. Anima normalmente
    // de novo (ainda com animação desligada, restaurada logo abaixo) —
    // como está tudo atrás do overlay, não faz diferença visual, e evita
    // qualquer chance de o usuário ver o redraw "crescendo" quando o
    // overlay fechar.
    if (temaOriginal) document.body.setAttribute('data-theme', temaOriginal);
    else document.body.removeAttribute('data-theme');
    redesenharGraficos();
    if (typeof Chart !== 'undefined') Chart.defaults.animation = animOriginal;
  }
}

function _dgrCapturarCategoriaAmpliada() {
  const canvas = document.getElementById('dg-vg-chart-categoria');
  // _dgVgCharts é `let` no topo de dashboard.js — NÃO vira propriedade de
  // window (só `var`/funções top-level viram). Como os dois arquivos são
  // <script> clássicos na mesma página, a referência solta (sem "window.")
  // enxerga a mesma variável, porque let/const de nível superior entram
  // num escopo léxico global compartilhado entre scripts, só não em
  // window. window._dgVgCharts (versão anterior) dava sempre undefined,
  // então isso SEMPRE caía no fallback abaixo (canvas cru, 180px, largura
  // total da tela) — o ajuste de altura nunca chegava a rodar de verdade.
  const chart  = (typeof _dgVgCharts !== 'undefined' ? _dgVgCharts : window._dgVgCharts)?.categoria;
  const wrap   = canvas?.parentElement;
  if (!canvas || !chart || !wrap) return _dgrCanvasParaPngDataUrl('dg-vg-chart-categoria');

  // Controla LARGURA e ALTURA da captura — não só a altura. Na tela, esse
  // card é largura cheia do Dashboard (bem mais largo que a coluna do
  // relatório em retrato, ~590px de conteúdo dentro do card). Só mudar a
  // altura (versão anterior) deixava a imagem com proporção larga/rasa
  // (ex.: 1200×460), e ao ser exibida no card mais estreito do relatório
  // via max-width:100%;height:auto, a altura EFETIVA encolhia nessa mesma
  // proporção — voltando a parecer espremida mesmo com 460px "de verdade"
  // na captura. Fixando os dois valores aqui, a proporção da imagem final
  // fica sempre previsível, não importa a largura da tela de quem gerou.
  const LARGURA_RELATORIO = '680px';
  const ALTURA_RELATORIO  = '320px'; // proporção ~0,47 — peso visual parecido com os cards de gauge vizinhos (Saúde Geral), que ficam bem mais compactos
  const larguraOriginal = wrap.style.width;
  const alturaOriginal  = wrap.style.height;

  // Snapshot das fontes/opções originais (todas nascem com os mesmos
  // valores hoje, mas cada uma é restaurada da sua própria referência por
  // segurança caso algum dia divirjam).
  const opts = chart.options;
  const scaleXFontOriginal   = { ...opts.scales.x.ticks.font };
  const scaleYFontOriginal   = { ...opts.scales.y.ticks.font };
  const legendFontOriginal   = { ...opts.plugins.legend.labels.font };
  const totalsFontSizeOriginal = opts.plugins.dgVgCategoryTotals.fontSize;
  const barLabelsFontSizeOriginal = opts.plugins.dgVgBarValueLabels.fontSize;
  const graceOriginal = opts.scales.x.grace;
  const categoryPercentageOriginal = opts.scales.y.categoryPercentage;
  const barPercentageOriginal = opts.scales.y.barPercentage;
  const paddingLeftOriginal  = opts.layout.padding.left;
  const paddingRightOriginal = opts.layout.padding.right;

  let dataUrl = null;
  try {
    wrap.style.width  = LARGURA_RELATORIO;
    wrap.style.height = ALTURA_RELATORIO;

    opts.scales.x.ticks.font = { ...scaleXFontOriginal, size: 13 };
    opts.scales.y.ticks.font = { ...scaleYFontOriginal, size: 14 };
    opts.plugins.legend.labels.font = { ...legendFontOriginal, size: 13 };
    opts.plugins.dgVgCategoryTotals.fontSize = 13;
    opts.plugins.dgVgBarValueLabels.fontSize = 13;

    // Sobreposição "Adição"/"459,5 kg" e "11,0 K kg"/"Δ -5,1 K kg" das
    // capturas anteriores corrigidas na raiz: _dgVgBarValueLabelsPlugin
    // (dashboard.js) agora SEMPRE desenha dentro da barra quando ela tem
    // espaço, ficando contido nos próprios limites dela — não depende
    // mais de calcular o espaço "fora" (frágil, variava com os dados).
    // Esse grace um pouco maior aqui é só respiro visual extra.
    opts.scales.x.grace = '25%';
    // Barras mais finas — pedido do usuário. categoryPercentage controla
    // quanto da "fatia" de cada categoria a barra ocupa (0.8 = padrão do
    // Chart.js); reduzindo, sobra mais respiro vertical entre as linhas
    // e a barra fica visualmente mais fina, sem mudar o comprimento (%).
    opts.scales.y.categoryPercentage = 0.5;
    opts.scales.y.barPercentage = 0.85;
    // Δ (dashboard.js) agora ancora pela borda direita do canvas — nunca
    // mais corta, seja qual for o tamanho do texto. Esse padding.right
    // ainda importa: é o espaço reservado pra essa coluna existir sem
    // "empurrar"/sobrepor a área dos gráficos. Valor generoso de propósito.
    opts.layout.padding.left  = 35;
    opts.layout.padding.right = 125;

    chart.resize();
    chart.update('none'); // sem animação — desenha na hora, síncrono

    dataUrl = _dgrCanvasParaPngDataUrl('dg-vg-chart-categoria');
  } catch (err) {
    console.error('[Relatório Gerencial - Dashboard] Falha ao ampliar gráfico Categoria para captura:', err);
  } finally {
    // Restaura a tela ao estado original, mudando ou não.
    wrap.style.width  = larguraOriginal;
    wrap.style.height = alturaOriginal;
    opts.scales.x.ticks.font = scaleXFontOriginal;
    opts.scales.y.ticks.font = scaleYFontOriginal;
    opts.plugins.legend.labels.font = legendFontOriginal;
    opts.plugins.dgVgCategoryTotals.fontSize = totalsFontSizeOriginal;
    opts.plugins.dgVgBarValueLabels.fontSize = barLabelsFontSizeOriginal;
    opts.scales.x.grace = graceOriginal;
    opts.scales.y.categoryPercentage = categoryPercentageOriginal;
    opts.scales.y.barPercentage = barPercentageOriginal;
    opts.layout.padding.left  = paddingLeftOriginal;
    opts.layout.padding.right = paddingRightOriginal;
    try { chart.resize(); chart.update('none'); } catch (e) { /* noop */ }
  }

  return dataUrl;
}

// ── Seção 3: Desfalque e Sobra por Categoria — gráfico de barra (Chart.js)
//    capturado como imagem; cores já vêm "assadas" nos pixels do canvas,
//    sem depender de CSS var (ver _dgrCanvasParaPngDataUrl). ─────────────
function _dgrBuildCategoriaHtml(imgCategoria) {
  return `
    <div class="dgr-chart-card" style="margin-top:26px">
      <div class="dgr-chart-title"><i class="ti ti-chart-bar"></i>Desfalque e Sobra por Categoria — % do Volume Movimentado</div>
      ${imgCategoria ? `<img src="${imgCategoria}" alt="Desfalque e Sobra por Categoria">` : '<div class="dgr-chart-empty">Gráfico indisponível</div>'}
    </div>`;
}

// ── Seções 4/5/6: Variação por Regional e Central — 4 cards de destaque
//    (extremos, reconstruídos a partir de d.extRegional/d.extCentral já
//    calculados — mesma lógica de _dgVgRenderExtremos em dashboard.js, só
//    com cores literais em vez de var(--x)) + os 2 gráficos de barra
//    (Regional/Central) capturados como imagem. ──────────────────────────
function _dgrBuildCustoRegionalCentralHtml(d, imgRegional, imgUsina) {
  const extremoBox = (label, ext) => {
    if (!ext) return `
      <div class="dgr-extremo-box">
        <div class="dgr-extremo-label">${_rankEsc(label)}</div>
        <div class="dgr-extremo-value" style="color:#64748b">—</div>
        <div class="dgr-extremo-name">Sem dados no período</div>
      </div>`;
    const col = ext.v < 0 ? '#f43f5e' : '#f59e0b';
    return `
      <div class="dgr-extremo-box">
        <div class="dgr-extremo-label">${_rankEsc(label)}</div>
        <div class="dgr-extremo-value" style="color:${col}">${_dgrNowrapNum(`${varSymbol(ext.v)} ${fmtKg(Math.abs(ext.v))}`)}</div>
        <div class="dgr-extremo-kg">${_dgrNowrapNum(`${varSymbol(ext.aux || 0)} ${money(Math.abs(ext.aux || 0))}`)}</div>
        <div class="dgr-extremo-name">${_rankEsc(ext.k)}</div>
      </div>`;
  };

  const extremosHtml =
    extremoBox('Regional · Maior Desfalque', d.extRegional.min && d.extRegional.min.v < 0 ? d.extRegional.min : null) +
    extremoBox('Regional · Maior Sobra',     d.extRegional.max && d.extRegional.max.v > 0 ? d.extRegional.max : null) +
    extremoBox('Central · Maior Desfalque',  d.extCentral.min  && d.extCentral.min.v  < 0 ? d.extCentral.min  : null) +
    extremoBox('Central · Maior Sobra',      d.extCentral.max  && d.extCentral.max.v  > 0 ? d.extCentral.max  : null);

  return `
    <div class="dgr-extremos-grid">${extremosHtml}</div>
    <div class="dgr-chart-grid">
      <div class="dgr-chart-card">
        <div class="dgr-chart-title"><i class="ti ti-users"></i>Variação por Regional</div>
        ${imgRegional ? `<img src="${imgRegional}" alt="Variação por Regional">` : '<div class="dgr-chart-empty">Gráfico indisponível</div>'}
      </div>
      <div class="dgr-chart-card">
        <div class="dgr-chart-title"><i class="ti ti-building-factory-2"></i>Variação por Central</div>
        ${imgUsina ? `<img src="${imgUsina}" alt="Variação por Central">` : '<div class="dgr-chart-empty">Gráfico indisponível</div>'}
      </div>
    </div>`;
}

// ── Seções 7/8: Custo Absoluto — 1 donut combinado (Grupo de Material,
//    em destaque) + 4 donuts de categoria (Agregado/Aglomerante/Aditivo/
//    Adição), todos gerados por _dgVgRenderCustoDonutSvg (mesma função dos
//    gauges de Saúde Geral) e capturados com a mesma técnica de resolução
//    de var(--x) já validada na Fase 1.
//    NÃO CHAMADA ATUALMENTE — removida do corpo do relatório a pedido do
//    Hugo (jul/2026). Função mantida (não deletada) pra reativar rápido
//    caso ele queira essa seção de volta; a captura das imagens
//    correspondentes também foi removida do fluxo principal.
function _dgrBuildCustoAbsolutoHtml(imgGrupo, imgsCat) {
  const subGrupo = document.getElementById('dg-vg-grupo-subtitle')?.textContent || '';
  const catTitulos = {
    agregado: 'Custo Absoluto por Agregado',
    aglomerante: 'Custo Absoluto por Aglomerante',
    aditivo: 'Custo Absoluto por Aditivo',
    adicao: 'Custo Absoluto por Adição'
  };

  const smallCard = catKey => {
    const sub = document.getElementById(`dg-vg-donut-${catKey}-subtitle`)?.textContent || '';
    const img = imgsCat[catKey];
    return `
      <div class="dgr-chart-card dgr-donut-small">
        <div class="dgr-chart-title"><span>${_rankEsc(catTitulos[catKey])}</span><span style="margin-left:auto;font-weight:400;color:#64748b;font-size:10px">${_rankEsc(sub)}</span></div>
        ${img ? `<img src="${img}" alt="${_rankEsc(catTitulos[catKey])}">` : '<div class="dgr-chart-empty">Gráfico indisponível</div>'}
      </div>`;
  };

  return `
    <div class="dgr-section-title" style="margin-top:26px"><i class="ti ti-chart-pie"></i>Custo Absoluto — Por Grupo e Categoria de Material</div>
    <div class="dgr-grupo-layout">
      <div class="dgr-chart-card dgr-donut-grande">
        <div class="dgr-chart-title"><span><i class="ti ti-chart-donut"></i>Custo Absoluto por Grupo de Material</span><span style="margin-left:auto;font-weight:400;color:#64748b;font-size:10px">${_rankEsc(subGrupo)}</span></div>
        ${imgGrupo ? `<img src="${imgGrupo}" alt="Custo Absoluto por Grupo de Material">` : '<div class="dgr-chart-empty">Gráfico indisponível</div>'}
      </div>
      <div class="dgr-donut-sub-grid">
        ${smallCard('agregado')}${smallCard('aglomerante')}${smallCard('aditivo')}${smallCard('adicao')}
      </div>
    </div>`;
}

// ── Seção 9: Giro & Cobertura — Top 5 Centrais/Materiais mais saudáveis e
//    mais críticos. Lê d.giro (cache populado no fim de renderDgGiro, em
//    dashboard.js — a lógica de classificação de nível/giro/cobertura NUNCA
//    é duplicada aqui, só reformatada com cores literais). Tabelas
//    reaproveitam .rk-table do shell (_buildRankingShellHTML). ───────────
function _dgrNivelCor(level) {
  return { bom: '#10b981', atencao: '#f59e0b', urgente: '#f97316', critico: '#f43f5e' }[level] || '#64748b';
}
function _dgrGiroCor(g) {
  if (g > 4.0)  return '#f43f5e';
  if (g >= 2.0) return '#10b981';
  if (g >= 1.0) return '#06b6d4';
  if (g >= 0.5) return '#f59e0b';
  if (g >= 0.2) return '#f97316';
  return '#f43f5e';
}
function _dgrTruncNome(nome, max = 26) {
  const s = String(nome || '');
  return s.length > max ? s.slice(0, max - 1).trimEnd() + '…' : s;
}
// ── Abastecimento (entradas ÷ saídas) — MESMOS limiares/rótulos de
//    buildAbastCell (função interna de renderDgGiro, dashboard.js, não
//    acessível globalmente), só com cores literais em vez de var(--x) e
//    sem os data-help/tooltips (não fazem sentido num PDF estático).
//    panel: 'alto' (alto giro — risco de ruptura) ou 'baixo' (baixo giro —
//    capital parado) — o mesmo % de abastecimento é lido de forma
//    diferente conforme o painel, exatamente como na tela. ──────────────
function _dgrAbastInfo(entradas, saidas, panel) {
  if (saidas < 0.001 && entradas < 0.001) return { texto: '—', cor: '#64748b', icone: null };
  if (saidas < 0.001) return { texto: 'acúmulo', cor: '#8b5cf6', icone: 'ti-arrow-up' };
  const ratio = (entradas / saidas) * 100;
  const label = ratio.toFixed(0) + '%';
  if (panel === 'alto') {
    if (ratio >= 100) return { texto: label, cor: '#10b981', icone: 'ti-circle-check' };
    if (ratio >= 80)  return { texto: label, cor: '#f59e0b', icone: 'ti-alert-triangle' };
    return { texto: label, cor: '#f43f5e', icone: 'ti-flame' };
  }
  if (ratio > 150)  return { texto: label, cor: '#8b5cf6', icone: 'ti-currency-dollar' };
  if (ratio >= 100) return { texto: label, cor: '#f59e0b', icone: 'ti-arrow-up' };
  if (ratio >= 80)  return { texto: label, cor: '#10b981', icone: 'ti-equal' };
  return { texto: label, cor: '#f43f5e', icone: 'ti-trending-down' };
}
function _dgrGiroListaHtml(titulo, iconCls, items, panel, footerArr) {
  if (!items || !items.length) {
    return `<div class="dgr-chart-card"><div class="dgr-chart-title"><i class="ti ${iconCls}"></i>${_rankEsc(titulo)}</div><div class="dgr-chart-empty">Sem dados de giro</div></div>`;
  }
  const rows = items.map(item => {
    const cor = _dgrNivelCor(item.nivel.level);
    const abast = _dgrAbastInfo(item.entradas, item.saidas, panel);
    return `
    <tr>
      <td class="rk-name" style="font-size:10.5px" title="${_rankEsc(item.name)}"><span class="dgr-nome-trunc-inner">${_rankEsc(_dgrTruncNome(item.name))}</span></td>
      <td><span style="display:inline-block;padding:1px 5px;border-radius:5px;font-size:8.5px;font-weight:700;white-space:nowrap;background:${cor}22;color:${cor};border:1px solid ${cor}55">${_rankEsc(item.nivel.label)}</span></td>
      <td class="rk-num" style="font-size:8.5px;color:#94a3b8">${_dgrNowrapNum(fmtKgShort(item.entradas))}</td>
      <td class="rk-num" style="font-size:8.5px;color:#94a3b8">${_dgrNowrapNum(fmtKgShort(item.saidas))}</td>
      <td style="text-align:right"><span style="display:inline-flex;align-items:center;gap:3px;padding:1px 5px;border-radius:5px;font-size:8px;font-weight:700;white-space:nowrap;background:${abast.cor}22;color:${abast.cor};border:1px solid ${abast.cor}55">${abast.icone ? `<i class="ti ${abast.icone}" style="font-size:9px"></i>` : ''}${abast.texto}</span></td>
      <td class="rk-num" style="font-size:8.5px;color:#94a3b8">${_dgrNowrapNum(fmtKgShort(item.estMedio || 0))}</td>
      <td class="rk-num" style="font-size:9px;color:${_dgrGiroCor(item.giro)}">${_dgrNowrapNum(item.giro.toFixed(2) + '×')}</td>
      <td class="rk-num" style="font-size:9px">${item.cobertura === null ? 'sem consumo' : _dgrNowrapNum(item.cobertura.toFixed(1) + 'd')}</td>
    </tr>`;
  }).join('');

  // Rodapé de resumo (só no painel "Materiais Mais Críticos" — mesma
  // condição withFooter=true de buildBaixoFooter na tela) — soma sobre o
  // array COMPLETO (footerArr), não só os 5 exibidos na tabela.
  const footerHtml = footerArr ? (() => {
    const parados   = footerArr.filter(m => m.giro < 0.1).length;
    const baixoGiro = footerArr.filter(m => m.giro >= 0.1 && m.giro < 1).length;
    const estTotal  = footerArr.reduce((s, m) => s + (m.estMedio || 0), 0);
    return `
      <div class="dgr-giro-footer">
        <span style="color:#f43f5e"><i class="ti ti-lock" style="font-size:10px"></i> ${parados} parado${parados !== 1 ? 's' : ''}</span>
        <span style="color:#f59e0b"><i class="ti ti-alert-triangle" style="font-size:10px"></i> ${baixoGiro} baixo giro</span>
        <span style="color:#64748b;margin-left:auto">Est. total parado: ${fmtKgShort(estTotal)}</span>
      </div>`;
  })() : '';

  return `
    <div class="dgr-chart-card dgr-giro-card">
      <div class="dgr-chart-title"><i class="ti ${iconCls}"></i>${_rankEsc(titulo)}</div>
      <table class="rk-table dgr-giro-table">
        <thead><tr>
          <th style="width:19%">Nome</th>
          <th style="width:11%">Nível</th>
          <th style="width:12%;text-align:right">Entradas</th>
          <th style="width:12%;text-align:right">Saídas</th>
          <th style="width:16%;text-align:right">Abast.</th>
          <th style="width:12%;text-align:right">Est.Médio</th>
          <th style="width:8%;text-align:right">Giro</th>
          <th style="width:10%;text-align:right">Cobertura</th>
        </tr></thead>
        <tbody>${rows}</tbody>
      </table>
      ${footerHtml}
    </div>`;
}
function _dgrBuildGiroCoberturaHtml(d) {
  const g = d.giro;
  if (!g) return '';
  return `
    <div class="dgr-section-title" style="margin-top:26px"><i class="ti ti-arrows-exchange"></i>Giro & Cobertura — Top 5</div>
    <div class="dgr-chart-grid">
      ${_dgrGiroListaHtml('Top 5 Centrais — Mais Saudáveis', 'ti-trending-up', g.centralAlto, 'alto')}
      ${_dgrGiroListaHtml('Top 5 Centrais — Mais Críticas', 'ti-trending-down', g.centralBaixo, 'baixo')}
    </div>
    <div class="dgr-chart-grid" style="margin-top:6px">
      ${_dgrGiroListaHtml('Top 5 Materiais — Mais Saudáveis', 'ti-trending-up', g.matAlto, 'alto')}
      ${_dgrGiroListaHtml('Top 5 Materiais — Mais Críticos', 'ti-trending-down', g.matBaixo, 'baixo', g.matArrFull)}
    </div>`;
}

// ── Seção 10: Detalhado Analítico — tabela de Detalhamento por Material +
//    4 rankings (Regional/Central/Material/Categoria). Chama DIRETO as
//    mesmas funções puras de cálculo que dashboard.js usa na tela
//    (_daBuildTabelaMaterial, _daBuildRanking, etc. — funções globais,
//    reaproveitando d.pares/d.results/d.totalEstTeoricoKpi já cacheados),
//    então os números nunca podem divergir da Visão Geral. Lista completa
//    (sem corte por Top N) — decisão do Hugo, jul/2026: tabelas usam
//    .dgr-table-wrap (sem page-break-inside:avoid, ao contrário de
//    .rk-table-wrap do shell) pra paginar naturalmente na impressão em vez
//    de forçar a tabela inteira numa página só. ───────────────────────────
function _dgrValCor(v) {
  if (v === null || v === undefined || !Number.isFinite(v)) return '#64748b';
  return v < -0.0001 ? '#f43f5e' : v > 0.0001 ? '#f59e0b' : '#64748b';
}
// Mantém o trecho numérico de um valor já formatado (money/fmtKg/pct etc.)
// inteiro, numa unidade não-quebrável, JUNTO com um "R$" que vier logo
// antes dele — prefixos (R$) e sufixos (kg, /kg, %, ×) continuam podendo
// quebrar pra linha seguinte livremente quando não colados no número,
// mas o "R$ 1.234,56" (ou só o número, sem R$) nunca quebra no meio nem
// se separa um do outro (evita o "12.85|5.060|,00|kg" E o "R$|1.234,56"
// que aconteciam em colunas estreitas).
function _dgrNowrapNum(str) {
  const s = String(str);
  // Pega o ÚLTIMO trecho numérico da string (+ "R$ " logo antes dele, se
  // houver) — é sempre o valor formatado de verdade. Usar o primeiro
  // (versão anterior, com bug) podia casar um número que apareça ANTES
  // dele dentro de HTML já embutido, como o "11" de style="font-size:11px"
  // no ícone que varSymbol() antepõe em _daFmtPctSigned/_daFmtMoneySigned/
  // _daFmtCountSigned — o que quebrava a tag no meio e vazava texto cru
  // pro PDF.
  const m = s.match(/(?:R\$\s*)?[\d.,]+(?!.*[\d.,])/);
  if (!m) return s;
  return s.slice(0, m.index) + `<span style="white-space:nowrap">${m[0]}</span>` + s.slice(m.index + m[0].length);
}
function _dgrTabelaMaterialHtml(dados) {
  if (!dados.linhas.length) return '';
  const rows = dados.linhas.map(l => {
    const catLabel = l.catKey ? (DG_VG_CATSUB_LABELS[l.catSubKey] || DG_VG_CAT_LABELS[l.catKey] || l.catKey) : '';
    return `
    <tr>
      <td class="rk-name" style="font-size:10.5px" title="${_rankEsc(l.mat)}"><span class="dgr-nome-trunc-inner">${_rankEsc(_dgrTruncNome(l.mat, 20))}</span>${catLabel ? `<div class="rk-sub dgr-nome-trunc-inner" title="${_rankEsc(catLabel)}">${_rankEsc(_dgrTruncNome(catLabel, 20))}</div>` : ''}</td>
      <td class="rk-num" style="color:#06b6d4">${_dgrNowrapNum(fmtKg(l.estIni))}</td>
      <td class="rk-num" style="color:#10b981">${_dgrNowrapNum(fmtKg(l.entKg))}</td>
      <td class="rk-num" style="color:#f43f5e">${_dgrNowrapNum(fmtKg(l.saiKg))}</td>
      <td class="rk-num" style="color:#06b6d4">${_dgrNowrapNum(fmtKg(l.estTeorico))}</td>
      <td class="rk-num" style="color:#06b6d4">${_dgrNowrapNum(fmtKg(l.estFim))}</td>
      <td class="rk-num" style="color:${_dgrValCor(l.pctVariacao)}">${_dgrNowrapNum(_daFmtPctSigned(l.pctVariacao))}</td>
      <td class="rk-num">${_dgrNowrapNum(money(l.custoMedio) + '/kg')}</td>
      <td class="rk-num" style="color:${_dgrValCor(l.custoAjuste)}">${_dgrNowrapNum(_daFmtMoneySigned(l.custoAjuste))}</td>
    </tr>`;
  }).join('');
  const t = dados.total;
  const totalRow = `
    <tr style="font-weight:800;background:rgba(255,255,255,.05)">
      <td class="rk-name">Total</td>
      <td class="rk-num" style="color:#06b6d4">${_dgrNowrapNum(fmtKg(t.estIni))}</td>
      <td class="rk-num" style="color:#10b981">${_dgrNowrapNum(fmtKg(t.entKg))}</td>
      <td class="rk-num" style="color:#f43f5e">${_dgrNowrapNum(fmtKg(t.saiKg))}</td>
      <td class="rk-num" style="color:#06b6d4">${_dgrNowrapNum(fmtKg(t.estTeorico))}</td>
      <td class="rk-num" style="color:#06b6d4">${_dgrNowrapNum(fmtKg(t.estFim))}</td>
      <td class="rk-num" style="color:${_dgrValCor(t.pctVariacao)}">${_dgrNowrapNum(_daFmtPctSigned(t.pctVariacao))}</td>
      <td class="rk-num">${_dgrNowrapNum(money(t.custoMedio) + '/kg')}</td>
      <td class="rk-num" style="color:${_dgrValCor(t.custoAjuste)}">${_dgrNowrapNum(_daFmtMoneySigned(t.custoAjuste))}</td>
    </tr>`;
  return `
    <div class="dgr-table-wrap">
      <div class="rk-table-head"><div class="rk-table-head-title">Detalhamento por Material (Grupo SAP)</div><div class="rk-table-head-cap">${dados.linhas.length} materia${dados.linhas.length !== 1 ? 'is' : 'l'}</div></div>
      <table class="rk-table dgr-material-table">
        <thead><tr>
          <th style="width:9%">Grupo SAP</th>
          <th style="width:12%;text-align:right">Est. Inicial</th>
          <th style="width:12%;text-align:right">Entradas</th>
          <th style="width:12%;text-align:right">Saídas</th>
          <th style="width:12%;text-align:right">Est. Teórico</th>
          <th style="width:12%;text-align:right">Est. Final</th>
          <th style="width:9%;text-align:right">% Variação</th>
          <th style="width:11%;text-align:right">Custo Médio</th>
          <th style="width:11%;text-align:right">Custo Ajuste</th>
        </tr></thead>
        <tbody>${rows}</tbody>
        <tfoot>${totalRow}</tfoot>
      </table>
    </div>`;
}
function _dgrRankingHtml(titulo, colLabel, dados) {
  if (!dados.linhas.length) return '';
  const rows = dados.linhas.map(l => {
    const imp = _daMaiorImpacto(l);
    const cell = (campo, valor) => imp === campo ? `<strong>${_dgrNowrapNum(_daFmtCountSigned(valor))}</strong>` : _dgrNowrapNum(_daFmtCountSigned(valor));
    return `
    <tr>
      <td class="rk-name" style="font-size:11px">${_rankEsc(l.nome)}</td>
      <td class="rk-num" style="color:${_dgrValCor(l.caminhoes)}">${cell('caminhoes', l.caminhoes)}</td>
      <td class="rk-num" style="color:${_dgrValCor(l.carretas)}">${cell('carretas', l.carretas)}</td>
      <td class="rk-num" style="color:${_dgrValCor(l.ibcs)}">${cell('ibcs', l.ibcs)}</td>
      <td class="rk-num" style="color:${_dgrValCor(l.pctVariacao)}">${_dgrNowrapNum(_daFmtPctSigned(l.pctVariacao))}</td>
      <td class="rk-num" style="color:${_dgrValCor(l.custoTotal)}">${_dgrNowrapNum(_daFmtMoneySigned(l.custoTotal))}</td>
    </tr>`;
  }).join('');
  const t = dados.total;
  const totalRow = `
    <tr style="font-weight:800;background:rgba(255,255,255,.05)">
      <td class="rk-name">Total</td>
      <td class="rk-num" style="color:${_dgrValCor(t.caminhoes)}">${_dgrNowrapNum(_daFmtCountSigned(t.caminhoes))}</td>
      <td class="rk-num" style="color:${_dgrValCor(t.carretas)}">${_dgrNowrapNum(_daFmtCountSigned(t.carretas))}</td>
      <td class="rk-num" style="color:${_dgrValCor(t.ibcs)}">${_dgrNowrapNum(_daFmtCountSigned(t.ibcs))}</td>
      <td class="rk-num" style="color:${_dgrValCor(t.pctVariacao)}">${_dgrNowrapNum(_daFmtPctSigned(t.pctVariacao))}</td>
      <td class="rk-num" style="color:${_dgrValCor(t.custoTotal)}">${_dgrNowrapNum(_daFmtMoneySigned(t.custoTotal))}</td>
    </tr>`;
  return `
    <div class="dgr-table-wrap">
      <div class="rk-table-head"><div class="rk-table-head-title">${_rankEsc(titulo)}</div><div class="rk-table-head-cap">${dados.linhas.length} ${dados.linhas.length !== 1 ? 'itens' : 'item'}</div></div>
      <table class="rk-table dgr-ranking-table">
        <thead><tr>
          <th style="width:26%">${_rankEsc(colLabel)}</th>
          <th style="width:13%;text-align:right">Caminhões</th>
          <th style="width:13%;text-align:right">Carretas</th>
          <th style="width:13%;text-align:right">IBCs</th>
          <th style="width:13%;text-align:right">Variação</th>
          <th style="width:22%;text-align:right">Custo Total</th>
        </tr></thead>
        <tbody>${rows}</tbody>
        <tfoot>${totalRow}</tfoot>
      </table>
    </div>`;
}
function _dgrBuildDetalhadoAnaliticoHtml(d) {
  const entradasFlat = _daBuildEntradasFlat(d.results);
  const pesoMedio     = _daPesoMedioPorTipo(entradasFlat);
  const tabelaMaterial = _daBuildTabelaMaterial(d.pares);
  const rankRegional  = _daBuildRanking(d.pares, pesoMedio, p => p.regional, d.totalEstTeoricoKpi, k => k === '—' ? 'Sem regional' : k);
  const rankCentral   = _daBuildRanking(d.pares, pesoMedio, p => p.central,  d.totalEstTeoricoKpi);
  const rankMaterial  = _daBuildRanking(d.pares, pesoMedio, p => p.mat,      d.totalEstTeoricoKpi);
  const rankCategoria = _daBuildRanking(
    d.pares, pesoMedio,
    p => p.catKey === 'agregado' ? (p.catSubKey || 'agregado_sem_subcategoria') : p.catKey,
    d.totalEstTeoricoKpi,
    k => DG_VG_CATSUB_LABELS[k] || DG_VG_CAT_LABELS[k] || (k === 'agregado_sem_subcategoria' ? 'Agregado (sem subcategoria)' : k)
  );

  return `
    ${_dgrTabelaMaterialHtml(tabelaMaterial)}
    ${_dgrRankingHtml('Ranking de Regionais', 'Regional', rankRegional)}
    ${_dgrRankingHtml('Ranking de Centrais', 'Central', rankCentral)}
    ${_dgrRankingHtml('Ranking de Materiais', 'Material', rankMaterial)}
    ${_dgrRankingHtml('Ranking de Categoria', 'Categoria', rankCategoria)}`;
}

function _dgrEstilos() {
  return `
    .dgr-section-title { font-size:11px; font-weight:800; letter-spacing:.05em; text-transform:uppercase; color:var(--dgr-accent-text, #f87171); margin:0 0 8px; display:flex; align-items:center; gap:8px; }
    .dgr-kpi-secondary { display:grid; grid-template-columns:repeat(3,1fr); gap:13px; margin-bottom:8px; }
    .dgr-kpi-card { background:var(--dgr-card-bg, rgba(255,255,255,.045)); border:1px solid var(--dgr-card-border, rgba(255,255,255,.09)); border-radius:12px; padding:22px 24px; border-top:3px solid transparent; page-break-inside:avoid; }
    .dgr-kpi-secondary .dgr-kpi-card { padding:15px 19px; border-top:none; }
    .dgr-kpi-card-head { display:flex; align-items:flex-start; justify-content:space-between; gap:10px; margin-bottom:8px; }
    .dgr-kpi-icon { width:30px; height:30px; border-radius:9px; display:flex; align-items:center; justify-content:center; font-size:15px; flex-shrink:0; }
    .dgr-kpi-label { font-size:10.5px; font-weight:700; text-transform:uppercase; letter-spacing:.06em; color:var(--dgr-text-dim, #94a3b8); }
    .dgr-kpi-value { font-family:'JetBrains Mono',monospace; font-size:25px; font-weight:800; color:var(--dgr-text-strong, #fff); }
    .dgr-kpi-secondary .dgr-kpi-value { font-size:21px; }
    .dgr-kpi-unit { font-size:10.5px; color:var(--dgr-text-dim2, #64748b); margin-top:4px; font-family:'JetBrains Mono',monospace; }
    .dgr-kpi-divider-row { display:flex; align-items:baseline; gap:7px; margin-top:8px; padding-top:8px; border-top:1px solid var(--dgr-divider, rgba(255,255,255,.08)); }
    .dgr-kpi-pct { font-family:'JetBrains Mono',monospace; font-size:19px; font-weight:800; }
    .dgr-kpi-pct-sub { font-family:'JetBrains Mono',monospace; font-size:13px; font-weight:600; }
    .dgr-kpi-pct-label { font-size:10px; color:var(--dgr-text-dim2, #64748b); }
    /* Card hero "Variação Estoque" — saldo em evidência (valor maior),
       custo em R$ abaixo (menor), veículos em blocos grandes por baixo. */
    .dgr-kpi-hero { background:var(--dgr-card-bg, rgba(255,255,255,.045)); border:1px solid var(--dgr-card-border, rgba(255,255,255,.09)); border-radius:12px; padding:19px 27px; border-top:3px solid transparent; page-break-inside:avoid; }
    .dgr-kpi-hero-saldo { font-family:'JetBrains Mono',monospace; font-size:32px; font-weight:800; }
    .dgr-kpi-hero-custo { font-family:'JetBrains Mono',monospace; font-size:23px; font-weight:700; }
    /* Linha do custo (R$) + veículos lado a lado — sem selo/ícone (só
       número + rótulo pequeno), discretos, ao lado do custo em vez de
       embaixo numa grade grande — pedido do Hugo pra corrigir o
       desbalanceamento do card hero. */
    .dgr-kpi-hero-custo-row { display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:20px; margin-top:12px; padding-top:12px; border-top:1px solid var(--dgr-divider, rgba(255,255,255,.08)); }
    .dgr-kpi-veiculos-simples { display:flex; gap:28px; flex-wrap:wrap; }
    .dgr-kpi-veiculo-simples { text-align:center; }
    .dgr-kpi-veiculo-simples-valor { font-family:'JetBrains Mono',monospace; font-size:15px; font-weight:800; }
    .dgr-kpi-veiculo-simples-label { font-size:9px; color:var(--dgr-text-dim2, #64748b); text-transform:uppercase; letter-spacing:.05em; font-weight:700; margin-top:2px; }
    .dgr-health-grid { display:grid; grid-template-columns:1fr 1fr; gap:20px; }
    .dgr-health-card { background:var(--dgr-card-bg, rgba(255,255,255,.045)); border:1px solid var(--dgr-card-border, rgba(255,255,255,.09)); border-radius:12px; padding:23px; page-break-inside:avoid; }
    .dgr-health-card img { max-width:100%; height:auto; display:block; margin:0 auto; }
    .dgr-health-title { font-size:11px; font-weight:800; text-transform:uppercase; letter-spacing:.05em; color:var(--dgr-text, #e2e8f0); margin-bottom:10px; display:flex; align-items:center; gap:6px; }
    .dgr-health-summary { display:flex; flex-wrap:wrap; gap:6px; justify-content:center; margin-top:10px; }
    .dgr-chart-card { background:var(--dgr-card-bg, rgba(255,255,255,.045)); border:1px solid var(--dgr-card-border, rgba(255,255,255,.09)); border-radius:12px; padding:20px 23px; page-break-inside:avoid; }
    .dgr-chart-card img { max-width:100%; height:auto; display:block; margin:0 auto; }
    .dgr-chart-title { font-size:11px; font-weight:800; text-transform:uppercase; letter-spacing:.05em; color:var(--dgr-text, #e2e8f0); margin-bottom:12px; display:flex; align-items:center; gap:6px; }
    .dgr-chart-empty { padding:40px 0; color:var(--dgr-text-dim2, #64748b); font-size:11px; text-align:center; }
    .dgr-chart-grid { display:grid; grid-template-columns:1fr 1fr; gap:24px; margin-top:16px; }
    .dgr-extremos-grid { display:grid; grid-template-columns:repeat(auto-fit,minmax(125px,1fr)); gap:10px; margin-bottom:6px; }
    .dgr-extremo-box { background:var(--dgr-card-bg, rgba(255,255,255,.045)); border:1px solid var(--dgr-card-border, rgba(255,255,255,.09)); border-radius:12px; padding:13px 12px; page-break-inside:avoid; }
    .dgr-extremo-label { font-size:10.5px; font-weight:700; font-family:'JetBrains Mono',monospace; letter-spacing:.06em; text-transform:uppercase; color:var(--dgr-text-dim, #94a3b8); margin-bottom:5px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
    .dgr-extremo-value { font-size:19px; font-weight:700; font-family:'JetBrains Mono',monospace; letter-spacing:-.02em; margin-bottom:3px; }
    .dgr-extremo-kg { font-size:9.5px; font-family:'JetBrains Mono',monospace; color:var(--dgr-text-dim2, #64748b); margin-bottom:5px; }
    .dgr-extremo-name { font-size:11px; color:var(--dgr-brand-text, #cbd5e1); font-weight:600; }
    .dgr-grupo-layout { display:grid; grid-template-columns:1fr 1fr; gap:16px; }
    .dgr-donut-grande img { max-width:100%; height:auto; }
    .dgr-donut-sub-grid { display:grid; grid-template-columns:1fr 1fr; gap:12px; }
    .dgr-donut-small .dgr-chart-title { margin-bottom:8px; }
    .dgr-table-wrap {
      margin-bottom:26px;
      background:var(--dgr-card-bg, rgba(255,255,255,.045));
      border:1px solid var(--dgr-card-border, rgba(255,255,255,.09));
      border-radius:12px;
      padding:16px 6px;
    }
    /* Cabeçalho e total (thead/tfoot) SEM repetir a cada quebra de
       página — por padrão, tanto o display:table-header-group (thead)
       quanto o table-footer-group (tfoot, já vem assim de fábrica no
       navegador mesmo sem CSS nenhum) fazem o Chrome reimprimir essas
       linhas em TODAS as páginas em que a tabela se estende. Forçando
       os dois pra table-row-group (linha "comum"), eles saem da posição
       de "cabeçalho/rodapé fixo por página" e passam a fluir no lugar
       normal: thead continua no topo (primeiro no HTML) e tfoot no fim
       (é o último elemento dentro de <table>, ver _dgrTabelaMaterialHtml/
       _dgrRankingHtml), só que cada um aparece UMA vez só. */
    .dgr-table-wrap thead, .dgr-chart-card table.rk-table thead { display:table-row-group; }
    .dgr-table-wrap tfoot,  .dgr-chart-card table.rk-table tfoot  { display:table-row-group; }
    .dgr-table-wrap tbody tr { page-break-inside:avoid; }
    .dgr-table-wrap .rk-table { table-layout:fixed; }
    .dgr-table-wrap tbody tr:nth-child(even) { background:var(--dgr-row-alt, rgba(255,255,255,.025)); }
    .dgr-chart-card table.rk-table tbody tr:nth-child(even) { background:var(--dgr-row-alt, rgba(255,255,255,.025)); }
    /* Mais respiro nas células — escopado a .dgr-chart-card/.dgr-table-wrap
       (Giro & Cobertura + Detalhado Analítico) pra não alterar .rk-table
       nos outros relatórios do sistema (Ocorrências, Ranking etc.), que
       usam a densidade padrão do shell. */
    .dgr-chart-card .rk-table th, .dgr-table-wrap .rk-table th { padding:9px 3px; font-size:7.5px; white-space:nowrap; letter-spacing:.02em; }
    .dgr-chart-card .rk-table td, .dgr-table-wrap .rk-table td { padding:10px 3px; line-height:1.4; overflow-wrap:break-word; font-size:7.5px; }
    /* Coluna de nome (1ª coluna) é a única que pode quebrar em várias
       linhas — mantém uma fonte um pouco maior, mais legível, já que ela
       tem a largura reservada pra isso. As demais colunas (números) usam
       a fonte reduzida acima pra caber numa linha só sem vazar pra célula
       vizinha. */
    .dgr-table-wrap .rk-name, .dgr-chart-card .rk-name { font-size:8.3px !important; }
    .dgr-table-wrap .rk-name { line-height:1.35; }
    .dgr-table-wrap .rk-sub, .dgr-chart-card .rk-sub { font-size:7.3px; }
    /* Corte de texto do nome — num span INTERNO ao td (não no td em si),
       com max-width:100% do pai. O td continua um table-cell normal,
       respeitando a largura em % que table-layout:fixed calculou; um
       display:inline-block com max-width fixo direto no td (versão
       anterior) não respeitava essa largura de forma confiável e deixava
       o texto vazar visualmente pra célula vizinha. */
    .dgr-nome-trunc-inner { display:block; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; max-width:100%; }
    .dgr-chart-card table.rk-table { table-layout:fixed; }
    /* Cards de Giro & Cobertura — mais compactos que o padrão de
       .dgr-chart-card (usado também pelos gráficos, que têm menos
       conteúdo). São 4 tabelas na mesma seção/página; com o padding
       padrão dos cards + células a seção passava de 1 página (a 4ª
       tabela ficava sozinha numa página seguinte quase vazia). */
    .dgr-giro-card { padding:8px 10px; }
    .dgr-giro-card .dgr-chart-title { margin-bottom:5px; }
    .dgr-giro-card .rk-table th { padding:4px 3px; }
    .dgr-giro-card .rk-table td { padding:4px 3px; line-height:1.15; }
    .dgr-giro-footer { display:flex; gap:14px; padding:4px 0 0; margin-top:4px; border-top:1px solid var(--dgr-divider, rgba(255,255,255,.08)); flex-wrap:wrap; font-size:9px; font-family:'JetBrains Mono',monospace; font-weight:700; }
    .dgr-giro-footer span { display:flex; align-items:center; gap:4px; }
    /* Colapso dos pares de card (Giro, gráficos de barra) e das grades de
       3 colunas — SEMPRE ao imprimir/gerar PDF, não só condicional a
       largura. Medi e confirmei: @media(max-width) é avaliado contra a
       largura da JANELA do navegador, não da página impressa — numa
       janela larga a condição nunca dispara mesmo a página final saindo
       estreita (retrato), o que já causou tabelas do Giro espremidas a
       ponto de virar ilegíveis. Como as classes dgr-* só existem neste
       relatório, é seguro deixar incondicional no papel. A condição por
       largura continua valendo também, só como bônus pra quem visualizar
       o HTML numa janela estreita antes de imprimir. */
    @media print, (max-width:900px) {
      .dgr-kpi-secondary, .dgr-health-grid, .dgr-grupo-layout, .dgr-donut-sub-grid { grid-template-columns:repeat(2,1fr); }
      .dgr-chart-grid { grid-template-columns:1fr; }
    }
    @media print { .dgr-kpi-card, .dgr-health-card, .dgr-chart-card, .dgr-extremo-box { page-break-inside:avoid; } }

    /* ── Recolher/expandir seção (jul/2026) — cada <section> do relatório
       ganha um cabeçalho clicável (rótulo vem do registro de abas/seções,
       não duplica o título interno de cada builder, que continua igual).
       Ao imprimir/salvar PDF, força tudo expandido e esconde o botão —
       não faz sentido ter conteúdo escondido no papel. ────────────────── */
    .dgr-collapse-toggle {
      width:100%; display:flex; align-items:center; gap:8px;
      background:none; border:none; border-bottom:1px solid var(--dgr-card-border, rgba(255,255,255,.08));
      cursor:pointer; padding:0 0 10px; margin-bottom:16px;
      font-size:11px; font-weight:800; letter-spacing:.05em; text-transform:uppercase;
      color:var(--dgr-text-dim, #94a3b8); text-align:left; font-family:inherit;
    }
    .dgr-collapse-toggle:hover { color:var(--dgr-text, #e2e8f0); }
    .dgr-collapse-toggle i { font-size:14px; transition:transform .15s ease; flex-shrink:0; }
    .dgr-collapse-toggle[aria-expanded="false"] i { transform:rotate(-90deg); }
    .dgr-collapse-body.dgr-collapsed { display:none; }
    @media print {
      .dgr-collapse-toggle { display:none; }
      .dgr-collapse-body.dgr-collapsed { display:block !important; }
    }

    /* ── Navegação por abas (jul/2026) — só aparece quando o relatório
       reúne mais de uma aba do Dashboard Gerencial na mesma seleção (hoje
       só existe Visão Geral registrada; o mecanismo fica pronto e
       invisível até Consumo/Corte entrarem). O painel ativo sempre ganha
       .rel-aba-ativa já na geração (não depende de JS rodar pra aparecer
       algo na tela). Ao imprimir, esconde a barra e força todos os
       painéis visíveis — impressão sempre traz tudo que foi selecionado,
       não só a aba que estava em foco na tela. ──────────────────────── */
    .rel-aba-bar { display:flex; gap:8px; margin-bottom:20px; flex-wrap:wrap; }
    .rel-aba-btn {
      display:flex; align-items:center; gap:6px; padding:8px 14px; border-radius:8px;
      border:1px solid var(--dgr-card-border, rgba(255,255,255,.08));
      background:var(--dgr-card-bg, rgba(255,255,255,.03)); color:var(--dgr-text-dim, #94a3b8);
      font-size:11.5px; font-weight:700; cursor:pointer; font-family:inherit;
    }
    .rel-aba-btn.active { color:var(--dgr-text, #e2e8f0); border-color:var(--dgr-accent-text, #f87171); }
    .rel-aba-pane { display:none; }
    .rel-aba-pane.rel-aba-ativa { display:block; }
    @media print {
      .rel-aba-bar { display:none; }
      .rel-aba-pane { display:block !important; }
    }`;
}

// ═══════════════════════════════════════════════════════════════════════════════
// REGISTRO DINÂMICO DE ABAS/SEÇÕES — Exportação Interativa do Relatório
// Gerencial (jul/2026). Cada aba do Dashboard Gerencial que já tiver um
// cache de dados pronto (padrão window._dgXxxLastData, populado no fim do
// render da aba, sem recalcular nada) se registra aqui com suas seções.
// O modal de seleção (abrirModalSelecaoRelatorioGerencial) e a montagem
// do corpo do relatório (gerarRelatorioGerencialDashboard) são 100%
// orientados por esse registro — nenhum nome de aba fica hardcoded fora
// daqui, então ativar Consumo/Corte/futuras abas é só adicionar uma
// entrada nova nesse array, sem reescrever o núcleo.
//
// Giro & Cobertura NÃO está aqui: foi migrada da Visão Geral pra dentro
// da Visão de Consumo na tela (ver renderDgConsumo, dashboard.js), então
// volta a aparecer como seção da aba "consumo" quando essa etapa for
// implementada — _dgrBuildGiroCoberturaHtml continua existindo no
// arquivo, só não é chamada daqui por enquanto (decisão de jul/2026,
// confirmada com o usuário).
// ═══════════════════════════════════════════════════════════════════════════════
window._RELATORIO_ABAS_REGISTRY = [
  {
    id: 'visao-geral',
    label: 'Visão Geral',
    icon: 'ti-layout-dashboard',
    disponivel: () => !!window._dgVgLastData,
    secoes: [
      { id: 'resumo-periodo',  label: 'Resumo do Período — Estoque, Movimentação e Variação', natural: false,
        builder: (d) => _dgrBuildResumoPeriodoHtml(d) },
      { id: 'custo-regional',  label: 'Variação por Regional e Central', natural: false,
        builder: (d, imgs) => _dgrBuildCustoRegionalCentralHtml(d, imgs.imgRegional, imgs.imgUsina) },
      { id: 'saude-categoria', label: 'Saúde Geral + Categoria', natural: false,
        builder: (d, imgs) => _dgrBuildSaudeGeralHtml(imgs.imgGaugeCentral, imgs.imgGaugeMateriais) + _dgrBuildCategoriaHtml(imgs.imgCategoria) },
      { id: 'detalhado',       label: 'Detalhado Analítico — Tabela de Material', natural: true,
        builder: (d) => _dgrBuildDetalhadoAnaliticoHtml(d) }
    ]
  }
  // Consumo e Controle de Corte entram aqui em etapas futuras, cada um
  // com seu próprio cache de dados (_dgConsLastData / _dgCorteLastData ou
  // nomes equivalentes) e builders de seção próprios.
];

// Seleção "tudo marcado" — usada quando o relatório é gerado sem passar
// por seleção nenhuma (chamada direta/antiga) e como estado inicial dos
// checkboxes no modal (nunca abre com nada desmarcado).
function _dgrSelecaoCompleta() {
  const sel = {};
  window._RELATORIO_ABAS_REGISTRY.forEach(aba => {
    if (aba.disponivel()) sel[aba.id] = aba.secoes.map(s => s.id);
  });
  return sel;
}

// ── Modal de seleção: abas e seções que entram no HTML exportado ───────────
// Injeta o CSS uma única vez (guard por id, mesmo padrão do próprio modal
// — evita empilhar <style> repetido toda vez que o modal reabre).
function _dgrInjetarEstiloModalSelecao() {
  if (document.getElementById('rel-sel-modal-style')) return;
  const style = document.createElement('style');
  style.id = 'rel-sel-modal-style';
  style.textContent = `
    .rel-sel-aba { border:1px solid var(--border); border-radius:10px; padding:10px 12px; }
    .rel-sel-aba.rel-sel-disabled { opacity:.5; }
    .rel-sel-aba-header { display:flex; align-items:center; gap:8px; cursor:pointer; font-size:13px; }
    .rel-sel-aba-header input { margin:0; }
    .rel-sel-badge { margin-left:auto; font-size:10.5px; color:var(--text3); font-weight:400; }
    .rel-sel-secoes { display:flex; flex-direction:column; gap:6px; margin:8px 0 0 26px; }
    .rel-sel-secao { display:flex; align-items:center; gap:8px; font-size:12.5px; color:var(--text2); cursor:pointer; }
    .rel-sel-secao input { margin:0; }
  `;
  document.head.appendChild(style);
}

// Ponto de entrada direto do botão "Relatório Gerencial" (index.html) —
// sem modal de tema intermediário: o HTML gerado já tem seu próprio botão
// de troca de tema embutido (ver _dgrScriptTema), então escolher o tema
// antes de gerar virou redundante (decisão de jul/2026). O tema aqui só
// define a cor em que os gráficos/gauges são capturados (rasterizados em
// PNG — não mudam de cor junto com o toggle do HTML gerado, só o restante
// da página muda; ver nota em _dgrCapturarComTema).
window.abrirModalSelecaoRelatorioGerencial = function(tema = 'dark') {
  const algumaDisponivel = window._RELATORIO_ABAS_REGISTRY.some(aba => aba.disponivel());
  if (!algumaDisponivel) {
    toast('Analise um período em pelo menos uma aba do Dashboard Gerencial antes de gerar o relatório.', 'error');
    return;
  }

  _dgrInjetarEstiloModalSelecao();

  let modal = document.getElementById('rel-selecao-modal');
  if (!modal) {
    modal = document.createElement('div');
    modal.id = 'rel-selecao-modal';
    modal.className = 'modal-overlay';
    modal.style.cssText = 'z-index:3200';
    document.body.appendChild(modal);
  }

  const abasHtml = window._RELATORIO_ABAS_REGISTRY.map(aba => {
    const disponivel = aba.disponivel();
    const secoesHtml = aba.secoes.map(sec => `
      <label class="rel-sel-secao">
        <input type="checkbox" data-aba="${aba.id}" data-secao="${sec.id}" ${disponivel ? 'checked' : 'disabled'}>
        <span>${_rankEsc(sec.label)}</span>
      </label>`
    ).join('');

    return `
      <div class="rel-sel-aba ${disponivel ? '' : 'rel-sel-disabled'}">
        <label class="rel-sel-aba-header">
          <input type="checkbox" class="rel-sel-aba-toggle" data-aba="${aba.id}" ${disponivel ? 'checked' : 'disabled'}>
          <i class="ti ${aba.icon}"></i>
          <strong>${_rankEsc(aba.label)}</strong>
          ${disponivel ? '' : '<span class="rel-sel-badge">analise essa aba antes</span>'}
        </label>
        <div class="rel-sel-secoes">${secoesHtml}</div>
      </div>`;
  }).join('');

  modal.innerHTML = `
    <div class="modal" style="max-width:460px;width:92vw;max-height:82vh;display:flex;flex-direction:column">
      <div class="modal-title" style="display:flex;align-items:center;gap:10px">
        <i class="ti ti-list-check" style="color:var(--accent)"></i>
        O que incluir no relatório?
      </div>
      <div class="modal-sub">Marque as abas e seções que devem entrar no arquivo. Desmarcar a aba desmarca todas as seções dela.</div>
      <div style="overflow-y:auto;flex:1;margin:12px 0 14px;display:flex;flex-direction:column;gap:10px">
        ${abasHtml}
      </div>
      <div style="display:flex;justify-content:space-between;gap:10px">
        <button class="btn" onclick="document.getElementById('rel-selecao-modal').classList.remove('open')">Cancelar</button>
        <button class="btn btn-primary" onclick="_dgrGerarComSelecao('${tema}')">
          <i class="ti ti-file-analytics"></i> Gerar Relatório
        </button>
      </div>
    </div>`;

  // Aba: marcar/desmarcar o checkbox da aba propaga pra todas as seções
  // dela. Seção: desmarcar a última seção marcada de uma aba desmarca o
  // checkbox da aba automaticamente (evita "aba marcada, mas vazia por
  // dentro").
  modal.querySelectorAll('.rel-sel-aba-toggle').forEach(cbAba => {
    cbAba.addEventListener('change', () => {
      modal.querySelectorAll(`input[data-aba="${cbAba.dataset.aba}"][data-secao]`).forEach(cbSecao => {
        if (!cbSecao.disabled) cbSecao.checked = cbAba.checked;
      });
    });
  });
  modal.querySelectorAll('input[data-secao]').forEach(cbSecao => {
    cbSecao.addEventListener('change', () => {
      const abaId = cbSecao.dataset.aba;
      const algumaMarcada = [...modal.querySelectorAll(`input[data-aba="${abaId}"][data-secao]`)].some(c => c.checked);
      const cbAba = modal.querySelector(`.rel-sel-aba-toggle[data-aba="${abaId}"]`);
      if (cbAba && !cbAba.disabled) cbAba.checked = algumaMarcada;
    });
  });

  modal.classList.add('open');
};

// Lê os checkboxes marcados no modal de seleção e dispara a geração
// filtrada — se sobrar alguma aba sem nenhuma seção marcada, ela
// simplesmente não entra no objeto de seleção (gerarRelatorioGerencial
// Dashboard já ignora abas ausentes da seleção).
window._dgrGerarComSelecao = function(tema) {
  const modal = document.getElementById('rel-selecao-modal');
  const selecao = {};
  modal.querySelectorAll('input[data-secao]:checked').forEach(cb => {
    const abaId = cb.dataset.aba;
    (selecao[abaId] = selecao[abaId] || []).push(cb.dataset.secao);
  });
  modal.classList.remove('open');

  if (!Object.keys(selecao).length) {
    toast('Selecione ao menos uma seção para gerar o relatório.', 'error');
    return;
  }

  window.gerarRelatorioGerencialDashboard(tema, selecao);
};

// ── Nome do arquivo do relatório — carimbo de data/hora, sanitizado pra
//    não quebrar ao salvar em Windows/Mac. Usado pelo botão "Baixar HTML"
//    embutido no próprio relatório (ver _dgrScriptDownload). ────────────
function _dgrNomeArquivoRelatorio(prefixo) {
  const agora = new Date();
  const pad = n => String(n).padStart(2, '0');
  const carimbo = `${agora.getFullYear()}${pad(agora.getMonth() + 1)}${pad(agora.getDate())}-${pad(agora.getHours())}${pad(agora.getMinutes())}`;
  return `${prefixo}-${carimbo}.html`;
}

window.gerarRelatorioGerencialDashboard = async function(tema = 'dark', selecao = null) {
  const d = window._dgVgLastData;
  if (!d) {
    toast('Analise um período no Dashboard Gerencial antes de gerar o relatório.', 'error');
    return;
  }

  // Sem seleção explícita (ex.: chamada direta/antiga, fora do fluxo dos
  // modais) — inclui tudo que estiver disponível, mesmo comportamento de
  // antes dessa mudança (menos Giro & Cobertura, ver nota no registro).
  const secoesSelecionadas = selecao || _dgrSelecaoCompleta();

  const btn = document.getElementById('dg-btn-relatorio-gerencial');
  if (btn?.disabled) return;
  if (typeof _setBtnLoading === 'function') _setBtnLoading(btn, true, 'Gerando...');
  if (typeof showLoadingOverlay === 'function') showLoadingOverlay('Gerando relatório', 'Capturando gráficos e montando o relatório...');

  try {
    const now = new Date().toLocaleString('pt-BR');
    const periodo = (d.dtIni && d.dtFim)
      ? `${d.dtIni.toLocaleDateString('pt-BR')} a ${d.dtFim.toLocaleDateString('pt-BR')}`
      : 'Período completo';

    // Captura tudo já na cor de `tema` (fixo, sem modal de escolha — ver
    // nota acima abrirModalSelecaoRelatorioGerencial) — troca o tema do
    // Dashboard só durante a captura (escondida atrás do loading overlay)
    // e devolve a tela exatamente como estava (ver _dgrCapturarComTema).
    // Continua capturando as imagens mesmo que a seção correspondente não
    // tenha sido selecionada — condicionar a captura por seção fica pra
    // uma etapa futura, o custo da captura extra hoje é pequeno.
    const imgs = await _dgrCapturarComTema(tema, d);

    // Monta o corpo 100% a partir do registro (window._RELATORIO_ABAS_
    // REGISTRY) e da seleção do usuário — nenhuma seção fica hardcoded
    // aqui. Cada aba incluída vira um painel (.rel-aba-pane); dentro dele,
    // cada seção "compacta" vira uma página só (dgr-page-section) e a
    // marcada como "natural" (Detalhado Analítico) pagina livremente
    // (dgr-page-section-natural) — mesma regra de sempre, só que agora
    // lida pelo campo `natural` de cada seção no registro.
    let panesHtml = '';
    const abasIncluidas = [];
    window._RELATORIO_ABAS_REGISTRY.forEach(aba => {
      const secoesIds = secoesSelecionadas[aba.id];
      if (!secoesIds || !secoesIds.length || !aba.disponivel()) return;

      let secoesHtml = '';
      aba.secoes.forEach(sec => {
        if (!secoesIds.includes(sec.id)) return;
        const classe = sec.natural ? 'dgr-page-section-natural' : 'dgr-page-section';
        secoesHtml += `<section class="${classe}" data-secao-id="${sec.id}">`
          + `<button type="button" class="dgr-collapse-toggle" aria-expanded="true" onclick="_dgrToggleSecao(this)">`
          + `<i class="ti ti-chevron-down"></i><span>${_rankEsc(sec.label)}</span>`
          + `</button>`
          + `<div class="dgr-collapse-body">${sec.builder(d, imgs)}</div>`
          + `</section>`;
      });

      // O primeiro painel incluído já nasce ativo (.rel-aba-ativa) — o
      // relatório precisa mostrar algo mesmo se o JS da barra não
      // rodar por algum motivo, e é o comportamento certo pro caso de
      // hoje (1 aba só, sem barra nenhuma pra clicar).
      const ativa = abasIncluidas.length === 0 ? ' rel-aba-ativa' : '';
      panesHtml += `<div class="rel-aba-pane${ativa}" data-aba-id="${aba.id}">${secoesHtml}</div>`;
      abasIncluidas.push(aba);
    });

    // A barra só aparece com 2+ abas na seleção — com 1 só (hoje, sempre
    // Visão Geral) ela ficaria vazia de sentido (nada pra alternar).
    const abasBarHtml = abasIncluidas.length > 1
      ? `<div class="rel-aba-bar">${abasIncluidas.map((aba, i) => `
          <button type="button" class="rel-aba-btn${i === 0 ? ' active' : ''}" data-aba-id="${aba.id}" onclick="_dgrSwitchAba('${aba.id}', this)">
            <i class="ti ${aba.icon}"></i> ${_rankEsc(aba.label)}
          </button>`).join('')}</div>`
      : '';

    const bodyHtml = `<style>${_dgrEstilos()}</style>${abasBarHtml}${panesHtml}`;

    // Mesmo nome usado nos dois caminhos de download: o automático (ao
    // gerar) e o botão "Baixar HTML" embutido dentro do próprio arquivo
    // (útil pra quem reabre o arquivo depois, ou pra quem recebeu por
    // e-mail e quer salvar a cópia que está vendo).
    const nomeArquivo = _dgrNomeArquivoRelatorio('relatorio-gerencial');

    const html = _buildRankingShellHTML({
      periodoBadge: periodo,
      periodo,
      now,
      kpis: []
    }, {
      pageOrientation: 'retrato',
      paginarSecoes: true,
      temaAlternavel: true,
      temaInicial: tema === 'light' ? 'light' : 'dark',
      permitirDownload: true,
      nomeArquivoDownload: nomeArquivo,
      secoesRecolhiveis: true,
      abasNavegaveis: true,
      offlineCompleto: true,
      pageTitle:  'Relatório Gerencial — Dashboard Gerencial',
      badge:      'Relatório Gerencial',
      title:      'Visão Geral — Dashboard Gerencial',
      subtitle:   'Resumo executivo de estoque, movimentação, variação e saúde geral do período selecionado.',
      bodyHtml,
      notaRodape: 'Variação e Custo Var. desconsideram Ajustes de Fechamento Mensal não reincluídos manualmente. Saúde Geral considera os limiares configurados em Configurações → Parâmetros.'
    });

    // Abre pra conferência/impressão, como sempre. O download NÃO é mais
    // automático — o botão "Baixar HTML" dentro do relatório (action-bar)
    // baixa esse mesmo conteúdo quando o usuário efetivamente quiser.
    _openRelWindow(html);
  } catch (err) {
    console.error('[Relatório Gerencial - Dashboard] Falha ao gerar:', err);
    toast('Falha ao gerar o relatório. Veja o console para detalhes.', 'error');
  } finally {
    if (typeof _setBtnLoading === 'function') _setBtnLoading(btn, false);
    if (typeof hideLoadingOverlay === 'function') hideLoadingOverlay();
  }
};

// ═══════════════════════════════════════════════════════════════════════════════
// RELATÓRIO DE COBRANÇA POR REGIONAL — ocorrências abertas/urgentes/vencidas
// ordenadas por prioridade crítica, com filtro por regional (mesmo shell escuro
// dos relatórios de Ranking/Ausência: _buildRankingShellHTML)
// ═══════════════════════════════════════════════════════════════════════════════
window.gerarRelatorioCobrancaRegional = function(regionalFiltro) {
  const nowISO = new Date().toISOString().split('T')[0];
  const now    = new Date().toLocaleString('pt-BR');

  // ── helpers ─────────────────────────────────────────────────────────────────
  function escR(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
  function fmtBR(iso) { if (!iso) return '—'; const [y,m,d] = iso.split('-'); return `${d}/${m}/${y}`; }
  function diffDays(aISO, bISO) {
    if (!aISO || !bISO) return null;
    const a = new Date(aISO+'T00:00:00'), b = new Date(bISO+'T00:00:00');
    if (isNaN(a)||isNaN(b)) return null;
    return Math.round((b - a) / 86400000);
  }
  function ocStatus(o) {
    if (o.concluida) return 'concluida';
    if (!o.dataLimite) return 'normal';
    const d = diffDays(nowISO, o.dataLimite);
    if (d < 0)  return 'vencida';
    if (d <= 2) return 'urgente';
    return 'normal';
  }
  // Ordem numérica de prioridade para ordenação
  const statusPriority = { vencida: 0, urgente: 1, normal: 2, concluida: 9 };

  // ── mapeamento central → regional ────────────────────────────────────────────
  const centralParaRegional = {};
  (state.filiais || []).forEach(f => {
    const key = (f.origem || f.alias || '').trim().toLowerCase();
    if (key) centralParaRegional[key] = (f.regional || '').trim() || 'Sem Regional';
  });
  function getRegional(central) {
    return centralParaRegional[(central||'').trim().toLowerCase()] || 'Sem Regional';
  }

  // ── filtra só abertas (vencidas + urgentes + normais) ────────────────────────
  const abertas = (state.ocorrencias || []).filter(o => !o.concluida);

  if (!abertas.length) {
    alert('Não há ocorrências em aberto para gerar o relatório.');
    return;
  }

  // Aplica filtro de regional se informado
  const listaFiltrada = regionalFiltro
    ? abertas.filter(o => getRegional(o.central) === regionalFiltro)
    : abertas;

  if (!listaFiltrada.length) {
    alert(`Nenhuma ocorrência em aberto para o regional "${regionalFiltro}".`);
    return;
  }

  // Ordena: vencidas → urgentes → normais; dentro de cada grupo, mais antiga primeiro
  listaFiltrada.sort((a, b) => {
    const pa = statusPriority[ocStatus(a)], pb = statusPriority[ocStatus(b)];
    if (pa !== pb) return pa - pb;
    const da = a.dataLimite || '9999-12-31';
    const db = b.dataLimite || '9999-12-31';
    return da.localeCompare(db);
  });

  // ── Agrupa por regional → central ────────────────────────────────────────────
  const porRegional = {};
  listaFiltrada.forEach(o => {
    const reg = getRegional(o.central);
    const cen = o.central || '—';
    if (!porRegional[reg]) porRegional[reg] = {};
    if (!porRegional[reg][cen]) porRegional[reg][cen] = [];
    porRegional[reg][cen].push(o);
  });

  // Ordena regionais: mais vencidas primeiro
  const regionaisOrdenados = Object.entries(porRegional).sort((a, b) => {
    const countVenc = obj => Object.values(obj).flat().filter(o => ocStatus(o)==='vencida').length;
    const countUrg  = obj => Object.values(obj).flat().filter(o => ocStatus(o)==='urgente').length;
    return (countVenc(b[1])*1000 + countUrg(b[1])) - (countVenc(a[1])*1000 + countUrg(a[1]));
  });

  // ── Totais globais do relatório ───────────────────────────────────────────────
  const totalAberto  = listaFiltrada.length;
  const totalVencido = listaFiltrada.filter(o => ocStatus(o)==='vencida').length;
  const totalUrgente = listaFiltrada.filter(o => ocStatus(o)==='urgente').length;
  const totalNormal  = listaFiltrada.filter(o => ocStatus(o)==='normal').length;

  // ── Builders ─────────────────────────────────────────────────────────────────
  function buildTempoCell(o) {
    const st = ocStatus(o);
    const diasAberto = diffDays(o.dataAbertura, nowISO);
    const abertoStr = diasAberto !== null ? diasAberto+'d' : '—';

    if (st === 'vencida') {
      const diasVencido = diffDays(o.dataLimite, nowISO);
      return `<div class="oc-tempo"><span class="oc-tempo-main" style="color:#f87171">⚠ ${diasVencido}d vencido</span><span class="oc-tempo-sub">aberto há ${abertoStr}</span></div>`;
    }
    if (st === 'urgente') {
      const diasRestam = diffDays(nowISO, o.dataLimite);
      return `<div class="oc-tempo"><span class="oc-tempo-main" style="color:#fbbf24">🔔 ${diasRestam}d p/ vencer</span><span class="oc-tempo-sub">aberto há ${abertoStr}</span></div>`;
    }
    const diasRestam = o.dataLimite ? diffDays(nowISO, o.dataLimite) : null;
    return `<div class="oc-tempo">${diasRestam !== null
        ? `<span class="oc-tempo-main" style="color:#a5b4fc">${diasRestam}d restantes</span>`
        : `<span style="font-size:10.5px;color:#64748b">Sem prazo</span>`}<span class="oc-tempo-sub">aberto há ${abertoStr}</span></div>`;
  }

  function buildStatusBadge(st) {
    const cfg = {
      vencida: { cls:'oc-status-vencida', label:'VENCIDA'   },
      urgente: { cls:'oc-status-urgente', label:'URGENTE'   },
      normal:  { cls:'oc-status-normal',  label:'EM ABERTO' },
    };
    const c = cfg[st] || cfg.normal;
    return `<span class="oc-status ${c.cls}">${c.label}</span>`;
  }

  function buildOcorrenciaRow(o, idx) {
    const st = ocStatus(o);
    const leftColor = st==='vencida' ? '#ef4444' : st==='urgente' ? '#f59e0b' : 'rgba(255,255,255,.12)';
    const rowBg     = st==='vencida' ? 'rgba(239,68,68,.05)' : st==='urgente' ? 'rgba(245,158,11,.05)' : 'transparent';

    return `
    <tr style="background:${rowBg};box-shadow:inset 3px 0 0 ${leftColor}">
      <td class="rk-num" style="color:#64748b;font-size:10px">${idx+1}</td>
      <td>${buildStatusBadge(st)}</td>
      <td>
        <div style="font-weight:700;font-size:11.5px;color:#f1f5f9;font-family:'JetBrains Mono',monospace">${escR(o.id)}</div>
        ${o.motivo ? `<div style="font-size:9.5px;color:#64748b;margin-top:2px">${escR(o.motivo)}</div>` : ''}
      </td>
      <td class="rk-name" style="font-size:12px">${escR(o.central||'—')}</td>
      <td style="font-size:11.5px;color:#cbd5e1">${escR(o.material||'—')}</td>
      <td style="font-size:10.5px;color:#94a3b8">
        <div>${fmtBR(o.dataAbertura)}</div>
        ${o.dataLimite ? `<div style="color:${st==='vencida'?'#f87171':st==='urgente'?'#fbbf24':'#64748b'};font-size:9.5px;margin-top:2px">prazo: ${fmtBR(o.dataLimite)}</div>` : ''}
      </td>
      <td>${buildTempoCell(o)}</td>
      <td style="font-size:11.5px;color:#cbd5e1;max-width:240px">
        <div style="overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;line-height:1.4">${escR(o.descricao||'—')}</div>
      </td>
      <td style="font-size:10.5px;color:#94a3b8">
        <div>${escR(o.operador||'—')}</div>
        ${o.contato ? `<div style="color:#64748b;margin-top:2px">${escR(o.contato)}</div>` : ''}
      </td>
    </tr>`;
  }

  function buildCentralSection(centralNome, ocorrencias) {
    const venc = ocorrencias.filter(o => ocStatus(o)==='vencida').length;
    const urg  = ocorrencias.filter(o => ocStatus(o)==='urgente').length;
    const norm = ocorrencias.filter(o => ocStatus(o)==='normal').length;
    const piorSt = venc > 0 ? 'vencida' : urg > 0 ? 'urgente' : 'normal';
    const accent = piorSt==='vencida' ? '#ef4444' : piorSt==='urgente' ? '#f59e0b' : '#64748b';

    const badges = [
      venc > 0 ? `<span class="oc-mini-badge" style="color:#fca5a5">🔴 ${venc} vencida${venc!==1?'s':''}</span>` : '',
      urg  > 0 ? `<span class="oc-mini-badge" style="color:#fde68a">🟡 ${urg} urgente${urg!==1?'s':''}</span>` : '',
      norm > 0 ? `<span class="oc-mini-badge" style="color:#93c5fd">🔵 ${norm} em aberto</span>` : '',
    ].filter(Boolean).join(' ');

    return `
    <div class="oc-central-block">
      <div class="oc-central-hdr" style="background:rgba(255,255,255,.035);border-bottom:1px solid rgba(255,255,255,.08)">
        <div class="oc-central-hdr-left">
          <span style="width:5px;height:22px;border-radius:3px;background:${accent};flex-shrink:0;display:inline-block"></span>
          <span class="oc-central-name">${escR(centralNome)}</span>
        </div>
        <div style="display:flex;gap:6px;flex-wrap:wrap">${badges}</div>
      </div>
      <table class="rk-table">
        <thead>
          <tr>
            <th style="width:26px">#</th><th style="width:82px">Status</th><th style="width:88px">ID / Motivo</th>
            <th>Central</th><th>Material</th><th style="width:100px">Datas</th>
            <th style="width:125px">Prazo / Tempo</th><th>Descrição</th><th style="width:105px">Responsável</th>
          </tr>
        </thead>
        <tbody>${ocorrencias.map(buildOcorrenciaRow).join('')}</tbody>
      </table>
    </div>`;
  }

  function buildRegionalSection([regNome, centrais]) {
    const todasOc  = Object.values(centrais).flat();
    const regVenc  = todasOc.filter(o => ocStatus(o)==='vencida').length;
    const regUrg   = todasOc.filter(o => ocStatus(o)==='urgente').length;
    const regNorm  = todasOc.filter(o => ocStatus(o)==='normal').length;
    const regTotal = todasOc.length;
    const piorSt   = regVenc > 0 ? 'vencida' : regUrg > 0 ? 'urgente' : 'normal';
    const regBg    = piorSt==='vencida'
      ? 'linear-gradient(135deg,#7f1d1d 0%,#991b1b 60%,#b91c1c 100%)'
      : piorSt==='urgente'
      ? 'linear-gradient(135deg,#78350f 0%,#92400e 60%,#b45309 100%)'
      : 'linear-gradient(135deg,#1e3a5f 0%,#1e40af 60%,#2563eb 100%)';

    const centraisOrdenadas = Object.entries(centrais).sort((a, b) => {
      const sv = x => x.filter(o => ocStatus(o)==='vencida').length;
      const su = x => x.filter(o => ocStatus(o)==='urgente').length;
      return (sv(b[1])*100 + su(b[1])) - (sv(a[1])*100 + su(a[1]));
    });

    return `
    <div class="oc-regional-section">
      <div class="oc-regional-hdr" style="background:${regBg}">
        <div style="display:flex;align-items:center;gap:14px;position:relative">
          <div class="oc-regional-icon"><i class="ti ti-map-2"></i></div>
          <div>
            <div class="oc-regional-name">${escR(regNome)}</div>
            <div class="oc-regional-sub">${centraisOrdenadas.length} ${centraisOrdenadas.length!==1?'centrais':'central'} · ${regTotal} ocorrência${regTotal!==1?'s':''}</div>
          </div>
        </div>
        <div class="oc-regional-stats">
          <div class="oc-regional-stat"><strong style="color:#fca5a5">${regVenc}</strong><span>Vencidas</span></div>
          <div class="oc-regional-stat-sep"></div>
          <div class="oc-regional-stat"><strong style="color:#fde68a">${regUrg}</strong><span>Urgentes</span></div>
          <div class="oc-regional-stat-sep"></div>
          <div class="oc-regional-stat"><strong style="color:#bfdbfe">${regNorm}</strong><span>Em Aberto</span></div>
        </div>
      </div>
      <div class="oc-regional-body">
        ${centraisOrdenadas.map(([cn, ocs]) => buildCentralSection(cn, ocs)).join('')}
      </div>
    </div>`;
  }

  // ── bodyHtml ──────────────────────────────────────────────────────────────────
  const tituloFiltro = regionalFiltro ? ` — ${regionalFiltro}` : ' — Todos os Regionais';

  const bodyHtml = `
    <style>
      .oc-status { display:inline-block; padding:3px 9px; border-radius:12px; font-size:9.5px; font-weight:800; letter-spacing:.05em; white-space:nowrap; }
      .oc-status-vencida { background:rgba(239,68,68,.15); color:#fca5a5; border:1px solid rgba(239,68,68,.4); }
      .oc-status-urgente { background:rgba(245,158,11,.15); color:#fde68a; border:1px solid rgba(245,158,11,.4); }
      .oc-status-normal  { background:rgba(59,130,246,.15); color:#93c5fd; border:1px solid rgba(59,130,246,.4); }

      .oc-tempo { display:flex; flex-direction:column; gap:3px; }
      .oc-tempo-main { font-size:10.5px; font-family:'JetBrains Mono',monospace; font-weight:800; white-space:nowrap; }
      .oc-tempo-sub { font-size:9.5px; color:#64748b; font-family:'JetBrains Mono',monospace; white-space:nowrap; }

      .oc-regional-section { margin-bottom:26px; }
      .oc-regional-section:last-child { margin-bottom:0; }
      .oc-regional-hdr { border-radius:12px 12px 0 0; padding:16px 22px; display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:12px; position:relative; overflow:hidden; }
      .oc-regional-hdr::before { content:''; position:absolute; right:-20px; top:-20px; width:100px; height:100px; border-radius:50%; background:rgba(255,255,255,.06); pointer-events:none; }
      .oc-regional-icon { width:38px; height:38px; border-radius:9px; background:rgba(255,255,255,.15); border:1px solid rgba(255,255,255,.25); display:flex; align-items:center; justify-content:center; flex-shrink:0; }
      .oc-regional-icon i { color:#fff; font-size:17px; }
      .oc-regional-name { font-size:16px; font-weight:900; color:#fff; letter-spacing:-.01em; }
      .oc-regional-sub { font-size:10.5px; color:rgba(255,255,255,.62); margin-top:2px; }
      .oc-regional-stats { display:flex; align-items:center; position:relative; }
      .oc-regional-stat { text-align:center; padding:0 16px; }
      .oc-regional-stat strong { display:block; font-size:22px; font-weight:800; font-family:'JetBrains Mono',monospace; line-height:1; }
      .oc-regional-stat span { font-size:9px; text-transform:uppercase; letter-spacing:.05em; color:rgba(255,255,255,.6); font-weight:700; margin-top:3px; display:block; }
      .oc-regional-stat-sep { width:1px; height:34px; background:rgba(255,255,255,.2); }
      .oc-regional-body { background:rgba(255,255,255,.025); border:1px solid rgba(255,255,255,.09); border-top:none; border-radius:0 0 12px 12px; padding:14px; }

      .oc-central-block { margin-bottom:14px; border-radius:10px; overflow:hidden; border:1px solid rgba(255,255,255,.09); page-break-inside:avoid; }
      .oc-central-block:last-child { margin-bottom:0; }
      .oc-central-hdr { padding:10px 16px; display:flex; align-items:center; justify-content:space-between; gap:12px; flex-wrap:wrap; }
      .oc-central-hdr-left { display:flex; align-items:center; gap:10px; }
      .oc-central-name { font-size:13px; font-weight:800; color:#fff; }
      .oc-mini-badge { padding:2px 8px; border-radius:10px; font-size:9px; font-weight:700; background:rgba(255,255,255,.06); border:1px solid rgba(255,255,255,.12); }
    </style>

    <div class="rk-table-head" style="margin-bottom:16px">
      <div class="rk-table-head-title">${escR(regionalFiltro ? regionalFiltro : 'Todos os Regionais')}</div>
      <div class="rk-table-head-cap">ocorrências em aberto por prioridade</div>
    </div>

    ${regionaisOrdenados.map(buildRegionalSection).join('')}`;

  const d = {
    periodoBadge: now.split(' ')[0],
    periodo: 'Ocorrências em aberto',
    now,
    kpis: [
      { value: totalAberto,  label: 'total em aberto', color: '#94a3b8' },
      { value: totalVencido, label: 'vencidas',        color: '#ef4444' },
      { value: totalUrgente, label: 'urgentes',        color: '#f59e0b' },
      { value: totalNormal,  label: 'em prazo',        color: '#3b82f6' }
    ]
  };

  const html = _buildRankingShellHTML(d, {
    pageTitle:  `Relatório de Cobrança por Regional${tituloFiltro}`,
    badge:      'Cobrança de Pendências',
    title:      'Cobrança Regional — Ocorrências em Aberto',
    subtitle:   `Ocorrências em aberto ordenadas por prioridade crítica${regionalFiltro ? ' · ' + escR(regionalFiltro) : ', agrupadas por regional e central'}.`,
    bodyHtml,
    notaRodape: 'Vencida: prazo expirado. Urgente: vence em até 2 dias. Regionais e centrais ordenados por quantidade de ocorrências vencidas/urgentes.'
  });

  _openRelWindow(html);
};

// ── Modal de seleção de regional para o Relatório 2 ─────────────────────────
window.abrirSeletorRegionalOcorrencias = function() {
  const nowISO = new Date().toISOString().split('T')[0];
  const centralParaRegional = {};
  (state.filiais || []).forEach(f => {
    const key = (f.origem || f.alias || '').trim().toLowerCase();
    if (key) centralParaRegional[key] = (f.regional || '').trim() || 'Sem Regional';
  });
  function getRegional(central) {
    return centralParaRegional[(central||'').trim().toLowerCase()] || 'Sem Regional';
  }

  const abertas = (state.ocorrencias || []).filter(o => !o.concluida);
  if (!abertas.length) {
    alert('Não há ocorrências em aberto para gerar o relatório.');
    return;
  }

  // Monta contagem por regional para exibir no modal
  const porRegional = {};
  abertas.forEach(o => {
    const reg = getRegional(o.central);
    if (!porRegional[reg]) porRegional[reg] = { vencidas:0, urgentes:0, total:0 };
    porRegional[reg].total++;
    if (!o.dataLimite) return;
    const d = Math.round((new Date(o.dataLimite+'T00:00:00') - new Date(nowISO+'T00:00:00')) / 86400000);
    if (d < 0) porRegional[reg].vencidas++;
    else if (d <= 2) porRegional[reg].urgentes++;
  });

  const regionais = Object.entries(porRegional).sort((a, b) => {
    return (b[1].vencidas*1000 + b[1].urgentes*100 + b[1].total) - (a[1].vencidas*1000 + a[1].urgentes*100 + a[1].total);
  });

  // Cria o modal dinamicamente se não existir
  let modal = document.getElementById('oc-rel-regional-modal');
  if (!modal) {
    modal = document.createElement('div');
    modal.id = 'oc-rel-regional-modal';
    modal.className = 'modal-overlay';
    modal.style.cssText = 'z-index:3200';
    document.body.appendChild(modal);
  }

  const opcoesHtml = regionais.map(([reg, c]) => {
    const vBadge = c.vencidas > 0 ? `<span style="padding:2px 8px;border-radius:10px;font-size:10px;font-weight:700;background:#fef2f2;color:#ef4444;border:1px solid #fca5a5">🔴 ${c.vencidas}</span>` : '';
    const uBadge = c.urgentes > 0 ? `<span style="padding:2px 8px;border-radius:10px;font-size:10px;font-weight:700;background:#fffbeb;color:#d97706;border:1px solid #fde68a">🟡 ${c.urgentes}</span>` : '';
    return `<button onclick="document.getElementById('oc-rel-regional-modal').classList.remove('open');gerarRelatorioCobrancaRegional('${reg.replace(/'/g,"\\'")}');"
      style="display:flex;align-items:center;justify-content:space-between;width:100%;padding:12px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;cursor:pointer;font-size:13px;font-family:inherit;color:#0f172a;font-weight:600;transition:background .12s;text-align:left;gap:10px"
      onmouseover="this.style.background='#eff6ff'" onmouseout="this.style.background='#f8fafc'">
      <span>${reg}</span>
      <span style="display:flex;align-items:center;gap:6px">
        ${vBadge}${uBadge}
        <span style="font-size:11px;color:#94a3b8;font-family:'DM Mono',monospace">${c.total} oc.</span>
      </span>
    </button>`;
  }).join('');

  modal.innerHTML = `
    <div class="modal" style="max-width:480px;width:94vw">
      <div class="modal-title" style="display:flex;align-items:center;gap:10px">
        <i class="ti ti-map-pin" style="color:var(--amber)"></i>
        Relatório de Cobrança por Regional
      </div>
      <div class="modal-sub">Selecione o regional ou gere para todos</div>
      <div style="display:flex;flex-direction:column;gap:8px;margin:16px 0">
        <button onclick="document.getElementById('oc-rel-regional-modal').classList.remove('open');gerarRelatorioCobrancaRegional(null);"
          style="display:flex;align-items:center;justify-content:space-between;width:100%;padding:12px 16px;background:linear-gradient(135deg,#1e3a5f,#1e40af);border:none;border-radius:8px;cursor:pointer;font-size:13px;font-family:inherit;color:#fff;font-weight:700;gap:10px"
          onmouseover="this.style.opacity='.9'" onmouseout="this.style.opacity='1'">
          <span>🗺 Todos os Regionais</span>
          <span style="font-size:11px;opacity:.7">${abertas.length} ocorrências no total</span>
        </button>
        <div style="font-size:11px;color:var(--text3);text-transform:uppercase;letter-spacing:.06em;margin:4px 0 2px;padding:0 2px">ou escolha um regional</div>
        ${opcoesHtml}
      </div>
      <div style="display:flex;justify-content:flex-end;margin-top:8px">
        <button class="btn" onclick="document.getElementById('oc-rel-regional-modal').classList.remove('open')">Cancelar</button>
      </div>
    </div>`;

  modal.classList.add('open');
};

// ═══════════════════════════════════════════════════════════════════════════════
// RELATÓRIO DE COBRANÇA GERAL POR CENTRAL — todas as ocorrências abertas
// agrupadas por central, com colunas de tempo detalhadas, para cobrança ampla
// (mesmo shell escuro dos relatórios de Ranking/Ausência: _buildRankingShellHTML)
// ═══════════════════════════════════════════════════════════════════════════════
window.gerarRelatorioCobrancaCentral = function(centralFiltro) {
  const nowISO = new Date().toISOString().split('T')[0];
  const now    = new Date().toLocaleString('pt-BR');

  // ── helpers ─────────────────────────────────────────────────────────────────
  function escR(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
  function fmtBR(iso) { if (!iso) return '—'; const [y,m,d] = iso.split('-'); return `${d}/${m}/${y}`; }
  function diffDays(aISO, bISO) {
    if (!aISO || !bISO) return null;
    const a = new Date(aISO+'T00:00:00'), b = new Date(bISO+'T00:00:00');
    if (isNaN(a)||isNaN(b)) return null;
    return Math.round((b - a) / 86400000);
  }
  function ocStatus(o) {
    if (o.concluida) return 'concluida';
    if (!o.dataLimite) return 'normal';
    const d = diffDays(nowISO, o.dataLimite);
    if (d < 0)  return 'vencida';
    if (d <= 2) return 'urgente';
    return 'normal';
  }
  const statusPriority = { vencida:0, urgente:1, normal:2, concluida:9 };

  // ── mapeamento central → regional ────────────────────────────────────────────
  const centralParaRegional = {};
  (state.filiais || []).forEach(f => {
    const key = (f.origem || f.alias || '').trim().toLowerCase();
    if (key) centralParaRegional[key] = (f.regional || '').trim() || 'Sem Regional';
  });
  function getRegional(central) {
    return centralParaRegional[(central||'').trim().toLowerCase()] || 'Sem Regional';
  }

  // ── filtra só abertas ────────────────────────────────────────────────────────
  const todasAbertas = (state.ocorrencias || []).filter(o => !o.concluida);
  if (!todasAbertas.length) {
    alert('Não há ocorrências em aberto para gerar o relatório.');
    return;
  }

  const abertas = centralFiltro
    ? todasAbertas.filter(o => (o.central || '—') === centralFiltro)
    : todasAbertas;

  if (!abertas.length) {
    alert(`Nenhuma ocorrência em aberto para a central "${centralFiltro}".`);
    return;
  }

  abertas.sort((a, b) => {
    const pa = statusPriority[ocStatus(a)], pb = statusPriority[ocStatus(b)];
    if (pa !== pb) return pa - pb;
    return (a.dataLimite||'9999-12-31').localeCompare(b.dataLimite||'9999-12-31');
  });

  // ── Agrupa por central ───────────────────────────────────────────────────────
  const porCentral = {};
  abertas.forEach(o => {
    const c = o.central || '—';
    if (!porCentral[c]) porCentral[c] = [];
    porCentral[c].push(o);
  });

  const centraisOrdenadas = Object.entries(porCentral).sort((a, b) => {
    const sv = arr => arr.filter(o => ocStatus(o)==='vencida').length;
    const su = arr => arr.filter(o => ocStatus(o)==='urgente').length;
    return (sv(b[1])*1000 + su(b[1])*100 + b[1].length) -
           (sv(a[1])*1000 + su(a[1])*100 + a[1].length);
  });

  // ── Totais globais ───────────────────────────────────────────────────────────
  const totalAberto  = abertas.length;
  const totalVencido = abertas.filter(o => ocStatus(o)==='vencida').length;
  const totalUrgente = abertas.filter(o => ocStatus(o)==='urgente').length;
  const totalNormal  = abertas.filter(o => ocStatus(o)==='normal').length;
  const totalCentral = centraisOrdenadas.length;

  // ── Célula de tempo ──────────────────────────────────────────────────────────
  function buildTempoCell(o) {
    const st = ocStatus(o);
    const diasAberto = diffDays(o.dataAbertura, nowISO);
    const abertoStr  = diasAberto !== null ? diasAberto+'d' : '—';

    if (st === 'vencida') {
      const diasVencido = diffDays(o.dataLimite, nowISO);
      return `<div class="oc-tempo"><span class="oc-tempo-chip" style="background:rgba(239,68,68,.14);border:1px solid rgba(239,68,68,.4);color:#fca5a5">⚠ ${diasVencido}d vencido</span><span class="oc-tempo-sub">em aberto há ${abertoStr}</span></div>`;
    }
    if (st === 'urgente') {
      const diasRestam = diffDays(nowISO, o.dataLimite);
      return `<div class="oc-tempo"><span class="oc-tempo-chip" style="background:rgba(245,158,11,.14);border:1px solid rgba(245,158,11,.4);color:#fde68a">🔔 ${diasRestam}d p/ vencer</span><span class="oc-tempo-sub">em aberto há ${abertoStr}</span></div>`;
    }
    const diasRestam = o.dataLimite ? diffDays(nowISO, o.dataLimite) : null;
    return `<div class="oc-tempo">${diasRestam !== null
        ? `<span class="oc-tempo-chip" style="background:rgba(59,130,246,.14);border:1px solid rgba(59,130,246,.35);color:#93c5fd">📅 ${diasRestam}d restantes</span>`
        : `<span style="font-size:10.5px;color:#64748b">Sem prazo</span>`}<span class="oc-tempo-sub">em aberto há ${abertoStr}</span></div>`;
  }

  function buildStatusBadge(st) {
    const cfg = {
      vencida: { cls:'oc-status-vencida', label:'VENCIDA'   },
      urgente: { cls:'oc-status-urgente', label:'URGENTE'   },
      normal:  { cls:'oc-status-normal',  label:'EM ABERTO' },
    };
    const c = cfg[st] || cfg.normal;
    return `<span class="oc-status ${c.cls}">${c.label}</span>`;
  }

  function buildOcorrenciaRow(o, idx) {
    const st = ocStatus(o);
    const leftColor = st==='vencida' ? '#ef4444' : st==='urgente' ? '#f59e0b' : 'rgba(255,255,255,.12)';
    const rowBg     = st==='vencida' ? 'rgba(239,68,68,.05)' : st==='urgente' ? 'rgba(245,158,11,.05)' : 'transparent';

    return `
    <tr style="background:${rowBg};box-shadow:inset 3px 0 0 ${leftColor}">
      <td class="rk-num" style="color:#64748b;font-size:10px">${idx+1}</td>
      <td>${buildStatusBadge(st)}</td>
      <td>
        <div style="font-weight:700;font-size:11.5px;color:#f1f5f9;font-family:'JetBrains Mono',monospace">${escR(o.id)}</div>
        ${o.motivo ? `<div style="font-size:9.5px;color:#64748b;margin-top:1px">${escR(o.motivo)}</div>` : ''}
      </td>
      <td style="font-size:11.5px;color:#cbd5e1">${escR(o.material||'—')}</td>
      <td style="font-size:10.5px;color:#94a3b8">
        <div>${fmtBR(o.dataAbertura)}</div>
        ${o.dataLimite ? `<div style="color:${st==='vencida'?'#f87171':st==='urgente'?'#fbbf24':'#64748b'};font-size:9.5px;margin-top:1px">prazo: ${fmtBR(o.dataLimite)}</div>` : ''}
      </td>
      <td>${buildTempoCell(o)}</td>
      <td style="font-size:11.5px;color:#cbd5e1;max-width:220px">
        <div style="overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;line-height:1.4">${escR(o.descricao||'—')}</div>
      </td>
      <td style="font-size:10.5px;color:#94a3b8">
        <div>${escR(o.operador||'—')}</div>
        ${o.contato ? `<div style="color:#64748b;font-size:9.5px;margin-top:1px">${escR(o.contato)}</div>` : ''}
      </td>
    </tr>`;
  }

  function buildCentralSection([centralNome, ocorrencias], idx) {
    const venc = ocorrencias.filter(o => ocStatus(o)==='vencida').length;
    const urg  = ocorrencias.filter(o => ocStatus(o)==='urgente').length;
    const norm = ocorrencias.filter(o => ocStatus(o)==='normal').length;
    const reg  = getRegional(centralNome);
    const piorSt = venc > 0 ? 'vencida' : urg > 0 ? 'urgente' : 'normal';
    const hdrGrad = piorSt==='vencida'
      ? 'linear-gradient(135deg,#7f1d1d 0%,#991b1b 60%,#b91c1c 100%)'
      : piorSt==='urgente'
      ? 'linear-gradient(135deg,#78350f 0%,#92400e 60%,#b45309 100%)'
      : 'linear-gradient(135deg,#1e3a5f 0%,#1e40af 60%,#2563eb 100%)';

    const badges = [
      venc > 0 ? `<span class="oc-mini-badge" style="color:#fca5a5">🔴 ${venc} vencida${venc!==1?'s':''}</span>` : '',
      urg  > 0 ? `<span class="oc-mini-badge" style="color:#fde68a">🟡 ${urg} urgente${urg!==1?'s':''}</span>` : '',
      norm > 0 ? `<span class="oc-mini-badge" style="color:#bfdbfe">🔵 ${norm} em aberto</span>` : '',
    ].filter(Boolean).join(' ');

    return `
    <div class="oc-central-card" id="oc-central-${idx}">
      <div class="oc-central-card-hdr" style="background:${hdrGrad}">
        <div style="display:flex;align-items:center;gap:10px;position:relative">
          <div class="oc-central-num">${idx+1}</div>
          <div>
            <div class="oc-central-card-name">${escR(centralNome)}</div>
            <div class="oc-central-card-sub">${escR(reg)} · ${ocorrencias.length} ocorrência${ocorrencias.length!==1?'s':''}</div>
          </div>
        </div>
        <div style="display:flex;gap:6px;flex-wrap:wrap;position:relative">${badges}</div>
      </div>
      <table class="rk-table">
        <thead>
          <tr>
            <th style="width:26px">#</th><th style="width:82px">Status</th><th style="width:88px">ID / Motivo</th>
            <th>Material</th><th style="width:95px">Datas</th><th style="width:135px">Prazo / Tempo</th>
            <th>Descrição</th><th style="width:100px">Responsável</th>
          </tr>
        </thead>
        <tbody>${ocorrencias.map(buildOcorrenciaRow).join('')}</tbody>
      </table>
    </div>`;
  }

  function buildSumario() {
    return centraisOrdenadas.slice(0, 20).map(([cn, ocs], idx) => {
      const venc = ocs.filter(o => ocStatus(o)==='vencida').length;
      const urg  = ocs.filter(o => ocStatus(o)==='urgente').length;
      const total = ocs.length;
      const cor  = venc > 0 ? '#f87171' : urg > 0 ? '#fbbf24' : '#93c5fd';
      const barW = Math.round(total / (centraisOrdenadas[0][1].length || 1) * 100);
      return `
      <a href="#oc-central-${idx}" class="oc-sumario-item">
        <span class="oc-sumario-idx">${idx+1}</span>
        <div style="flex:1;min-width:0">
          <div class="oc-sumario-name">${escR(cn)}</div>
          <div style="display:flex;align-items:center;gap:5px;margin-top:3px">
            <div class="oc-bar-track"><div class="oc-bar-fill" style="width:${barW}%;background:${cor}"></div></div>
            <span style="font-size:9.5px;font-family:'JetBrains Mono',monospace;color:#64748b;min-width:18px;text-align:right">${total}</span>
          </div>
        </div>
        <div style="display:flex;gap:4px;flex-shrink:0">
          ${venc>0 ? `<span class="oc-sumario-tag" style="color:#fca5a5">${venc}</span>` : ''}
          ${urg>0  ? `<span class="oc-sumario-tag" style="color:#fde68a">${urg}</span>`  : ''}
        </div>
      </a>`;
    }).join('');
  }

  // ── bodyHtml ──────────────────────────────────────────────────────────────────
  const bodyHtml = `
    <style>
      .oc-status { display:inline-block; padding:3px 9px; border-radius:12px; font-size:9.5px; font-weight:800; letter-spacing:.05em; white-space:nowrap; }
      .oc-status-vencida { background:rgba(239,68,68,.15); color:#fca5a5; border:1px solid rgba(239,68,68,.4); }
      .oc-status-urgente { background:rgba(245,158,11,.15); color:#fde68a; border:1px solid rgba(245,158,11,.4); }
      .oc-status-normal  { background:rgba(59,130,246,.15); color:#93c5fd; border:1px solid rgba(59,130,246,.4); }

      .oc-tempo { display:flex; flex-direction:column; gap:4px; }
      .oc-tempo-chip { display:inline-flex; align-items:center; gap:4px; padding:3px 8px; border-radius:6px; font-size:10.5px; font-family:'JetBrains Mono',monospace; font-weight:800; white-space:nowrap; width:fit-content; }
      .oc-tempo-sub { font-size:9.5px; color:#64748b; font-family:'JetBrains Mono',monospace; white-space:nowrap; padding-left:2px; }

      .oc-mini-badge { padding:2px 8px; border-radius:10px; font-size:9px; font-weight:700; background:rgba(255,255,255,.13); border:1px solid rgba(255,255,255,.2); }

      .oc-central-card { margin-bottom:16px; border-radius:10px; overflow:hidden; border:1px solid rgba(255,255,255,.09); page-break-inside:avoid; }
      .oc-central-card:last-child { margin-bottom:0; }
      .oc-central-card-hdr { padding:12px 18px; display:flex; align-items:center; justify-content:space-between; gap:12px; flex-wrap:wrap; }
      .oc-central-num { width:26px; height:26px; border-radius:7px; background:rgba(255,255,255,.15); border:1px solid rgba(255,255,255,.22); display:flex; align-items:center; justify-content:center; font-size:11.5px; font-weight:800; color:#fff; font-family:'JetBrains Mono',monospace; flex-shrink:0; }
      .oc-central-card-name { font-size:14px; font-weight:800; color:#fff; letter-spacing:-.01em; }
      .oc-central-card-sub { font-size:10px; color:rgba(255,255,255,.6); margin-top:1px; }

      .oc-layout { display:grid; grid-template-columns:220px 1fr; gap:22px; align-items:start; }
      .oc-sumario-col { position:sticky; top:78px; background:rgba(255,255,255,.03); border:1px solid rgba(255,255,255,.09); border-radius:10px; overflow:hidden; }
      .oc-sumario-hdr { background:rgba(255,255,255,.04); border-bottom:1px solid rgba(255,255,255,.08); padding:10px 14px; font-size:10.5px; font-weight:800; color:#94a3b8; text-transform:uppercase; letter-spacing:.06em; }
      .oc-sumario-body { padding:4px 12px 10px; max-height:calc(100vh - 140px); overflow-y:auto; }
      .oc-sumario-item { display:flex; align-items:center; gap:9px; padding:7px 0; border-bottom:1px solid rgba(255,255,255,.06); text-decoration:none; }
      .oc-sumario-item:last-child { border-bottom:none; }
      .oc-sumario-idx { font-size:9.5px; font-family:'JetBrains Mono',monospace; color:#64748b; min-width:16px; font-weight:700; }
      .oc-sumario-name { font-size:11px; font-weight:700; color:#e2e8f0; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
      .oc-sumario-tag { padding:1px 6px; border-radius:8px; font-size:8.5px; font-weight:800; background:rgba(255,255,255,.08); }
      .oc-bar-track { flex:1; height:4px; background:rgba(255,255,255,.09); border-radius:2px; overflow:hidden; }
      .oc-bar-fill { height:100%; border-radius:2px; }

      @media (max-width:900px) { .oc-layout { grid-template-columns:1fr; } .oc-sumario-col { position:static; } }
      @media print { .oc-sumario-col { display:none; } .oc-layout { display:block; } }
    </style>

    <div class="oc-layout">
      <div class="oc-sumario-col">
        <div class="oc-sumario-hdr"><i class="ti ti-list-details"></i> Índice de Centrais</div>
        <div class="oc-sumario-body">
          ${buildSumario()}
          ${centraisOrdenadas.length > 20 ? `<div style="padding:8px 0;font-size:9.5px;color:#64748b;font-style:italic">+ ${centraisOrdenadas.length - 20} centrais adicionais</div>` : ''}
        </div>
      </div>
      <div>
        <div class="rk-table-head" style="margin-bottom:14px">
          <div class="rk-table-head-title">${totalCentral} Centra${totalCentral!==1?'is':'l'}</div>
          <div class="rk-table-head-cap">ocorrências em aberto por prioridade</div>
        </div>
        ${centraisOrdenadas.map(buildCentralSection).join('')}
      </div>
    </div>`;

  const d = {
    periodoBadge: now.split(' ')[0],
    periodo: 'Ocorrências em aberto',
    now,
    kpis: [
      { value: totalAberto,  label: 'total em aberto', color: '#94a3b8' },
      { value: totalVencido, label: 'vencidas',        color: '#ef4444' },
      { value: totalUrgente, label: 'urgentes',        color: '#f59e0b' },
      { value: totalNormal,  label: 'em prazo',        color: '#3b82f6' }
    ]
  };

  const html = _buildRankingShellHTML(d, {
    pageTitle:  'Relatório de Cobrança Geral por Central',
    badge:      'Cobrança de Pendências',
    title:      'Cobrança por Central — Ocorrências em Aberto',
    subtitle:   `Ocorrências em aberto agrupadas por central, ordenadas por criticidade${centralFiltro ? ' · ' + escR(centralFiltro) : ''}.`,
    bodyHtml,
    notaRodape: 'Vencida: prazo expirado. Urgente: vence em até 2 dias. Centrais ordenadas por quantidade de ocorrências vencidas/urgentes.'
  });

  _openRelWindow(html);
};

// ── Modal de seleção de central para o Relatório 3 ──────────────────────────
window.abrirSeletorCentralOcorrencias = function() {
  const nowISO = new Date().toISOString().split('T')[0];

  const abertas = (state.ocorrencias || []).filter(o => !o.concluida);
  if (!abertas.length) {
    alert('Não há ocorrências em aberto para gerar o relatório.');
    return;
  }

  // Monta contagem por central para exibir no modal
  const porCentral = {};
  abertas.forEach(o => {
    const c = o.central || '—';
    if (!porCentral[c]) porCentral[c] = { vencidas:0, urgentes:0, total:0 };
    porCentral[c].total++;
    if (!o.dataLimite) return;
    const d = Math.round((new Date(o.dataLimite+'T00:00:00') - new Date(nowISO+'T00:00:00')) / 86400000);
    if (d < 0) porCentral[c].vencidas++;
    else if (d <= 2) porCentral[c].urgentes++;
  });

  // Ordena: mais vencidas → mais urgentes → mais abertas
  const centrais = Object.entries(porCentral).sort((a, b) =>
    (b[1].vencidas*1000 + b[1].urgentes*100 + b[1].total) -
    (a[1].vencidas*1000 + a[1].urgentes*100 + a[1].total)
  );

  // Cria o modal dinamicamente se não existir
  let modal = document.getElementById('oc-rel-central-modal');
  if (!modal) {
    modal = document.createElement('div');
    modal.id = 'oc-rel-central-modal';
    modal.className = 'modal-overlay';
    modal.style.cssText = 'z-index:3200';
    document.body.appendChild(modal);
  }

  const opcoesHtml = centrais.map(([central, c]) => {
    const vBadge = c.vencidas > 0 ? `<span style="padding:2px 8px;border-radius:10px;font-size:10px;font-weight:700;background:#fef2f2;color:#ef4444;border:1px solid #fca5a5">🔴 ${c.vencidas}</span>` : '';
    const uBadge = c.urgentes > 0 ? `<span style="padding:2px 8px;border-radius:10px;font-size:10px;font-weight:700;background:#fffbeb;color:#d97706;border:1px solid #fde68a">🟡 ${c.urgentes}</span>` : '';
    const safe = central.replace(/\\/g,'\\\\').replace(/'/g,"\\'");
    return `<button onclick="document.getElementById('oc-rel-central-modal').classList.remove('open');gerarRelatorioCobrancaCentral('${safe}');"
      style="display:flex;align-items:center;justify-content:space-between;width:100%;padding:12px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;cursor:pointer;font-size:13px;font-family:inherit;color:#0f172a;font-weight:600;transition:background .12s;text-align:left;gap:10px"
      onmouseover="this.style.background='#eff6ff'" onmouseout="this.style.background='#f8fafc'">
      <span>${central}</span>
      <span style="display:flex;align-items:center;gap:6px">
        ${vBadge}${uBadge}
        <span style="font-size:11px;color:#94a3b8;font-family:'DM Mono',monospace">${c.total} oc.</span>
      </span>
    </button>`;
  }).join('');

  modal.innerHTML = `
    <div class="modal" style="max-width:480px;width:94vw;max-height:88vh;overflow:hidden;display:flex;flex-direction:column">
      <div class="modal-title" style="display:flex;align-items:center;gap:10px;flex-shrink:0">
        <i class="ti ti-building-factory-2" style="color:var(--accent)"></i>
        Relatório de Cobrança por Central
      </div>
      <div class="modal-sub" style="flex-shrink:0">Selecione a central ou gere para todas</div>
      <div style="display:flex;flex-direction:column;gap:8px;margin:16px 0;overflow-y:auto;flex:1;padding-right:2px">
        <button onclick="document.getElementById('oc-rel-central-modal').classList.remove('open');gerarRelatorioCobrancaCentral(null);"
          style="display:flex;align-items:center;justify-content:space-between;width:100%;padding:12px 16px;background:linear-gradient(135deg,#3730a3,#4f46e5);border:none;border-radius:8px;cursor:pointer;font-size:13px;font-family:inherit;color:#fff;font-weight:700;gap:10px;flex-shrink:0"
          onmouseover="this.style.opacity='.9'" onmouseout="this.style.opacity='1'">
          <span>🏭 Todas as Centrais</span>
          <span style="font-size:11px;opacity:.7">${abertas.length} ocorrência${abertas.length!==1?'s':''} no total</span>
        </button>
        <div style="font-size:11px;color:var(--text3);text-transform:uppercase;letter-spacing:.06em;margin:4px 0 2px;padding:0 2px;flex-shrink:0">ou escolha uma central</div>
        ${opcoesHtml}
      </div>
      <div style="display:flex;justify-content:flex-end;margin-top:8px;flex-shrink:0">
        <button class="btn" onclick="document.getElementById('oc-rel-central-modal').classList.remove('open')">Cancelar</button>
      </div>
    </div>`;

  modal.classList.add('open');
};

// ═══════════════════════════════════════════════════════════════════════════════
// RELATÓRIO GIRO POR USINA — Giro & Cobertura de cada central, e DENTRO de cada
// central cada material dela (mesmo detalhamento da Visão Micro do Analítico),
// com uma aba por mês selecionado.
//
// TEMPORÁRIO (ago/2026): pedido do Hugo como relatório provisório, com botão
// próprio no cabeçalho do Dashboard Gerencial — separado do "Relatório
// Gerencial", que continua sendo o da Visão Geral. Se virar permanente, o
// caminho natural é entrar como uma aba do _RELATORIO_ABAS_REGISTRY.
//
// Números: TUDO vem de buildGiroPorCentralMaterial (dashboard.js) — giro,
// cobertura, nível e variação nunca são recalculados aqui, só reformatados com
// cores literais (o HTML exportado não tem as CSS vars do app).
//
// ponytail: cada mês roda buildDashboardGerencialResults do zero (varredura
// completa do state). Com muitos meses × muitas centrais a geração fica lenta;
// upgrade = cachear o resultado por mês se alguém reclamar.
// ═══════════════════════════════════════════════════════════════════════════════

const _dgmState = {
  viewYear: new Date().getFullYear(),
  // Chaves "ano-mes" (mes 0-based). As abas saem sempre ordenadas por data,
  // independente da ordem em que o usuário clicou.
  selecionados: new Set()
};

function _dgmMesKey(ano, mes)   { return `${ano}-${mes}`; }
function _dgmMesLabel(ano, mes) { return `${MESES_ABREV_DG[mes]}/${ano}`; }
function _dgmMesesOrdenados() {
  return [..._dgmState.selecionados]
    .map(k => { const [a, m] = k.split('-').map(Number); return { ano: a, mes: m }; })
    .sort((x, y) => x.ano - y.ano || x.mes - y.mes);
}

// ── Modal de seleção de meses ──────────────────────────────────────────────
function _dgmInjetarEstilo() {
  if (document.getElementById('rel-giro-usina-style')) return;
  const style = document.createElement('style');
  style.id = 'rel-giro-usina-style';
  style.textContent = `
    .dgm-mes-grid { display:grid; grid-template-columns:repeat(4,1fr); gap:6px; }
    .dgm-mes-btn { padding:8px 0; border:1px solid var(--border); border-radius:8px; background:var(--bg2);
                   color:var(--text2); font-size:12px; font-weight:600; cursor:pointer; }
    .dgm-mes-btn.sel { background:var(--accent); border-color:var(--accent); color:#fff; }
    .dgm-nav { display:flex; align-items:center; justify-content:space-between; margin-bottom:10px; }
    .dgm-nav strong { font-size:13px; }
  `;
  document.head.appendChild(style);
}

window.abrirModalRelatorioGiroUsina = function() {
  _dgmInjetarEstilo();

  let modal = document.getElementById('rel-giro-usina-modal');
  if (!modal) {
    modal = document.createElement('div');
    modal.id = 'rel-giro-usina-modal';
    modal.className = 'modal-overlay';
    modal.style.cssText = 'z-index:3200';
    document.body.appendChild(modal);
  }

  // Abre já com o mês do Dashboard marcado — é o caso comum ("este mês e mais
  // alguns anteriores") e evita abrir sem nada selecionado.
  if (!_dgmState.selecionados.size && typeof _dgMonthState === 'object') {
    _dgmState.viewYear = _dgMonthState.selectedYear;
    _dgmState.selecionados.add(_dgmMesKey(_dgMonthState.selectedYear, _dgMonthState.selectedMonth));
  }

  modal.innerHTML = `
    <div class="modal" style="max-width:400px;width:92vw">
      <div class="modal-title" style="display:flex;align-items:center;gap:10px">
        <i class="ti ti-building-factory-2" style="color:var(--accent)"></i>
        Giro por Usina
      </div>
      <div class="modal-sub">Escolha os meses. Cada mês vira uma aba do relatório, com todas as centrais e os materiais de cada uma.</div>
      <div id="dgm-mes-picker" style="margin:14px 0"></div>
      <div style="display:flex;justify-content:space-between;gap:10px">
        <button class="btn" onclick="document.getElementById('rel-giro-usina-modal').classList.remove('open')">Cancelar</button>
        <button class="btn btn-primary" onclick="gerarRelatorioGiroUsina()">
          <i class="ti ti-file-analytics"></i> Gerar Relatório
        </button>
      </div>
    </div>`;

  _dgmRenderPicker();
  modal.classList.add('open');
};

function _dgmRenderPicker() {
  const el = document.getElementById('dgm-mes-picker');
  if (!el) return;
  const y = _dgmState.viewYear;
  const botoes = MESES_ABREV_DG.map((nome, i) => {
    const sel = _dgmState.selecionados.has(_dgmMesKey(y, i)) ? ' sel' : '';
    return `<button type="button" class="dgm-mes-btn${sel}" onclick="_dgmToggleMes(${i})">${nome}</button>`;
  }).join('');
  const escolhidos = _dgmMesesOrdenados();
  el.innerHTML = `
    <div class="dgm-nav">
      <button class="btn" style="padding:4px 8px" onclick="_dgmNavAno(-1)"><i class="ti ti-chevron-left"></i></button>
      <strong>${y}</strong>
      <button class="btn" style="padding:4px 8px" onclick="_dgmNavAno(1)"><i class="ti ti-chevron-right"></i></button>
    </div>
    <div class="dgm-mes-grid">${botoes}</div>
    <div style="margin-top:10px;font-size:11.5px;color:var(--text3)">
      ${escolhidos.length ? escolhidos.map(m => _dgmMesLabel(m.ano, m.mes)).join(' · ') : 'Nenhum mês selecionado'}
    </div>`;
}

window._dgmNavAno = function(dir) { _dgmState.viewYear += dir; _dgmRenderPicker(); };
window._dgmToggleMes = function(mes) {
  const k = _dgmMesKey(_dgmState.viewYear, mes);
  if (!_dgmState.selecionados.delete(k)) _dgmState.selecionados.add(k);
  _dgmRenderPicker();
};

// ── Montagem do HTML ───────────────────────────────────────────────────────
// Uma linha serve tanto pro total da central (em destaque) quanto pros
// materiais dela. O painel de leitura do abastecimento (alto giro = risco de
// ruptura, baixo giro = capital parado) é decidido pelo próprio giro da linha,
// mesma regra de buildGiroRow na tela.
// Cobertura em dias → cor + ícone. MESMOS limiares e ícones de
// buildCoberturaCell (função interna de renderDgGiro, dashboard.js, não
// acessível globalmente), só com cores literais em vez de var(--x) — mesmo
// arranjo que _dgrAbastInfo já usa pro abastecimento.
function _dgmCoberturaInfo(dias) {
  if (dias === null || dias === undefined) return { texto: 'sem consumo', cor: '#64748b', icone: null };
  const d = dias.toFixed(1) + 'd';
  if (dias < 5)   return { texto: d, cor: '#f43f5e', icone: 'ti-flame' };           // crítico
  if (dias < 10)  return { texto: d, cor: '#f59e0b', icone: 'ti-alert-triangle' };  // urgente
  if (dias < 20)  return { texto: d, cor: '#10b981', icone: 'ti-circle-check' };    // saudável
  if (dias <= 40) return { texto: d, cor: '#f59e0b', icone: 'ti-clock' };           // atenção
  return { texto: d, cor: '#8b5cf6', icone: 'ti-lock' };                            // excesso
}

// Uma linha por MATERIAL. A central não tem linha própria: o cabeçalho do
// bloco já carrega o retrato dela (variação, contagem por nível, giro).
// data-material/data-nivel são o que os filtros consomem.
//
// Nível, Abast., Giro e Cobertura saem como badge — as quatro colunas
// qualitativas, todas no mesmo _dgmChip dos chips do cabeçalho. Entradas,
// Saídas, Est.Médio e Variação seguem número puro: são grandeza, não estado.
function _dgmLinhaHtml(item) {
  const cor    = _dgrNivelCor(item.nivel.level);
  const abast  = _dgrAbastInfo(item.entradas, item.saidas, item.giro >= 1 ? 'alto' : 'baixo');
  const cob    = _dgmCoberturaInfo(item.cobertura);
  const corVar = _dgrValCor(item.variacao);
  return `
    <tr data-material="${_rankEsc(item.name)}" data-nivel="${item.nivel.level}">
      <td class="rk-name" title="${_rankEsc(item.name)}">
        <span class="dgr-nome-trunc-inner"><i class="ti ${_DGM_NIVEL_ICONE[item.nivel.level]} dgm-nome-icone" style="color:${cor}"></i>${_rankEsc(_dgrTruncNome(item.name, 30))}</span>
      </td>
      <td>${_dgmChip(_rankEsc(item.nivel.label), cor)}</td>
      <td class="rk-num" style="color:#94a3b8">${_dgrNowrapNum(fmtKg(item.entradas))}</td>
      <td class="rk-num" style="color:#94a3b8">${_dgrNowrapNum(fmtKg(item.saidas))}</td>
      <td>${_dgmChip(abast.texto, abast.cor, abast.icone)}</td>
      <td class="rk-num" style="color:#94a3b8">${_dgrNowrapNum(fmtKg(item.estMedio))}</td>
      <td>${_dgmChip(item.giro.toFixed(2) + '×', _dgrGiroCor(item.giro))}</td>
      <td>${_dgmChip(cob.texto, cob.cor, cob.icone)}</td>
      <td class="rk-num" style="color:${corVar}">${varSymbol(item.variacao)} ${_dgrNowrapNum(fmtKg(Math.abs(item.variacao)))}</td>
    </tr>`;
}

// ── Colunas da tabela: rótulo, largura e a explicação ─────────────────────
// FONTE ÚNICA — daqui saem o <thead>, o "?" de cada coluna e a legenda do
// rodapé. Descrever a conta em dois lugares diferentes era garantia de que um
// dos dois ficaria desatualizado.
//
// Larguras dimensionadas pros kg POR EXTENSO ("1.234.567,00 kg"): as colunas
// de peso ficam mais largas que o nome, que tem ellipsis e aguenta o aperto.
// Precisam somar 100.
const _DGM_COLUNAS = [
  { label: 'Material', largura: 19,
    calculo: 'Material cadastrado com movimentação ou saldo na central, no mês da aba.' },

  { label: 'Nível', largura: 8,
    calculo: 'Combina Cobertura, Giro e Abastecimento. Cada eixo vira um peso de 0 a 3; o nível parte do PIOR dos três (o elo mais fraco decide) e sobe um degrau quando dois ou mais eixos já estão em 2 ou mais — problema correlacionado pesa mais que problema isolado.',
    faixas: [
      ['Bom',     'os três eixos equilibrados'],
      ['Atenção', 'um eixo levemente fora da faixa saudável'],
      ['Urgente', 'um eixo ruim, ou dois em alerta ao mesmo tempo'],
      ['Crítico', 'pior caso de algum eixo, ou mais de um eixo ruim junto'],
    ] },

  { label: 'Entradas', largura: 12,
    calculo: 'Soma dos lançamentos SAP positivos do material no mês. É o que entrou de fato na central.' },

  { label: 'Saídas', largura: 12,
    calculo: 'Soma dos lançamentos SAP negativos do material no mês, em módulo. É o consumo do período.' },

  { label: 'Abast.', largura: 10,
    calculo: 'Entradas ÷ Saídas × 100 — o abastecimento acompanhou o consumo? A MESMA porcentagem é lida de forma diferente conforme o giro: com giro ≥ 1 (consumo alto) o risco é ruptura, então repor menos que o consumo é grave; com giro < 1 (consumo baixo) o risco é acúmulo, então repor muito acima do consumo é que preocupa.',
    faixas: [
      ['Giro ≥ 1 · 100% ou mais',   'abastecimento cobre o consumo'],
      ['Giro ≥ 1 · 80% a 100%',     'no limite'],
      ['Giro ≥ 1 · abaixo de 80%',  'risco de ruptura'],
      ['Giro < 1 · acima de 150%',  'excesso — capital imobilizado'],
      ['Giro < 1 · 100% a 150%',    'abastecimento acima do consumo'],
      ['Giro < 1 · 80% a 100%',     'equilibrado'],
      ['Giro < 1 · abaixo de 80%',  'consumo supera o abastecimento'],
      ['Entradas sem consumo',      'acúmulo — entrou e não saiu nada'],
      ['Sem movimentação',          'eixo ignorado no cálculo do nível'],
    ] },

  { label: 'Est.Médio', largura: 12,
    calculo: '(Est. Inicial + Est. Final) ÷ 2 — o estoque médio mantido no mês. O Est. Inicial é o saldo TEÓRICO do SAP em véspera do período (âncora de Custos SAP + movimentações) e o Est. Final é o último lançamento do período, exatamente as duas pontas que a Visão Micro do Analítico mostra. É o divisor do Giro e o dividendo da Cobertura, então material que começa o mês com estoque não infla mais esses dois.' },

  { label: 'Giro', largura: 6,
    calculo: 'Saídas ÷ Est. Médio — quantas vezes o estoque se renovou no mês. Alto demais indica operação no limite (risco de ruptura); baixo demais, capital parado.',
    faixas: [
      ['acima de 4,00×',    'muito alto — risco de ruptura'],
      ['2,00× a 4,00×',     'alto — operação enxuta'],
      ['1,00× a 2,00×',     'saudável'],
      ['0,50× a 1,00×',     'baixo — atenção com excesso'],
      ['0,20× a 0,50×',     'muito baixo — estoque elevado'],
      ['abaixo de 0,20×',   'parado — capital imobilizado'],
    ] },

  { label: 'Cobertura', largura: 9,
    calculo: 'Est. Médio ÷ Saídas × dias do período — para quantos dias o estoque médio daria, mantido o consumo do mês. Os dias do período são medidos entre o primeiro e o último lançamento encontrado, não pelo calendário.',
    faixas: [
      ['menos de 5 dias',   'crítico'],
      ['5 a 10 dias',       'urgente'],
      ['10 a 20 dias',      'saudável'],
      ['20 a 40 dias',      'atenção — possível excesso'],
      ['mais de 40 dias',   'excesso — estoque parado'],
      ['sem consumo',       'não calculável; tratado como sinal máximo no nível'],
    ] },

  { label: 'Variação', largura: 12,
    calculo: 'Est. Final real − Est. Teórico, sendo o Teórico = Est. Inicial + Entradas + Saídas. O Est. Inicial vem do saldo TEÓRICO do SAP (âncora de Custos SAP + movimentações), então a variação mede o quanto o físico está distante do livro do SAP — mesma conta da Visão Micro do Analítico.',
    faixas: [
      ['Negativa (desfalque)', 'falta estoque em relação ao que o SAP diz'],
      ['Positiva (sobra)',     'sobra estoque em relação ao que o SAP diz'],
    ] },
];

// Texto do "?" — title nativo, multi-linha via &#10; (mesmo recurso que a
// tabela de giro do dashboard já usa). Sem JS, funciona offline e não some se
// o arquivo for aberto de um pendrive.
function _dgmAjudaTexto(col) {
  const linhas = [`${col.label} — como é calculado`, '', col.calculo];
  if (col.faixas) {
    linhas.push('', 'O que cada valor significa:');
    col.faixas.forEach(([faixa, significado]) => linhas.push(`  • ${faixa}: ${significado}`));
  }
  return _rankEsc(linhas.join('\n')).replace(/\n/g, '&#10;');
}

function _dgmCentralTabelaHtml(c) {
  const linhas = c.mats.map(_dgmLinhaHtml).join('');
  // Cabeçalhos à ESQUERDA (padrão do .rk-table th do shell, só não
  // sobrescrever) com valores centralizados — mesmo desenho da Visão Micro.
  const cabecalho = _DGM_COLUNAS.map(col => `
    <th style="width:${col.largura}%">${_rankEsc(col.label)}<span class="dgm-help" title="${_dgmAjudaTexto(col)}">?</span></th>`
  ).join('');
  return `
    <div class="dgr-table-wrap">
      <table class="rk-table dgm-tabela">
        <thead><tr>${cabecalho}</tr></thead>
        <tbody>${linhas}</tbody>
      </table>
    </div>`;
}

// ── Legenda ────────────────────────────────────────────────────────────────
// Mesma fonte do "?" (_DGM_COLUNAS), em bloco recolhível: o "?" serve pra tirar
// a dúvida pontual na hora, a legenda serve pra quem vai ler o relatório
// inteiro — e é ela que sai no papel, já que tooltip não imprime.
function _dgmLegendaHtml() {
  // Glossário, não cards: rótulo à esquerda, explicação à direita, cada
  // entrada com a altura do próprio conteúdo. Em grade de cards o "Material"
  // (uma frase) herdava a altura do "Abast." (oito faixas) e sobrava vão.
  // As faixas vão em linha, separadas por ·, em vez de lista com marcador —
  // oito itens viram duas linhas em vez de oito.
  const itens = _DGM_COLUNAS.map(col => `
    <div class="dgm-leg-item">
      <div class="dgm-leg-titulo">${_rankEsc(col.label)}</div>
      <div class="dgm-leg-corpo">
        <span class="dgm-leg-calculo">${_rankEsc(col.calculo)}</span>
        ${col.faixas ? `<span class="dgm-leg-faixas">${col.faixas.map(([f, sig]) =>
          `<span class="dgm-leg-faixa"><b>${_rankEsc(f)}</b> ${_rankEsc(sig)}</span>`).join(' ')}</span>` : ''}
      </div>
    </div>`).join('');

  return `
    <section class="dgm-legenda">
      <button type="button" class="dgr-collapse-toggle dgm-legenda-head" aria-expanded="false" onclick="_dgrToggleSecao(this)">
        <i class="ti ti-chevron-down"></i>
        <span>Legenda — como cada coluna é calculada e o que os níveis significam</span>
      </button>
      <div class="dgr-collapse-body dgr-collapsed">
        <div class="dgm-leg-lista">${itens}</div>
      </div>
    </section>`;
}

// ── Cabeçalho da central — mesmo desenho do card da Visão Micro: nome em
//    destaque seguido de chips coloridos (variação, custo, contagem de
//    materiais por nível, giro). Chips zerados ficam esmaecidos em vez de
//    sumirem, igual ao .hcc-zero da Micro: "0 urgente" é informação, não
//    ausência de informação.
// Um ícone por nível, usado nos chips do cabeçalho E na frente do nome do
// material (mesmo par ícone+cor da Visão Micro, então bate a leitura entre as
// duas telas).
const _DGM_NIVEL_ICONE = {
  critico: 'ti-flame',
  urgente: 'ti-alert-circle',
  atencao: 'ti-alert-triangle',
  bom:     'ti-circle-check',
};

function _dgmChip(texto, cor, icone, zero) {
  return `<span class="dgm-chip"${zero ? ' data-zero="1"' : ''} style="background:${cor}1f;color:${cor};border-color:${cor}4d">${icone ? `<i class="ti ${icone}"></i>` : ''}${texto}</span>`;
}

function _dgmCentralHeaderHtml(c) {
  const cont = { critico: 0, urgente: 0, atencao: 0, bom: 0 };
  c.mats.forEach(m => { cont[m.nivel.level]++; });

  const corVar   = _dgrValCor(c.variacao);
  const neutro   = Math.abs(c.variacao) <= 0.0001;
  const rotuloVar = neutro ? 'Equilibrado' : (c.variacao < 0 ? 'Desfalque' : 'Sobra');
  const iconeVar  = neutro ? 'ti-equal' : (c.variacao < 0 ? 'ti-trending-down' : 'ti-trending-up');
  const corNivel  = _dgrNivelCor(c.nivel.level);

  return `
    <i class="ti ti-chevron-down dgm-chev"></i>
    <span class="dgm-central-nome"><i class="ti ti-building-factory-2"></i>${_rankEsc(c.name)}</span>
    ${_dgmChip(`${rotuloVar}: ${fmtKg(Math.abs(c.variacao))}`, corVar, iconeVar)}
    <span class="dgm-chip-sep"></span>
    ${_dgmChip(`${cont.critico} crítico`, _dgrNivelCor('critico'), _DGM_NIVEL_ICONE.critico, !cont.critico)}
    ${_dgmChip(`${cont.urgente} urgente`, _dgrNivelCor('urgente'), _DGM_NIVEL_ICONE.urgente, !cont.urgente)}
    ${_dgmChip(`${cont.atencao} atenção`, _dgrNivelCor('atencao'), _DGM_NIVEL_ICONE.atencao, !cont.atencao)}
    ${_dgmChip(`${cont.bom} bom`,         _dgrNivelCor('bom'),     _DGM_NIVEL_ICONE.bom,     !cont.bom)}
    <span class="dgm-chip-sep"></span>
    ${_dgmChip(`Giro ${c.giro.toFixed(2)}× · ${c.nivel.label.toUpperCase()}`, corNivel, 'ti-arrows-exchange')}`;
}

// ── Filtros gerais (central / material / nível) ────────────────────────────
// Valem pro relatório inteiro, todas as abas de mês — por isso ficam ACIMA da
// barra de abas. <select> nativo de propósito: o HTML exportado roda offline,
// sem framework nenhum, e a lista é curta o bastante pra não precisar de
// busca. Some na impressão (o papel já sai filtrado).
function _dgmFiltrosHtml(centrais, materiais) {
  const opcoes = (arr) => arr.map(v => `<option value="${_rankEsc(v)}">${_rankEsc(v)}</option>`).join('');
  const niveis = [['critico','Crítico'], ['urgente','Urgente'], ['atencao','Atenção'], ['bom','Bom']];
  return `
    <div class="dgm-filtros">
      <label>Central
        <select id="dgm-f-central" onchange="_dgmAplicarFiltros()">
          <option value="">Todas</option>${opcoes(centrais)}
        </select>
      </label>
      <label>Material
        <select id="dgm-f-material" onchange="_dgmAplicarFiltros()">
          <option value="">Todos</option>${opcoes(materiais)}
        </select>
      </label>
      <label>Nível
        <select id="dgm-f-nivel" onchange="_dgmAplicarFiltros()">
          <option value="">Todos</option>${niveis.map(([v, l]) => `<option value="${v}">${l}</option>`).join('')}
        </select>
      </label>
      <button type="button" class="dgm-f-btn" onclick="_dgmLimparFiltros()">
        <i class="ti ti-filter-off"></i> Limpar
      </button>
      <button type="button" class="dgm-f-btn" id="dgm-toggle-tudo" onclick="_dgmAlternarTudo(this)">
        <i class="ti ti-chevrons-up"></i> Recolher tudo
      </button>
      <span class="dgm-f-resumo" id="dgm-f-resumo"></span>
    </div>`;
}

// Script embutido no relatório. Vai no FIM do bodyHtml, com o DOM que ele
// consulta já parseado.
//
// O filtro de material/nível esconde LINHA de material; a linha de total da
// central e os chips do cabeçalho continuam mostrando a central inteira, de
// propósito — são o retrato do conjunto, não do recorte. Uma central sem
// nenhum material visível some por completo.
function _dgmScriptFiltros() {
  return `<script>
function _dgmAplicarFiltros() {
  var fc = document.getElementById('dgm-f-central').value;
  var fm = document.getElementById('dgm-f-material').value;
  var fn = document.getElementById('dgm-f-nivel').value;
  var filtraLinha = !!(fm || fn);
  var centraisVisiveis = 0, linhasVisiveis = 0;

  document.querySelectorAll('.dgm-secao').forEach(function(sec) {
    var okCentral = !fc || sec.dataset.central === fc;
    var visiveis = 0;
    sec.querySelectorAll('tr[data-material]').forEach(function(tr) {
      var ok = okCentral
        && (!fm || tr.dataset.material === fm)
        && (!fn || tr.dataset.nivel === fn);
      tr.style.display = ok ? '' : 'none';
      if (ok) visiveis++;
    });
    // Sem filtro de linha, uma central sem materiais ainda deve aparecer.
    var mostra = okCentral && (visiveis > 0 || !filtraLinha);
    sec.style.display = mostra ? '' : 'none';
    if (mostra) { centraisVisiveis++; linhasVisiveis += visiveis; }
  });

  var resumo = document.getElementById('dgm-f-resumo');
  if (resumo) {
    resumo.textContent = (fc || fm || fn)
      ? centraisVisiveis + (centraisVisiveis === 1 ? ' central' : ' centrais') + ' · ' + linhasVisiveis + (linhasVisiveis === 1 ? ' material' : ' materiais')
      : '';
  }
}
function _dgmLimparFiltros() {
  ['dgm-f-central', 'dgm-f-material', 'dgm-f-nivel'].forEach(function(id) {
    var el = document.getElementById(id);
    if (el) el.value = '';
  });
  _dgmAplicarFiltros();
}
// Alterna TODAS as centrais de uma vez. O alvo é decidido pelo estado atual —
// se sobrou alguma expandida, recolhe todas; senão expande. Assim o botão faz
// o que promete mesmo depois do usuário abrir/fechar centrais no dedo.
// Mesmo contrato de DOM do _dgrToggleSecao (corpo = irmão seguinte).
function _dgmAlternarTudo(btn) {
  var cabecalhos = [].slice.call(document.querySelectorAll('.dgm-central-head'));
  if (!cabecalhos.length) return;
  var recolher = cabecalhos.some(function(b) { return b.getAttribute('aria-expanded') === 'true'; });
  cabecalhos.forEach(function(b) {
    b.setAttribute('aria-expanded', recolher ? 'false' : 'true');
    if (b.nextElementSibling) b.nextElementSibling.classList.toggle('dgr-collapsed', recolher);
  });
  btn.innerHTML = recolher
    ? '<i class="ti ti-chevrons-down"><\/i> Expandir tudo'
    : '<i class="ti ti-chevrons-up"><\/i> Recolher tudo';
}
<\/script>`;
}

// ── Abas do relatório ──────────────────────────────────────────────────────
// Uma por mês selecionado, mais a "Geral" na frente quando há mais de um mês.
//
// A Geral NÃO soma as abas de mês — ela roda o MESMO cálculo sobre o período
// inteiro, de uma vez. Somar mês a mês erraria em dois pontos: Est.Médio é um
// nível de estoque, não um acumulado (somar 3 meses de 200 kg daria 600 kg de
// "estoque médio"), e a Variação mede divergência ACUMULADA contra o SAP —
// uma diferença não ajustada reaparece nos meses seguintes (ver
// _anGetSapTheoreticalStock em analitico.js), então somá-la contaria a mesma
// diferença física várias vezes. Recalculando sobre o intervalo todo, giro,
// cobertura e variação saem pelo mesmo caminho de sempre, sem heurística.
//
// Atenção: o intervalo é do 1º dia do mês mais antigo ao último do mais novo.
// Com meses não contíguos selecionados (ex.: Jan e Jun), a Geral cobre TAMBÉM
// os meses do meio — por isso o subtítulo dela traz as datas por extenso.
function _dgmAbasDoRelatorio(meses) {
  const abas = meses.map(m => ({
    id: `mes-${m.ano}-${m.mes}`,
    rotulo: _dgmMesLabel(m.ano, m.mes),
    icone: 'ti-calendar-month',
    titulo: `${MESES_NOME_DG[m.mes]} de ${m.ano}`,
    dtIni: new Date(m.ano, m.mes, 1),
    dtFim: new Date(m.ano, m.mes + 1, 0, 23, 59, 59),
    vazio: 'Sem dados neste mês.',
  }));

  if (abas.length > 1) {
    const dtIni = abas[0].dtIni;
    const dtFim = abas[abas.length - 1].dtFim;
    abas.unshift({
      id: 'geral',
      rotulo: 'Geral',
      icone: 'ti-sum',
      titulo: `Geral — ${dtIni.toLocaleDateString('pt-BR')} a ${dtFim.toLocaleDateString('pt-BR')}`,
      dtIni, dtFim,
      vazio: 'Sem dados no período.',
    });
  }
  return abas;
}

function _dgmPaneHtml(aba, dados, ativa) {
  // Uma seção por central: recolhível na tela e página nova na impressão
  // (dgr-page-section-natural = quebra antes, mas pagina livre por dentro —
  // uma central com muitos materiais não cabe numa página só).
  const secoes = dados.centrais.map((c, i) => `
    <section class="dgr-page-section-natural dgm-secao" data-secao-id="${aba.id}-${i}" data-central="${_rankEsc(c.name)}">
      <button type="button" class="dgr-collapse-toggle dgm-central-head" aria-expanded="true" onclick="_dgrToggleSecao(this)">
        ${_dgmCentralHeaderHtml(c)}
      </button>
      <div class="dgr-collapse-body">${_dgmCentralTabelaHtml(c)}</div>
    </section>`).join('');

  const nCent = dados.centrais.length;
  const nDias = dados.periodoEstimado;
  return `<div class="rel-aba-pane${ativa ? ' rel-aba-ativa' : ''}" data-aba-id="${aba.id}">
    <div class="dgr-section-title"><i class="ti ${aba.icone}"></i>${_rankEsc(aba.titulo)} — ${nCent} ${nCent !== 1 ? 'centrais' : 'central'} · ${nDias} ${nDias !== 1 ? 'dias' : 'dia'} de movimentação</div>
    ${secoes || `<div class="dgr-chart-empty">${_rankEsc(aba.vazio)}</div>`}
  </div>`;
}

// A aba abre ANTES do cálculo, já mostrando progresso — não por preferência,
// por imposição do navegador: window.open só é liberado enquanto a ativação
// transitória do clique está viva (~5s), e esse relógio corre mesmo com a
// thread ocupada. Este relatório varre o state inteiro por mês, com dois
// buildSnapshot por material, e passa fácil desse orçamento com dados reais —
// tentar abrir no fim dava "Popups bloqueados". Ver _abrirJanelaRelatorio.
//
// Com a aba já aberta, dá pra ceder a thread entre os meses de novo, então o
// progresso aparece de verdade — na aba e no overlay da página.
window.gerarRelatorioGiroUsina = async function() {
  const meses = _dgmMesesOrdenados();
  if (!meses.length) { toast('Selecione ao menos um mês.', 'error'); return; }

  const nMeses = meses.length;
  const abas   = _dgmAbasDoRelatorio(meses);
  const nAbas  = abas.length;

  const janela = _abrirJanelaRelatorio(`0 de ${nAbas} — ${abas[0].titulo}`);
  if (!janela) return;

  document.getElementById('rel-giro-usina-modal')?.classList.remove('open');

  const step  = (id, st) => { if (typeof _lstepSet === 'function') _lstepSet(id, st); };
  const barra = pct => { if (typeof _lbarSet === 'function') _lbarSet(pct); };

  if (typeof showLoadingOverlay === 'function') {
    showLoadingOverlay('Gerando relatório', `Giro por usina — ${nMeses} ${nMeses !== 1 ? 'meses' : 'mês'}`);
  }
  // Etapas próprias: sem isso o overlay reaproveita as que ficaram penduradas
  // no DOM da última vez que alguém as usou (o boot do sistema), e o usuário vê
  // "Restaurando sessão anterior" ao gerar um relatório.
  if (typeof loadingShowSteps === 'function') {
    loadingShowSteps([
      ...abas.map(a => ({ id: `giro-usina-${a.id}`, icon: a.icone, label: a.titulo })),
      { id: 'giro-usina-montar', icon: 'ti-file-analytics', label: 'Montando o relatório' }
    ]);
  }

  try {
    const porAba = [];
    for (let i = 0; i < nAbas; i++) {
      const aba = abas[i];
      step(`giro-usina-${aba.id}`, 'running');
      barra(Math.round((i / (nAbas + 1)) * 100));
      _janelaRelatorioProgresso(janela, `${i} de ${nAbas} — ${aba.titulo}`);
      // Cede a thread pro overlay e pra aba repintarem antes do cálculo travá-la.
      await new Promise(r => setTimeout(r, 0));

      porAba.push({ aba, dados: buildGiroPorCentralMaterial(aba.dtIni, aba.dtFim) });
      step(`giro-usina-${aba.id}`, 'done');
    }

    step('giro-usina-montar', 'running');
    barra(Math.round((nAbas / (nAbas + 1)) * 100));
    _janelaRelatorioProgresso(janela, 'Montando o relatório…');

    const panes = porAba.map(({ aba, dados }, i) => _dgmPaneHtml(aba, dados, i === 0)).join('');

    // Opções dos filtros: união de TODAS as abas (o filtro é geral), pra que
    // uma central que só aparece em um mês continue selecionável nos outros.
    const setCentrais = new Set(), setMateriais = new Set();
    porAba.forEach(({ dados }) => dados.centrais.forEach(c => {
      setCentrais.add(c.name);
      c.mats.forEach(m => setMateriais.add(m.name));
    }));
    const cmp = (a, b) => a.localeCompare(b, 'pt-BR');
    const filtros = _dgmFiltrosHtml([...setCentrais].sort(cmp), [...setMateriais].sort(cmp));

    const abasBar = nAbas > 1
      ? `<div class="rel-aba-bar">${abas.map((a, i) => `
          <button type="button" class="rel-aba-btn${i === 0 ? ' active' : ''}${a.id === 'geral' ? ' rel-aba-geral' : ''}" data-aba-id="${a.id}" onclick="_dgrSwitchAba('${a.id}', this)" title="${_rankEsc(a.titulo)}">
            <i class="ti ${a.icone}"></i> ${_rankEsc(a.rotulo)}
          </button>`).join('')}</div>`
      : '';

    const estilos = `
      /* Filtros gerais — somem na impressão: o papel já sai filtrado. */
      .dgm-filtros {
        display:flex; flex-wrap:wrap; align-items:flex-end; gap:12px; margin-bottom:16px;
        padding:12px 14px; border-radius:10px;
        background:var(--dgr-card-bg, rgba(255,255,255,.045));
        border:1px solid var(--dgr-card-border, rgba(255,255,255,.09));
      }
      .dgm-filtros label {
        display:flex; flex-direction:column; gap:5px;
        font-size:9px; font-weight:800; text-transform:uppercase; letter-spacing:.06em;
        color:var(--dgr-text-dim2, #64748b);
      }
      .dgm-filtros select, .dgm-f-btn {
        background:var(--dgr-card-bg, rgba(255,255,255,.06));
        border:1px solid var(--dgr-card-border, rgba(255,255,255,.14));
        color:var(--dgr-text, #e2e8f0);
        border-radius:6px; padding:6px 9px;
        font-family:'JetBrains Mono',monospace; font-size:10.5px; font-weight:600;
      }
      .dgm-filtros select { min-width:170px; max-width:280px; }
      .dgm-f-btn { display:inline-flex; align-items:center; gap:5px; cursor:pointer; font-weight:700; }
      .dgm-f-btn i { font-size:12px; }
      .dgm-f-resumo {
        font-family:'JetBrains Mono',monospace; font-size:10px;
        color:var(--dgr-text-dim, #94a3b8); margin-left:auto;
      }

      /* A Geral não é "mais um mês": separa ela do resto da barra de abas. */
      .rel-aba-geral { font-weight:800; }
      .rel-aba-geral + .rel-aba-btn { margin-left:10px; }
      @media print { .dgm-filtros { display:none; } }

      /* Tudo centralizado; só a coluna de nome (a 1ª) fica à esquerda —
         cabeçalho e valor sempre no mesmo eixo. */
      .dgm-tabela th, .dgm-tabela td { text-align:center; }
      .dgm-tabela th:first-child, .dgm-tabela td:first-child { text-align:left; }

      /* Corpo maior que o padrão de _dgrEstilos (7,5px), que foi calibrado pro
         Relatório Gerencial — lá são 4 tabelas espremidas na mesma página.
         Aqui é UMA tabela por central, em paisagem: sobra largura. nowrap nas
         células numéricas pra "1.234.567,00 kg" nunca largar o "kg" na linha
         de baixo; o nome fica com ellipsis, que é o único texto que pode
         faltar espaço. */
      .dgm-secao .dgm-tabela th { font-size:9.5px; padding:10px 6px; }
      .dgm-secao .dgm-tabela td { font-size:11px; padding:11px 6px; }
      .dgm-secao .dgm-tabela .rk-name { font-size:11.5px !important; font-weight:700; }
      .dgm-secao .dgm-tabela .rk-num { white-space:nowrap; }
      /* Badges dentro da tabela — mesmo .dgm-chip do cabeçalho, só com o ícone
         no tamanho da célula (o do cabeçalho tem regra própria, menor). */
      .dgm-tabela .dgm-chip i { font-size:11px; }

      /* "?" de cada coluna: title nativo, sem JS. Não imprime — no papel quem
         explica é a legenda. */
      .dgm-help {
        display:inline-flex; align-items:center; justify-content:center;
        width:12px; height:12px; margin-left:5px; border-radius:50%;
        border:1px solid var(--dgr-card-border, rgba(255,255,255,.22));
        color:var(--dgr-text-dim2, #64748b);
        font-size:8px; font-weight:800; line-height:1; cursor:help;
        vertical-align:middle;
      }
      .dgm-help:hover { color:var(--dgr-text, #e2e8f0); }

      /* Legenda — recolhida por padrão pra não empurrar os dados pra baixo. Na
         impressão o shell força .dgr-collapsed a aparecer, então ela sai no
         papel de qualquer jeito (é lá que ela mais importa: tooltip não
         imprime). */
      .dgm-legenda { margin:0 0 18px; }
      .dgm-legenda-head { margin-bottom:0; }
      .dgm-legenda .dgr-collapse-body {
        padding:14px 16px;
        background:var(--dgr-card-bg, rgba(255,255,255,.045));
        border:1px solid var(--dgr-card-border, rgba(255,255,255,.09));
        border-top:none; border-radius:0 0 10px 10px;
      }
      /* Uma entrada por linha: rótulo à esquerda, explicação à direita. Cada
         linha ocupa a altura do próprio conteúdo — em grade de cards todos
         herdavam a altura do maior e sobrava vão. */
      .dgm-leg-item {
        display:grid; grid-template-columns:88px 1fr; gap:0 14px;
        padding:8px 0; border-bottom:1px solid var(--dgr-divider, rgba(255,255,255,.07));
        page-break-inside:avoid;
      }
      .dgm-leg-item:last-child { border-bottom:none; padding-bottom:0; }
      .dgm-leg-item:first-child { padding-top:0; }
      .dgm-leg-titulo {
        font-size:9.5px; font-weight:800; text-transform:uppercase; letter-spacing:.05em;
        color:var(--dgr-accent-text, #f87171); padding-top:1px;
      }
      /* min-width:0 — sem isso o item de grid não encolhe abaixo do conteúdo
         (o padrão é min-width:auto) e uma linha longa empurra a coluna 1fr
         pra fora da tela, levando a página junto. */
      .dgm-leg-corpo { min-width:0; }
      .dgm-leg-calculo { font-size:10.5px; line-height:1.5; color:var(--dgr-text, #e2e8f0); }
      /* Faixas em linha, separadas por ·: oito itens viram duas linhas em vez
         de uma lista de oito. Só o rótulo da faixa é nowrap ("acima de 4,00×"
         não pode partir no meio); a descrição quebra à vontade. */
      .dgm-leg-faixas { display:block; margin-top:5px; }
      .dgm-leg-faixa {
        font-size:9.5px; font-family:'JetBrains Mono',monospace;
        color:var(--dgr-text-dim, #94a3b8); line-height:1.75;
      }
      .dgm-leg-faixa + .dgm-leg-faixa::before { content:' · '; color:var(--dgr-text-dim2, #64748b); }
      .dgm-leg-faixa b { color:var(--dgr-text, #e2e8f0); font-weight:700; white-space:nowrap; }
      @media print { .dgm-help { display:none; } }

      /* Zebra do shell DESLIGADA aqui, por dois motivos: ela pinta o <tr>
         enquanto o destaque da central pinta o <td>, e com o fundo do bloco
         por baixo davam três tons diferentes; e sendo :nth-child, alternava
         errado assim que um filtro escondia linha. Separação vira borda, que
         não depende de índice nem briga por camada. */
      .dgm-secao tbody tr:nth-child(even) { background:none; }
      .dgm-secao tbody td { background:none; }
      .dgm-secao tbody tr:last-child td { border-bottom:none; }

      /* A central é um bloco único envolvendo os materiais dela — mesmo
         desenho do .regional-group da Visão Micro (cabeçalho colado no corpo,
         cantos arredondados só nas pontas de fora). A tabela de dentro perde o
         visual de card próprio pra não virar card dentro de card. */
      /* O padding-top de 24px que vem de .dgr-page-section-natural existia pra
         separar seções sem moldura; aqui cada central já é um card com margem
         própria, então ele só somava vão — atrapalhava bastante com todas
         recolhidas. Na impressão a margem de @page é que dá o respiro. */
      .dgm-secao { padding-top:0; margin-bottom:10px; }
      .dgm-central-head {
        padding:11px 14px; margin-bottom:0;
        background:var(--dgr-card-bg, rgba(255,255,255,.045));
        border:1px solid var(--dgr-card-border, rgba(255,255,255,.09));
        border-bottom:none; border-radius:12px 12px 0 0;
      }
      .dgm-central-head[aria-expanded="false"] {
        border-bottom:1px solid var(--dgr-card-border, rgba(255,255,255,.09));
        border-radius:12px;
      }
      /* Mesmo --dgr-card-bg do cabeçalho: os dois viram um card contínuo. Era
         daqui que vinha a inversão no tema claro — o corpo usava --dgr-row-alt
         (cinza) e a linha da central --dgr-card-bg (branco puro), então o
         "destaque" saía mais claro que o fundo em volta. */
      .dgm-secao .dgr-collapse-body {
        border:1px solid var(--dgr-card-border, rgba(255,255,255,.09));
        border-top:none; border-radius:0 0 12px 12px;
        padding:4px 10px 8px;
        background:var(--dgr-card-bg, rgba(255,255,255,.045));
      }
      .dgm-secao .dgr-table-wrap {
        margin-bottom:0; padding:0; background:none; border:none; border-radius:0;
      }

      /* Cabeçalho da central — chips no padrão da Visão Micro. Sobrescreve o
         uppercase/letter-spacing herdado de .dgr-collapse-toggle, que deixaria
         os chips com cara de título em vez de etiqueta. */
      .dgm-central-head { flex-wrap:wrap; gap:7px; text-transform:none; letter-spacing:0; }
      .dgm-nome-icone { font-size:12px !important; margin-right:6px; vertical-align:-1.5px; }

      /* O shell gira QUALQUER <i> dentro de .dgr-collapse-toggle ao recolher
         (a regra foi escrita quando o botão só tinha a seta). Como aqui o
         cabeçalho leva os chips dentro do botão, os ícones deles giravam
         junto: a rotação passa a valer só pra seta. */
      .dgm-central-head[aria-expanded="false"] i { transform:none; }
      .dgm-central-head[aria-expanded="false"] .dgm-chev { transform:rotate(-90deg); }
      .dgm-central-nome {
        display:inline-flex; align-items:center; gap:6px; margin-right:4px;
        font-size:12px; font-weight:800; letter-spacing:.04em; text-transform:uppercase;
        color:var(--dgr-text-strong, #fff);
      }
      .dgm-central-nome i { font-size:13px; opacity:.7; }
      .dgm-chip {
        display:inline-flex; align-items:center; gap:5px;
        padding:2px 8px; border-radius:6px; border:1px solid transparent;
        font-family:'JetBrains Mono',monospace; font-size:9.5px; font-weight:700;
        white-space:nowrap; letter-spacing:0;
      }
      .dgm-chip[data-zero="1"] { opacity:.4; }
      /* .dgr-collapse-toggle i vale 14px pra seta; os ícones dos chips são menores. */
      .dgm-central-head .dgm-chip i { font-size:10px; }
      .dgm-chip-sep { width:1px; height:14px; background:var(--dgr-divider, rgba(255,255,255,.14)); margin:0 3px; }
      @media print {
        /* O shell esconde .dgr-collapse-toggle na impressão (botão não faz
           sentido no papel), mas aqui o cabeçalho É a identificação da central
           — sem ele a tabela vira uma lista de materiais sem dono. Fica
           visível; só a seta de recolher some. */
        .dgm-central-head { display:flex !important; }
        .dgm-central-head .dgm-chev { display:none; }
      }`;

    const ultimo  = meses[nMeses - 1];
    const periodo = nMeses === 1
      ? `${MESES_NOME_DG[meses[0].mes]} de ${meses[0].ano}`
      : `${_dgmMesLabel(meses[0].ano, meses[0].mes)} a ${_dgmMesLabel(ultimo.ano, ultimo.mes)}`;

    const html = _buildRankingShellHTML({
      periodoBadge: periodo,
      periodo,
      now: new Date().toLocaleString('pt-BR'),
      kpis: []
    }, {
      // Paisagem: 9 colunas não cabem em retrato sem espremer o nome do material.
      pageOrientation: 'paisagem',
      temaAlternavel: true,
      temaInicial: 'dark',
      permitirDownload: true,
      nomeArquivoDownload: _dgrNomeArquivoRelatorio('relatorio-giro-usina'),
      secoesRecolhiveis: true,
      abasNavegaveis: nMeses > 1,
      offlineCompleto: true,
      pageTitle: 'Giro por Usina — Dashboard Gerencial',
      badge:     'Relatório de Fornecimento',
      title:     'Giro & Cobertura por Usina',
      subtitle:  'Giro, cobertura e variação de cada central e de cada material dentro dela, mês a mês.',
      // Filtros e legenda ANTES da barra de abas (valem pro relatório inteiro)
      // e o script no fim, com o DOM que ele consulta já parseado.
      bodyHtml:  `<style>${_dgrEstilos()}${estilos}</style>${filtros}${_dgmLegendaHtml()}${abasBar}${panes}${_dgmScriptFiltros()}`,
      notaRodape: 'Giro e Cobertura seguem a mesma metodologia do modal "Giro & Cobertura" do Dashboard Gerencial. Variação = Est. Final real − Est. Teórico, com Est. Inicial no saldo teórico do SAP — mesma conta da Visão Micro do Analítico.'
    });

    step('giro-usina-montar', 'done');
    barra(100);
    // Substitui a tela de progresso pelo relatório pronto.
    _openRelWindow(html, janela);
  } catch (err) {
    console.error('[Relatório Giro por Usina] Falha ao gerar:', err);
    toast('Falha ao gerar o relatório. Veja o console para detalhes.', 'error');
    try { janela.close(); } catch (_) {} // não deixa a aba de progresso órfã
  } finally {
    if (typeof hideLoadingOverlay === 'function') hideLoadingOverlay();
    if (typeof loadingHideSteps === 'function') loadingHideSteps();
  }
};
